    [2199] = "Apporter 5 Barres d'Argent à Talvash del Kissel, à Forgefer.",
    [2200] = "Chercher des indices sur le Collier de Talvash à Uldaman. Le paladin dont il a parlé est la dernière personne à l'avoir porté.",
    [2201] = "Trouvez le rubis, le saphir et la topaze qui sont éparpillés à travers Uldaman. Une fois que vous les aurez, contactez Talvash del Kissel en utilisant la Fiole de divination qu’il vous a donnée précédemment. C'est dans le journal, vous savez... * Le rubis a été caché dans une zone barricadée des Ombreforge. * La topaze a été dissimulée dans une urne, dans l’une des zones trogg, pas très loin de nains de Alliance. * Le saphir est en possession du chef trogg, Grimlok.",
    [2202] = "Apporter 12 Champignons magenta à Jarkal Mossmeld à Kargath.",
    [2203] = "Utiliser les 3 Récipients thaumaturgiques vides sur des dragons gardiens des terres brûlées dans les Terres ingrates. Une fois remplis, les rapporter à Jarkal Mossmeld à Kargath.",
    [2204] = "Obtenir une Source d'énergie de la construction la plus puissante que vous pouvez trouver à Uldaman, puis la remettre à Talvash del Kissel à Forgefer.",
    [2205] = "Remettre le colis de Keryn Sylvius à maître Mathias Shaw à la Caserne de Hurlevent.",
    [2206] = "Trouver l'Intendant des docks défias et récupérer le programme d'embarquement, pour le compte de maître Mathias Shaw.",
    [2218] = "Parler à Hulfdan Blackbeard à Forgefer.",
    [2238] = "Trouver Onin MacHammar à Gnomeregan.",
    [2239] = "Porter le rapport d'Onin à Hulfdan à Forgefer.",
    [2240] = "Lire le journal de Baelog, explorer la Chambre secrète, puis rendre compte au Prospecteur Foudrepique.",
    [2241] = "Porter la fleur de Jannok à Syurna à Darnassus.",
    [2242] = "Trouver Sethir l’Ancien et rapporter tout indice découvert à Syurna.",
    [2258] = "Apporter 5 Gésiers de busard, 10 Crocs de coyote des rochers et 5 Fragments d'élémentaire de roche à Jarkal Mossmeld, à Kargath, dans les Terres ingrates.",
    [2259] = "Contacter Erion Shadewhisper à Darnassus.",
    [2260] = "Voyager vers Hurlevent pour y rencontrer Renzik \"le Kriss\".",
    [2278] = "Parler au Gardien des pierres pour connaître le Savoir qu'il défend. Une fois découvert ce qu'ils peuvent offrir, activer les Disques de Norgannon.",
    [2279] = "Apporter la version miniature des Disques de Norgannon à la Ligue des Explorateurs à Forgefer.",
    [2280] = "Apporter la version miniature des Disques de Norgannon à l'un des Sages de Thunder Bluff.",
    [2281] = "S'aventurer vers Comté-du-Lac dans les Carmines et parler à Lucius.",
    [2282] = "Ouvrir le Coffret de Lucius, récupérer le Gage de voleur et le rapporter à Lucius à Comté-du-Lac.",
    [2283] = "Rechercher dans l'excavation d'Uldaman un Collier de prix et le rapporter à Dran Droffers à Orgrimmar. Ce Collier peut être endommagé.",
    [2284] = "Trouver, dans les profondeurs d'Uldaman, des indices sur la localisation des Gemmes.",
    [2298] = "Aller à Hurlevent et chercher Renzik \"le Kriss\".",
    [2299] = "Se rendre à Forgefer et parler à Hulfdan Blackbeard.",
    [2300] = "Aller à Hurlevent et chercher Renzik \"le Kriss\".",
    [2318] = "Trouver quelqu'un qui puisse traduire le journal du paladin. L'endroit le plus proche est Kargath, dans les Terres ingrates.",
    [2338] = "Laisser Jarkal emprunter le Collier en échange de la traduction du Journal.",
    [2339] = "Récupérer, dans Uldaman, les trois gemmes et une source d’énergie pour le collier, puis les rapporter à Jarkal Mossmeld, à Kargath. Jarkal pense que vous pouvez trouver une source d’énergie sur la machine la plus puissante d’Uldaman. C'est dans le journal, vous savez... * Le rubis a été caché dans une zone barricadée des Ombreforge. * La topaze a été dissimulée dans une urne, dans l’une des zones trogg, pas très loin de nains de Alliance. * Le saphir est possession du chef trogg, Grimlok.",
    [2340] = "Apporter Les gemmes et le collier récupérés à Dran Droffers, à Orgrimmar.",
    [2341] = "Rendre visite à Jarkal Mossmeld à Kargath pour constater (ou non) son succès.",
    [2342] = "Rapporter à Patrick Garrett, à Fossoyeuse, son Trésor de famille, qui se trouve dans le Coffre de famille dans le Hall commun sud d'Uldaman.",
    [2359] = "Voler la Clé de la Tour défias, pénétrer dans la Tour et trouver ce que contient le Coffre du bois de la Pénombre. Rapporter les informations à Mathias Shaw à Hurlevent. Lire le journal de Kearnen pour savoir ce qui se passe dans la Tour.",
    [2360] = "Se rendre dans la marche de l'Ouest et trouver l'Agent Kearnen pour un débriefing.",
    [2378] = "Voyager vers Orgrimmar pour y parler à Shenthul, dans la Faille de l'ombre.",
    [2379] = "Parler à Zando'zan à la Faille de l'ombre.",
    [2380] = "S'adresser à Shenthul à la Faille de l'ombre à Orgrimmar.",
    [2381] = "Rapporter le Trésor des Mers du sud à Wrenix le Misérable à Ratchet. Ne pas oublier d’obtenir un B.G.A.C. et des Outils de voleur de l’Appareil bidulotronique de Wreni. Ces deux éléments sont nécessaires pour accomplir la mission. En cas d’attaque par des perroquets particulièrement hostiles, utiliser le B.G.A.C.!",
    [2382] = "Aller jusqu'à Ratchet pour voir Wrenix le Misérable.",
    [2383] = "Lire le Simple parchemin, et parler à Frang, dans la Vallée des épreuves.",
    [2398] = "Trouver Baelog dans Uldaman.",
    [2418] = "Apporter 8 Pierres de puissance Dentrium et 8 Pierres de puissance An'Alleum à Rigglefuzz dans les Terres ingrates.",
    [2438] = "Apporter le Capturêve d'émeraude à Tallonkai Swiftroot à Dolanaar.",
    [2439] = "Apporter le Bon de récompense à Dinita Stonemantle à la Chambre forte de Forgefer.",
    [2440] = "Apporter le Bon de récompense à Bena Winterhoof à Thunder Bluff.",
    [2458] = "Aller à la tour de la KapitalRisk, au nord de la Videfange, et contacter l'agent secret de la Main brisée, le sous-chef Fizzule. Une fois la tour en vue, utiliser le lance-fusées pour se signaler au sous-chef Fizzule. Tirer DEUX fusées, puis s'approcher du sous-chef Fizzule et faire le Salut brisé (/salut). Respecter l'ordre de ces actions, car Fizzule attaque et tue toute personne qu'il ne peut pas identifier.",
    [2459] = "Sur ordre de Tallonkai Swiftroot de Dolanaar, tuer 7 Mystiques Pins-tordus et retrouver le Bijou disparu.",
    [2460] = "Faire le Salut brisé à Shenthul.",
    [2478] = "Voler la Clé de la tour de Silixiz au contremaître Silixiz, puis tuer deux Pantins mutants de la KapitalRisk, deux Patrouilleurs de la KapitalRisk, et deux Sentinelles de la KapitalRisk. Assassiner le grand contremaître Gallywix et prendre sa tête. Ouvrir le coffre de Gallywix et y voler la Mixture altérée de Zanzil. Apporter la Mixture et la tête de Gallywix à Shenthul à Orgrimmar, et attendre de nouvelles instructions.",
    [2479] = "Aller à Moulin-de-Tarren dans les contreforts d'Hillsbrad et livrer l'Échantillon de la mixture de Zanzil à Serge Hinott. Pour rejoindre Moulin-de-Tarren, prenez le zeppelin à Fossoyeuse et suivez la route du sud, à travers les Pins argentés et vers Hillsbrad. Suivez les panneaux !",
    [2480] = "Attendre Serge Hinott pour achever le remède.",
    [2498] = "Sur ordre de Rellian Greenspyre, aller voir Denalan au lac Al'Ameth.",
    [2499] = "Sur ordre de Denalan du lac Al'Ameth, ôter la Tumeur gargantuesque de Froncechêne.",
    [2500] = "Aller chercher les réactifs dont Ghak Healtouch a besoin dans les Terres ingrates, puis les lui rapporter à Thelsamar.",
    [2501] = "Utiliser les Récipients thaumaturgiques vides sur des dragons gardiens des terres brûlées dans les Terres ingrates. Une fois remplis, les rapporter à Ghak Healtouch à Thelsamar.",
    [2518] = "Apporter les Filières d'argent de dame Sathrah à la prêtresse A'moora, au temple de la Lune, à Darnassus.",
    [2519] = "Sœur Aquinne veut que vous parliez à la prêtresse A'moora, au temple de la Lune.",
    [2520] = "Sur ordre de la prêtresse A'moora, placer les Filières d'argent de dame Sathrah dans la fontaine du Temple, puis retourner la voir.",
    [2521] = "Si vous trouvez une sphère de draenéthyste sans défaut au hasard des voyages dans les Terres foudroyées, apportez-la à Kum'isha le Collecteur. Cette gemme, l'une des plus rares de tout Azeroth, peut être détenue par n'importe qui dans le pays. Une récompense sera donnée pour chaque sphère de draenéthyste sans défaut trouvée et rapportée.",
