    [3117] = "Lire le Sceau gravé, et parler à Ayanna Everstride, au sommet d'Aldrassil, dans Sombrevallon.",
    [3118] = "Lire le Sceau codé et parler à Frahun Shadewhisper, à Sombrevallon.",
    [3119] = "Lire le Sceau béni, et parler à Shanda, à Aldrassil.",
    [3120] = "Lire le Sceau verdoyant, et parler à Mardant Strongoak, dans l'arbre Aldrassil de Sombrevallon.",
    [3121] = "Porter la tête réduite à Neeru Fireblade à Orgrimmar.",
    [3122] = "Livrer une Poche d'herbes de Neeru au Sorcier docteur Uzer'i, en Feralas.",
    [3123] = "Partez pour les Hinterlands et localisez les Indomptables. Tuez-en 10, puis utilisez le Récipient de muisek pour faire rétrécir et capturer les Indomptables vaincus. Ramenez 10 Indomptables miniaturisés et le Récipient d'Indomptables miniaturisés au sorcier-docteur Uzer'i, en Feralas.",
    [3124] = "Tuer 10 Hippogryphes Aigreplume de n'importe quel type, puis utiliser le Vaisseau de muisek pour les faire rétrécir et les capturer.",
    [3125] = "Tuer 8 Fées fléchetteuses ou Petits dragons féeriques. Utiliser le Vaisseau de muisek pour faire rétrécir et capturer les dragons féeriques vaincus.",
    [3126] = "Tuer 3 Marcheurs des bois errants. Utiliser le Vaisseau de muisek pour faire rétrécir et pour capturer les tréants vaincus.",
    [3127] = "Tuer 7 Marcheurs des terres ou Géants des falaises. Utiliser le Récipient de muisek pour faire rétrécir et pour capturer les Géants des montagnes.",
    [3128] = "Apporter 2 Bûches fendues, 6 Minerais incrustés, 20 Morceaux de tendons résistants et 40 Fragments métalliques au sorcier-docteur Uzer'i au Camp Mojache.",
    [3129] = "Le sorcier-docteur Uzer'i veut que vous patientez tandis qu'il prépare les armes.",
    [3130] = "Se présenter devant Latronicus Moonspear au bastion de Feathermoon.",
    [3141] = "Écouter l'histoire de Loramus Thalipedes.",
    [3161] = "Marvon Rivetseeker à Tanaris veut que vous collectiez 30 Ornements Gahz'ridian.",
    [3181] = "Porter la Corne Gigantesque de Margol à la Montagnarde Pebblebitty.",
    [3182] = "Porter la Corne gigantesque de Margol au conservateur en chef Thorius à Forgefer.",
    [3201] = "Apporter le document de preuve à la Montagnarde Pebblebitty.",
    [3221] = "Parler à l'apothicaire Renferrel au Sépulcre.",
    [3261] = "Parler à Jorn Skyseer, à Camp Taurajo.",
    [3281] = "Rapportez l'Argent volé à Gazrog à la Croisée.",
    [3301] = "Parler à Mura Runetotem au Sépulcre.",
    [3321] = "Attendre que Trenton ait terminé son travail.",
    [3341] = "Andrew Brownell veut que vous tuiez Amnennar le Porte-froid et que vous lui rameniez son crâne.",
    [3361] = "Apporter la Boîte de Felix, le Coffre de Felix et le Seau de boulons de Felix à Felix Whindlebolt, à Courbenclume.",
    [3362] = "Tran'rek, à Gadgetzan, voudrait que vous tuiez 8 Chardonniers noueux et 8 Chardonniers taille-racines.",
    [3364] = "Apporter un Thé brûlant à Durnan Furcutter, dans Courbenclume, dans les cinq minutes imparties avant qu'il ne refroidisse !",
    [3365] = "Apporter la Chope de Nori à Nori Pridedrift.",
    [3367] = "Aider Dorius à retourner à Forgefer.",
    [3368] = "Apporter la Lettre roussie à Thorius à Forgefer. Il se trouve dans le Hall des Explorateurs.",
    [3369] = "Apporter l'Eclat de cauchemar à Hamuul Runetotem à la Cime des Anciens.",
    [3370] = "Apporter l'Eclat de cauchemar à Mathrengyl Bearwalker à Darnassus.",
    [3371] = "Retourner à la Gorge des Vents brûlants et trouver l'Equipe d'archéologues de Dorius.",
    [3372] = "Trouver l'Artefact mystérieux gardé par le Marteau du crépuscule au nord.",
    [3373] = "Placer l'Essence d'Eranikus dans le Réceptacle d'essence situé dans son antre dans le Temple englouti.",
    [3374] = "Apporter la Pierre de voeu des dragons d'Ysera et l'Essence d'Eranikus enchaînée à Itharius au marais des Chagrins. C'est là que vous choisirez d'aider ou non les dragons d'Ysera.",
    [3375] = "Apporter une Potion de mana, du Charbon, et du Nectar sucré à Talvash del Kissel à Ironforge pour remplacer la Fiole de divination de Talvash.",
    [3376] = "Apporter la Tête du chef Brochaigu Mantépine à Brave Windfeather à la mesa de Nuage rouge.",
    [3377] = "Écouter le récit de Zamael.",
    [3378] = "Trouver la Prière à Elune et l'apporter à Astarii Starseeker à Darnassus.",
    [3379] = "Tuer le groupe de braconniers Ombresoie qui rôde dans la gorge des Vents brûlants. Nilith a de bonnes raisons de croire qu'ils doivent être exterminés tous les cinq. Retourner voir Nilith dans la gorge des Vents brûlants lorsque vous aurez terminé.",
    [3380] = "Trouver Marvon Rivetseeker à Tanaris.",
    [3382] = "Défendre la capitaine Vanessa Beltis, son équipage et les passagers de “l’Horizon” contre l'attaque des nagas. La capitaine Vanessa Beltis doit survivre.",
    [3385] = "Tuer le Maître d'artisanat Kovic et son agent Clonk. Récupérer sur son corps la Sacoche du marchand et l'apporter à Nilith.",
    [3402] = "Parler à Vizzklick à Gadgetzan.",
    [3441] = "Écouter le récit de Velarok Lamevent.",
    [3442] = "Réunir 4 Cœurs des flammes et 4 globes d’Huile de golem puis rapporter ces objets à Velarok Lamevent.",
    [3443] = "Apporter 8 Dagues plaquées en thorium à Velarok Lamevent.",
    [3444] = "Récupérer le Cercle de pierres à l'Atelier de Marvon Rivetseeker à Ratchet.",
    [3445] = "Trouver Marvon Rivetseeker à Tanaris.",
    [3446] = "Trouver l'Autel d'Hakkar dans le Temple englouti du marais des Chagrins.",
    [3447] = "Voyager jusqu'au Temple englouti et découvrir le secret du cercle de statues.",
    [3448] = "Parler au mage Tymor à Forgefer.",
    [3449] = "À l'aide de la Trousse de dessin, effectuer des reproductions de la Rune de Beth'Amara, de la Rune de Jin'yael, de la Rune de Markri, de la Rune de Sael'hai, puis se diriger vers la petite île près de la Péninsule méridionale d'Azshara et signaler au Pilote Xiggs Fuselighter de venir les prendre.",
    [3450] = "Parler à Xiggs Fuselighter à Forgefer.",
    [3451] = "Parler à Xiggs Fuselighter à Forgefer et en obtenir un Lance-fusée standard.",
    [3452] = "Trouver et apporter un Symbole de Ragnaros à Velarok Lamevent.",
    [3453] = "Attendre que Velarok Lamevent termine la Torche de vindicte.",
    [3454] = "Prendre la Torche de vindicte.",
    [3461] = "Rapporter la Trousse de dessin du mage Tymor au mage Tymor, à Forgefer.",
    [3462] = "Parler à l'écuyer Maltrake.",
    [3463] = "Mettre le feu aux Tours de garde nord, sud, est, et ouest en utilisant la Torche de vindicte à l'intérieur de chaque tour.",
    [3481] = "Ouvrir le coffre.",
    [3501] = "Apporter des Fragments imparfaits de draenéthyste à Kum'isha et toucher une récompense pour chaque fragment rapporté.",
    [3502] = "Apporter des Fragments imparfaits de draenéthyste à Kum'isha. N'importe quel monstres des Terres foudroyées peut détenir un fragment.",
    [3504] = "Apporter la Lettre Scellée à Ag'tor Bloodfist dans Azshara.",
    [3505] = "Tuez 6 vengeurs elfes de sang et 6 géomètres elfes de sang avant de chercher la source du pouvoir de Rimtori.",
    [3506] = "Détruire le Cristal de focalisation des arcanes lié au magus Rimtori et l'assassiner ensuite. Puis apporter la tête du magus Rimtori à Ag'tor Bloodfist dans Azshara.",
    [3507] = "Aller voir Belgrom Rockmaul dans Orgrimmar.",
    [3508] = "Attendre que Loramus ait achevé le rituel de Lumière.",
    [3509] = "Aller voir le seigneur Arkkoroc dans Azshara. Commencer la recherche au bord de l'eau pour trouver le temple d'Arkkoran.",
    [3510] = "Assassiner Hetaera et apporter la Tête ensanglantée d'Hetaera, la Tête battue d'Hetaera et la Tête meurtrie d'Hetaera au seigneur Arkkoroc.",
    [3511] = "Rapporter le durcisseur à Loramus Thalipedes.",
    [3512] = "Se rendre dans la partie orientale du Berceau-de-l'Hiver et aller voir Umbranse l'implorateur d'esprit.",
    [3513] = "Apporter le Parchemin runique à la tour de garde Nord dans les Tarides.",
    [3514] = "Tuer le chef de l'Antre des Serres, Rynthariel le Maître des clés.",
    [3517] = "Trouvez la tablette de Beth’Amara, la tablette de Jin’yael, la tablette de Markri et la tablette de Sael’hai puis retournez voir Jediga à Valormok.",
    [3518] = "Apportez la tablette de Beth’Amara à Magatha Totem-Sinistre aux Pitons-du-Tonnerre.",
    [3519] = "Parler à Dirania Silvershine, à Sombrevallon.",
    [3520] = "Capturer l’Esprit de 3 Hurleurs en Feralas, puis retourner voir Yeh'kinya à Port Gentepression.",
    [3521] = "Trouver 7 Champignons jacinthe, 4 Lys pétales de lune et 1 Ichor d'araignée Tissebois pour Dirania Silveshine dans Sombrevallon.",
    [3522] = "Apporter l’Antidote d'Iverron à Iverron avant que la limite de temps ne soit atteinte. Iverron se trouve près de la grotte, au nord.",
    [3523] = "Pour aider Belnistrasz, lui parler de nouveau et lui rendre la Pierre de voeu qu’il vous avait donnée.",
    [3524] = "Récupérer des Os de créature marine sur la créature échouée, au sud d’Auberdine, puis les apporter à Gwennyth Bly'Leggonde, à Auberdine.",
    [3525] = "Escorter Belnistrasz jusqu'à l'Idole des hurans dans les Souilles de Tranchebauge. Protéger Belnistrasz tandis qu'il exécute le rituel pour arrêter l'idole.",
    [3526] = "Pour en apprendre davantage sur l'Ingénierie gobeline, apporter le Manuel d'Ingénierie à Nixx Sprocketspring dans Gadgetzan.",
    [3527] = "Apporter les Première et Deuxième tablettes Mosh'Aru à Yeh'kinya, à Tanaris.",
    [3528] = "Apporter l'Oeuf Rempli d'Hakkar à Yeh'kinya dans Tanaris.",
    [3541] = "Apporter la Tablette de Jin'yael à Jes'rimon dans Orgrimmar.",
    [3542] = "Apporter la Tablette de Markri à Andron Gant à Fossoyeuse.",
    [3561] = "Apporter la Tablette de Sael'hai à l'archimage Xylem dans Azshara.",
    [3562] = "Apporter la Note de Magatha à Jediga dans Azshara.",
    [3563] = "Apporter la Note de Jes'rimon à Jediga dans Azshara.",
    [3564] = "Apporter la Note d'Andron à Jediga dans Azshara.",
    [3565] = "Apporter la Note de Xylem à Jediga dans Azshara.",
    [3566] = "Assassiner Lathoric le Noir et Obsidion, puis retourner voir Thorius, à Forgefer, avec la Tête de Lathoric le Noir et le Coeur d'Obsidion.",
    [3568] = "Avant de retourner voir le Chimiste Cuely, remplir les 4 Fioles vides aux étangs des marées, le long de la côte des Ruines d'Eldarath, à Azshara.",
    [3569] = "Donner l’élixir de Cuely à Thersa Windsong, à Fossoyeuse.",
    [3601] = "Fouiller le Camp de base thalassien pour trouver la Boussole, la Lunette, le Poulet farci et le Wizzlegoober de Kim'Jael, puis les lui rapporter à Azshara.",
    [3602] = "Trouver 20 Azsharites cristallisées au sud d'Azshara. Utiliser éventuellement le gangrechien pour ‘renifler’ l'emplacement où sont intelligemment cachés les dépôts. Retourner voir Loramus une fois votre tâche accomplie.",
    [3621] = "Apporter la cargaison à Galvan l'Ancien dans la vallée de Strangleronce.",
    [3625] = "Attendre que Galvan ait fini de forger les armes.",
    [3626] = "Retourner voir le Héros déchu de la Horde.",
    [3627] = "Assassiner Grol le Destructeur, dame Sevine et l'archimage Allistarj. Prendre sur leurs cadavres l'Amulette de Grol, l'Amulette de Sevine et l'Amulette d'Allistarj. UTILISER les armes Fel en Azsharite enchantée pour affaiblir la triade (ils ne peuvent pas être tués autrement), mais les utiliser sagement...",
    [3628] = "Détruire Razelikh le Souilleur et apporter la Corne brisée du Souilleur au Héros déchu de la Horde. Rendre aussi l'Amulette du Souilleur au Héros Déchu pour qu'il puisse la détruire, afin de l'empêcher de tomber dans de mauvaises mains.",
    [3629] = "Pour en apprendre davantage sur l'Ingénierie gobeline, apporter le Manuel d'Ingénierie à Nixx Sprocketspring dans Gadgetzan.",
    [3630] = "Pour en apprendre davantage sur l'ingénierie gnome, apporter le Manuel d'Ingénierie au maître-artisan Overspark, à Forgefer.",
    [3631] = "Parler à Strahad Farsan, dans les Tarides.",
    [3632] = "Pour en apprendre davantage sur l'ingénierie gnome, apporter le Manuel d'Ingénierie au maître-artisan Overspark, à Forgefer.",
    [3633] = "Pour en apprendre davantage sur l'ingénierie gobeline, apporter le Manuel d'Ingénierie à Nixx Sprocketspring, à Gadgetzan.",
    [3634] = "Pour en apprendre davantage sur l'ingénierie gnome, apporter le Manuel d'Ingénierie au maître-artisan Overspark, à Ironforge.",
    [3635] = "Pour en apprendre davantage sur l'Ingénierie gnome, apporter le Manuel d'Ingénierie à Oglethorpe Obnoticus à Baie-du-Butin.",
    [3636] = "Tuer Amnennar le Porte-froid, aux Souilles de Tranchebauge, pour l’Archevêque Benedictus.",
    [3637] = "Pour en apprendre davantage sur l'Ingénierie gnome, apporter le Manuel d'Ingénierie à Oglethorpe Obnoticus à Baie-du-Butin.",
    [3638] = "Pour devenir un Ingénieur gobelin, cliquer avec le bouton droit sur le Vœu de secret et retourner voir une fois encore Nixx Sprocketspring dans Gadgetzan.",
    [3639] = "Apporter 20 Grandes Bombes en fer, 20 Dynamites Solides et 5 Moutons Explosifs à Nixx Sprocketspring dans Gadgetzan.",
    [3640] = "Pour devenir un Ingénieur gnome, cliquer avec le bouton droit sur le Vœu de secret et retourner voir une fois encore le maître-artisan Overspark, à Forgefer.",
    [3641] = "Apporter 6 Tubes de mithril, 1 Lunette de précision et 2 Leurres perfectionnés au Maître artisan Overspark à Forgefer.",
    [3642] = "Pour devenir un Ingénieur gnome, cliquer avec le bouton droit sur le Vœu de secret et retourner voir une fois encore Oglethrope Obnoticus à Baie-du-Butin.",
    [3643] = "Apporter 6 Tubes de mithril, 1 Lunette de précision et 2 Cibles avancées à Oglethorpe Obnoticus à Baie-du-Butin.",
    [3661] = "Collecter 15 Plumes d'Indomptable dans les Hinterlands, pour Erelas Ambersky au village de Rut'theran.",
    [3681] = "Parler à Duthorian Rall à Hurlevent.",
    [3701] = "Aller dans les ruines de Thaurissan, dans les Steppes ardentes. Récupérer des informations sur les Reliques de Thaurissan, puis retourner auprès de l’Historienne royale Archesonus.",
    [3702] = "Écouter l'historienne royale Archesonus raconter l'histoire de Thaurissan.",
    [3741] = "Trouver le Collier d'Hilary et le rapporter à Hilary à Comté-du-Lac.",
    [3761] = "Apporter 20 Echantillons d'Humus d'Un'Goro à Ghede, à Thunder Bluff.",
    [3762] = "Parler à l'archidruide Hamuul Runetotem à Thunder Bluff.",
    [3763] = "Parler à l'archidruide Fandral Staghelm à Darnassus.",
    [3764] = "Apporter 20 Echantillons d'Humus d'Un'Goro à Jenal, à Darnassus.",
    [3765] = "Aller voir Gershala Nightwhisper à Auberdine.",
    [3781] = "Apporter le Bon pour des graines de l'archidruide à Mathrengyl Bearwalker dans l'enclave cénarienne à Darnassus.",
    [3782] = "Apporter le Bon pour des graines à Bashana Runetotem à Thunder Bluff.",
    [3783] = "Collecter 10 Fourrures épaisses de yéti pour Umi Rumplesnicker, à Long-guet.",
    [3784] = "Parler à l'archidruide Hamuul Runetotem à Thunder Bluff.",
    [3785] = "Utiliser une Sacoche de printemps avec une pochette de graines de Tharlendis et deux Echantillons d'Humus d'Un'Goro pour essayer de cultiver des Fibres d'aurore. Apporter 10 Fibres d'aurore à Mathrengyl Bearwalker à Darnassus.",
    [3786] = "Utiliser une Sacoche de printemps avec une pochette de graines de Tharlendis et deux Echantillons d'Humus d'Un'Goro pour essayer de cultiver des Fibres d'aurore. Apporter 10 Fibres d'aurore à Bashana Runetotem à Thunder Bluff.",
    [3787] = "Parler à Quintis Jonespyre dans le bastion de Feathermoon.",
    [3788] = "Parler à Quintis Jonespyre dans le bastion de Feathermoon.",
    [3789] = "Parler à l'archidruide Fandral Staghelm à Darnassus.",
    [3790] = "Parler à l'archidruide Fandral Staghelm à Darnassus.",
    [3791] = "Apporter 10 Fibres d'aurore à Quintis Jonespyre au bastion de Feathermoon.",
    [3801] = "Parler à Franclorn Forgewright si obtenir une clé de la Cité majeure vous intéresse.",
    [3802] = "Tuer Fineous Darkvire et récupérer le grand marteau, Souillefer. Apporter Souillefer au sanctuaire de Thaurissan et le placer sur la statue de Franclorn Forgewright.",
    [3821] = "S'aventurer dans les Steppes ardentes et découvrir ce qu'il est advenu de Sha'ni Proudtusk.",
    [3822] = "Récupérer l’Anneau de nez de Sha'ni sur Krom'Grul, et le rapporter à Thal'trak, à Kargath. Fouiller les différentes grottes et mines du Rocher des Cognepeurs.",
    [3823] = "Tuer 15 Ogres-mages Brûlentrailles, 7 Ogres Brûlentrailles et 7 Brutes Brûlentrailles, puis retourner voir Oralius.",
    [3824] = "Trouver Gor'tesh, quelque part à l’ouest du rocher des Cognepeurs. Le tuer et rapporter la Tête coupée de Gor'tesh à Oralius, dans les Steppes ardentes.",
    [3825] = "Prendre la Tête coupée de Gor'tesh et la placer au sommet du Rocher des Cognepeurs. Chercher un monticule de terre meuble pour planter la pique.",
    [3841] = "Parler à Quentin aux Mille pointes.",
    [3842] = "Apportez 2 élixirs de robustesse inférieure à Quentin, aux Mille pointes.",
    [3843] = "Emmenez votre Oeuf fragile de Fée fléchetteuse dans les Hinterlands et parlez à Agnar Beastamer. Dépêchez-vous, vous n’avez qu’une heure pour le trouver avant que le petit ne meure dans l’oeuf.",
    [3844] = "Rechercher dans l'étang un indice sur l'identité du propriétaire du radeau brisé.",
    [3845] = "Examiner les objets du paquet et les apporter à leur propriétaire.",
    [3861] = "Trouver de la Nourriture spéciale pour poulet et l'apporter à la poule que vous voulez aider. Lorsque vous l'aurez trouvée, encouragez-la (/acclame) avant d'essayer de lui donner la Nourriture spéciale pour poulet.",
    [3881] = "Apporter une Caisse de nourriture et de l'Equipement de recherche à Williden Marshal dans le Cratère d'Un'Goro.",
    [3882] = "Apporter 8 Os de dinosaure à Spark Nilminer, au cratère d'Un'Goro.",
    [3883] = "Utiliser la Fiole de raclement pour récolter un Echantillon de paroi de la ruche dans une des nurseries de la ruche Gorishi, à l’intérieur du cratère d'Un'Goro. Chercher les chambres qui contiennent des larves suspendues. Apporter l’Echantillon de paroi de la ruche à Hol'anyee Marshal dans le cratère d'Un'Goro.",
    [3884] = "Rapporter le Journal à Williden Marshal quelque part dans le Cratère d'Un'Goro.",
    [3901] = "Tuez 12 Squelettes Cliquethorax, puis retournez voir le prêtre des ombres Sarvis au Glas.",
    [3902] = "Fouiller Le Glas et ses alentours pour trouver 6 pièces de fournitures de récupération, et les ramener au Garde noir Saltain.",
    [3903] = "Parler à Milly Osworth.",
    [3904] = "Apporter 8 seaux de la récolte de Milly à Milly Osworth à l’abbaye de Comté-du-Nord.",
    [3905] = "Apporter le Manifeste des vendanges à Frère Neals dans l’abbaye de Comté-du-Nord.",
    [3906] = "Partir pour la carrière dans le mont Rochenoire et tuer le Grand maître Pyron. Retourner voir Thunderheart une fois votre mission accomplie.",
    [3907] = "Pénétrer dans les Profondeurs de Rochenoire et traquer le Seigneur Incendius. Le tuer puis donner tous les renseignements que vous pouvez trouver à Thunderheart.",
    [3908] = "Apporter l’Epée de Linken à Donova Snowden dans le Berceau-de-l'Hiver.",
    [3909] = "Rechercher Gregan Brewspewer au nord de Feralas. Apprendre de lui comment vous pouvez acquérir l'élixir de Videre, puis retourner voir Donova Snowden, au Berceau-de-l'Hiver.",
    [3912] = "Se rendre au cimetière au-dehors de Gadgetzan et boire l'élixir de Videre. Suivre le reste des instructions de Donova pour trouver Gaeriyan.",
    [3913] = "Ressusciter, puis rechercher la pierre tombale que Gaeriyan vous a demandé de trouver.",
    [3914] = "Remettre l'Epée excellente de Linken à Linken dans le cratère d'Un'Goro.",
    [3921] = "Apporter le Samophlange cassé à Wenikee Boltbucket.",
    [3922] = "Apporter 15 Rondelles de métal à Wenikee Boltbucket dans les Tarides.",
    [3923] = "Apporter le Samophlange cassé à Rilli Greasygob à Orgrimmar.",
    [3924] = "Apporter le Manuel du Samophlange à Rilli Greasygob à Orgrimmar.",
    [3941] = "Trouver J.D. Collie dans la caverne du refuge des Marshal.",
    [3942] = "Trouver Eridan Bluewind dans le sud de Gangrebois.",
    [3961] = "Apporter le Totem d'argent d'Aquementas à Linken au refuge des Marshal.",
    [3962] = "Partir pour la crête de la Fournaise, au sud du refuge des Marshal. Trouver Blazerunner et utiliser le Totem pour dissiper son aura protectrice. Une fois Blazerunner vaincu, se procurer la Flamme dorée.",
    [3981] = "Trouver le commandant Gor'shak dans les Profondeurs de Rochenoire. Le dessin grossier représentait également des barreaux. Peut-être devriez-vous rechercher un genre de prison.",
    [3982] = "Défendre Gor'shak.",
    [4001] = "Parler à Kharan Mighthammer et obtenir autant de renseignements que possible sur l'enlèvement de la princesse Moira Bronzebeard. Apporter ces renseignements à Thrall à Orgrimmar. Gor'shak a dit que Kharan était détenu dans une cellule proche.",
    [4002] = "Parler à Thrall si vous êtes prêt à vous charger de la mission qu'il a prévue.",
    [4003] = "Tuer l'Empereur Thaurissan et libérer la princesse Moira Bronzebeard de son sort maléfique.",
    [4004] = "Retourner voir Thrall !",
    [4005] = "Apporter le Livre d'Aquor, les Griffes argentées et le Coeur d'Arbrefer à Tanaris. Utiliser le Livre d'Aquor pour invoquer Aquementas. Après avoir terminé le totem, l’apporter à J.D. Collie au refuge des Marshal.",
    [4021] = "Apporter un Morceau de la bannière de Krom'zar à Regthar Deathgate, à l'ouest de la Croisée.",
    [4022] = "Montrer à Cyrus Therepentous le Cuir de dragon noir que vous avez reçu de Velarok Lamevent.",
    [4023] = "Montrer à Cyrus Therepentous une preuve de votre valeur. Vous avez le sentiment que Cyrus sait déjà que vous êtes indigne.",
    [4024] = "Partir pour les Profondeurs de Rochenoire et tuer Bael'Gar. Vous savez seulement que le géant demeure à l'intérieur des Profondeurs de Rochenoire. Se souvenir d'utiliser l'Ecaille des dragons noirs altérée pour capturer l'Essence ardente. Apporter l'Essence ardente recouverte à Cyrus Therepentous.",
    [4061] = "S'aventurer dans les Steppes ardentes et récupérer 10 Fragments d'élémentaires cassés pour la Hiérophante Theodora Mulvadania. Theodora vous a indiqué que les golems et les élémentaires étaient la source de ces fragments.",
    [4062] = "Apporter l'Echantillon de fragment d'élémentaire à Lotwil Veriatus. Theodora vous a dit qu'il se trouvait au camp à l'est.",
    [4063] = "Trouver et tuer le seigneur des golems Argelmach. Rapporter sa tête à Lotwil. Collecter également 10 Noyaux d'élémentaire intacts sur les Golems ravarage et les Assemblages porteguerre qui protègent Argelmach. Vous savez cela car vous êtes médium.",
    [4081] = "Pénétrer dans les Profondeurs de Rochenoire et tuer les vils agresseurs ! Le chef de guerre Goretooth veut que vous tuiez 15 Gardes Ragenclumes, 10 Gardiens Ragenclumes et 5 Fantassins Ragenclumes. Retourner le voir une fois votre mission accomplie.",
    [4082] = "Pénétrer dans les Profondeurs de Rochenoire et tuer les vils agresseurs ! Le Chef de guerre Goretooth veut que vous tuiez 10 Médecins Ragenclumes, 10 Soldats Ragenclumes et 10 Officiers Ragenclumes. Retourner le voir une fois votre mission accomplie.",
    [4084] = "Trouver 11 Griffes d'argent et 1 Cœur d'Arbrefer pour Eridan Bluewind à Gangrebois.",
    [4101] = "Apporter 15 Ambres de sang à Arathandris Silversky à Gangrebois.",
    [4102] = "Apporter 15 Ambres de sang à Maybess Riverbreeze à Gangrebois.",
    [4120] = "Talo Thornhoof, à Camp Mojache, dans Feralas, voudrait que vous tuiez 12 Grizzlis de la griffe colérique et 12 Ravageurs Gangrepatte, à Gangrebois.",
    [4121] = "Escortez votre prisonnier, Grark Lorkrub, au-delà des Steppes ardentes et du mont Rochenoire, jusqu'à la gorge des Vents brûlants. Rappelez-vous que Lexlort a précisé que ses hommes attendraient de l'autre côté pour arrêter Grark. On vous demandera également de remettre vos chaînes en thorium à Lexlort.",
    [4122] = "Partez pour les Steppes ardentes et trouvez Grark Lorkrub. Lexlort a mentionné le fait que la dernière fois où on l'a vu, il se trouvait dans une imposante forteresse des Rochenoires. Une fois Grark Lorkrub découvert, l'enchaîner avec les chaînes en thorium, puis le ramener par le mont Rochenoire jusque dans la gorge des Vents brûlants. Des hommes de Lexlort attendront de l'autre côté de la gorge et le mettront sous bonne garde.",
    [4123] = "Apporter le Cœur de la montagne à Maxwort Uberglint dans les Steppes ardentes.",
    [4124] = "Parler à Ginro Hearthkindle dans le bastion de Feathermoon.",
    [4125] = "Localiser le bateau du messager quelque part le long de la côte de Feralas.",
    [4126] = "Apporter la Recette perdue de la Thunderbrew à Ragnar Thunderbrew à Kharanos.",
    [4127] = "Retourner au bastion de Feathermoon et montrer à Ginro Hearthkindle le Couteau perdu que vous avez découvert.",
    [4128] = "Parler à Ragnar Thunderbrew.",
    [4129] = "Apporter le Couteau perdu à Quintis Jonespyre au bastion de Feathermoon.",
    [4130] = "Parler à Ginro Hearthkindle dans le bastion de Feathermoon.",
    [4131] = "Fouiller les Camps des gnolls Griffebois dans la partie sud de Feralas pour trouver des indices sur les possessions du messager ou sur le messager lui-même.",
    [4132] = "Voyagez jusqu'aux Profondeurs de Rochenoire et tuez le général Forgehargne ! Une fois votre mission accomplie, retournez voir le seigneur de guerre Goretooth.",
    [4133] = "Parler à la maîtresse des ombres Vivian Lagrave à Kargath.",
    [4134] = "Apporter la Recette perdue de la Thunderbrew à Vivian Lagrave à Kargath.",
    [4135] = "À présent que la dernière destination connue de Raschal est découverte, continuez à le rechercher, lui ou ses restes, dans le Gouffre grouillant. D'après le message, il se trouve au sud des camps des gnolls Griffebois.",
    [4136] = "Apporter la Tête de Ribbly à Yuka Screwspigot dans les Steppes ardentes.",
    [4141] = "Récolter 15 Pétales-de-sang et retourner voir Muigin.",
    [4142] = "Apporter une Pétale-de-sang à Gregan Brewspewer en Feralas.",
    [4143] = "Récupérer 5 Echantillons de brume atal'ai puis retourner voir Muigin dans le cratère d'Un'Goro.",
    [4145] = "Chasser 5 Flagellants Pétale-de-sang, 5 Batteurs Pétale-de-sang, 5 Ecorcheurs Pétale-de-sang et 5 Trappeurs Pétale-de-sang pour Larion au refuge des Marshal.",
    [4146] = "Remettre la Baguette déchargée et 5 Echantillons de brume atal'ai à Larion au refuge des Marshal.",
    [4147] = "Se rendre à l'Atelier de Marvon Rivetseeker à Ratchet.",
    [4161] = "Collecter 7 Petites pattes d'araignée pour Zarrin, à Dolanaar.",
    [4181] = "Apporter le Manuel d'ingénierie à Nixx Sprocketspring à Gadgetzan si vous souhaitez en apprendre davantage sur l'ingénierie gobeline.",
    [4182] = "Tuer 15 Rejetons noirs, 10 Draconides noirs, 4 Wyrmides noirs et 1 Drake noir. Retrouver Helendis Riverhorn une fois la tâche accomplie.",
    [4183] = "Voyager jusqu’à Comté-du-Lac et remettre la Lettre d'Helendis Riverhorn au Magistrat Solomon.",
    [4184] = "Voyager vers Hurlevent et remettre la Demande d'aide de Solomon au généralissime Bolvar Fordragon. Bolvar demeure dans le Donjon de Hurlevent.",
    [4185] = "Parler au généralissime Bolvar Fordragon après avoir parlé à dame Katrana Prestor.",
    [4186] = "Apporter le Décret de Bolvar au Magistrat Solomon à Comté-du-Lac.",
    [4201] = "Apporter 4 Gromsang, 10 Veines d'argent de géant et la Fiole de Nagmara remplie à la gouvernante Nagmara dans les Profondeurs de Rochenoire.",
    [4223] = "Parler au maréchal Maxwell dans les Steppes ardentes.",
    [4224] = "Parlez à John le Loqueteux pour apprendre ce qu'il est advenu du maréchal Windsor puis retournez voir le maréchal Maxwell lorsque vous aurez accompli cette tâche. Vous vous rappelez que le maréchal Maxwell vous a dit de le chercher dans une grotte au nord.",
    [4241] = "Partir pour le mont Rochenoire au nord-ouest et pénétrer dans les Profondeurs de Rochenoire. Découvrir ce qu'il est advenu du Maréchal Windsor. Vous vous souvenez que John le Loqueteux a dit que Windsor avait été traîné en prison.",
    [4242] = "Donner les mauvaises nouvelles au maréchal Maxwell.",
    [4243] = "Trouver A-mi 01 dans le Cratère d'Un'Goro.",
    [4244] = "Trouver une Caisse en mithril et retourner près de A-mi 01 dans le Cratère d'Un'Goro.",
    [4245] = "Escorter A-mi 01 sur le chemin du retour jusqu'à Karna Remtravel dans le Cratère d'Un'Goro.",
    [4261] = "Escorter Arei jusqu’à un lieu sûr, puis parler à Kayneth Stillwind au Chant des forêts, dans l’est d'Ashenvale.",
    [4262] = "Tuer le Grand seigneur Pyron et retourner voir Jalinda Sprig. Jalinda vous a dit qu'il gardait la carrière. Peut-être devriez-vous chercher à cet endroit ?",
    [4263] = "Trouver le Seigneur Incendius dans les Profondeurs de Rochenoire et le détruire !",
    [4264] = "Il se peut que vous ayez simplement buté sur quelque chose qui pourrait intéresser le maréchal Windsor au plus haut point. Il reste peut-être encore un peu d'espoir, après tout…",
    [4265] = "Libérer Raschal de la ruche de Zukk'ash. Revenir voir Ginro Hearthkindle au bastion de Feathermoon et lui dire que Raschal est sain et sauf.",
    [4266] = "Parler à Shandris Feathermoon dans le bastion de Feathermoon.",
    [4267] = "Apporter le Rapport de Raschal à Gracina Spiritmight à Darnassus.",
    [4281] = "Apporter le Vieux colis à Falfindel Waywarder, à Thalanaar.",
    [4282] = "Rapporter les Renseignements perdus du maréchal Windsor. Le maréchal Windsor pense qu'ils sont détenus par le seigneur golem Argelmach et par le général Forgehargne.",
    [4283] = "Oralius veut 50 Médaillons de Rochenoire. Il y a de fortes chances de trouver ces médaillons sur les orcs des Steppes ardentes.",
    [4284] = "Récupérer 7 Cristaux de puissance de chaque couleur (rouge, bleu, jaune et vert). Les apporter à J.D. Collie au refuge des Marshal.",
    [4285] = "Découvrir l'emplacement du Pylône de cristal nord dans le Cratère d'Un'Goro.",
    [4286] = "Se rendre dans les Profondeurs de Rochenoire et trouver 20 Sacoches Sombrefer. Retourner voir Oralius lorsque vous aurez accompli cette tâche. Logiquement, ces sacoches devraient être sur les nains Sombrefer des Profondeurs de Rochenoire.",
    [4287] = "Trouver l'emplacement du Pylône de cristal est dans le Cratère d'Un'Goro.",
    [4288] = "Découvrir l'emplacement du Pylône de cristal ouest.",
    [4289] = "Apporter 2 Peaux de gorille d'Un'Goro, 2 Peaux de marteleur d'Un'Goro et 2 Peaux de foudroyeur d'Un'Goro à Torwa Pathfinder à l'entrée du cratère d'Un'Goro.",
    [4290] = "Trouver la dernière victime de Lar'korwi et voler un Morceau de carcasse d'un battrodon, puis retourner voir Torwa Pathfinder au Cratère d'Un'Goro.",
    [4291] = "Apporter 2 Glandes de phéromone de ravasaure à Torwa Pathfinder près de l'entrée du Cratère d'Un'Goro.",
    [4292] = "En utilisant le contenu de la Sacoche de Torwa, appeler Lar'korwi et le vaincre. Puis apporter la Tête de Lar'korwi à Torwa Pathfinder près de l'entrée du Cratère d'Un'Goro.",
    [4293] = "Ramasser des Echantillons de Gelée de Gangrebois sur les gelées de Gangrebois. Puis, en utilisant le Matériel d'expérience qui se trouve à côté du Chimiste Fuely à Fossoyeuse, déceler l'échantillon le plus corrompu. Apporter 5 Echantillons corrompus de Gangrebois au Chimiste Fuely.",
    [4294] = "Ramasser des Echantillons de Gelée d'Un'Goro sur les gelées du Cratère d'Un'Goro. Puis, en utilisant le Matériel d'expérience qui se trouve à côté du Chimiste Fuely à Fossoyeuse, déceler l'échantillon le plus pur. Apporter 5 Echantillons purs d'Un'Goro au Chimiste Fuely.",
    [4296] = "Apporter la Transcription de la tablette à Maxwort Uberglint dans les Steppes ardentes.",
    [4297] = "Apporter 5 Flancs de Traqueur Crins-d'argent à Angar Beastamer dans les Hinterlands.",
    [4298] = "Parler à Agnar Beastamer dans les Hinterlands.",
    [4300] = "Apporter 8 Griffes blanches de ravasaure à Jes'rimon à Orgrimmar.",
    [4301] = "Apporter la Peau d'U'cha à Torwa Pathfinder à l'entrée du Cratère d'Un'Goro.",
    [4321] = "Parler à J.D. Collie dans un moment.",
    [4322] = "Aider le maréchal Windsor à récupérer son équipement et à libérer ses amis. Ensuite, retourner voir le maréchal Maxwell.",
    [4324] = "Parler à Yuka Screwspigot dans les Steppes ardentes.",
    [4341] = "Aller dans les Profondeurs de Rochenoire et trouver Kharan Mighthammer. Le roi a mentionné que Kharan était retenu prisonnier là-bas ; cherchez une prison.",
    [4342] = "Écouter Kharan Mighthammer raconter son histoire.",
    [4361] = "Retourner à Forgefer et apporter la mauvaise nouvelle au Roi Magni Bronzebeard.",
    [4362] = "Retourner dans les Profondeurs de Rochenoire et secourir la Princesse Moira Bronzebeard, prisonnière de l'Empereur Dagran Thaurissan.",
    [4363] = "Retourner à Forgefer et parler au roi Magni Bronzebeard.",
    [4402] = "Apportez à Galgar 10 Pommes de cactus. Il vous a précisé qu'elles se trouvaient souvent à côté des cactus.",
    [4421] = "Tuer 11 Liges de la corruption Jadefeu, 9 Traqueurs des ombres Jadefeu, 9 Voleurs Jadefeu et Xavathras. Retourner voir Eridan Bluewind, à Gangrebois, quand la mission est terminée.",
    [4441] = "Aller à Darnassus et utiliser la Fiole d'Eridan dans le Temple de la Lune, pour obtenir une Fiole d'eau bénite. Retourner voir Eridan avec la Fiole pleine.",
    [4442] = "Attendre un moment avant de reparler à Eridan.",
    [4449] = "Tuer 8 Géologues Sombrefer et rapporter 15 morceaux d’Etoffe de soie à la personne enfermée de les toilettes de la gorge des Vents brûlants.",
    [4450] = "Prendre la copie du Livre de Goodsteel, puis collecter les objets qui y sont listés avant d’aller voir Krinkle Goodsteel, à Tanaris.",
    [4451] = "Aller dans la gorge des Vents brûlants et trouver une utilisation à la Clé des toilettes de Crasseboue que vous avez trouvée.",
    [4485] = "Parler à Duthorian Rall, à Hurlevent.",
    [4486] = "Parler à Duthorian Rall, à Hurlevent.",
    [4487] = "Parler à Strahad Farsan, à Ratchet.",
    [4488] = "Parler à Strahad Farsan, à Ratchet.",
    [4489] = "Parler à Strahad Farsan, à Ratchet.",
    [4490] = "Parler à Strahad Farsan, à Ratchet pour apprendre à invoquer un Palefroi corrompu.",
    [4491] = "Conduire Ringo à Spraggle Frock, au refuge des Marshal. Si Ringo s’évanouit, utiliser la Gourde de Spraggle pour le réanimer.",
    [4492] = "Trouver Ringo sur la crête de la Fournaise.",
    [4493] = "Parler à l’alchimiste Pestlezugg à Gadgetzan.",
    [4494] = "Parler à l’alchimiste Pestlezugg à Gadgetzan.",
    [4495] = "Trouver Iverron près de la grotte au nord.",
    [4496] = "Apporter une Glande olfactive Gorishi et 5 Echantillons d'Humus d'Un'Goro à l’alchimiste Pestlezugg, à Gadgetzan.",
    [4501] = "Tuer 10 Pterreurdactyles et 15 Pterreurdactyles frénétiques, puis parler à Spraggle Frock, au refuge des Marshal.",
    [4502] = "Collecter 9 Echantillons de cendre Un'Goro sur les Elémentaires de brûlure qui se trouvent autour du volcan, dans le Cratère d'Un'Goro, puis les apporter à Liv Rizzlefix, à Ratchet.",
    [4503] = "Apporter 8 Ecailles étoilées de dimeurtrodon et 8 Ecailles étoilées de pterreurdactyles à Shizzle, au refuge des Marshal.",
    [4504] = "Collecter 12 échantillons de Goudron ultra collant pour Tran'rek, à Gadgetzan.",
    [4505] = "Collecter un échantillon d’eau corrompue dans le Puits de lune des satyres Jadefeu, puis le rapporter à Winna Hazzard, au Poste de la Vénéneuse.",
    [4506] = "Amener le chaton de Winna au Puits de lune corrompu, le relâcher, puis le rapporter à Winna. Une fois de retour auprès de Winna, cliquer sur le chat pour le lui rendre.",
    [4507] = "Invoquer la Reine gorishi et la vaincre. Apporter le Cerveau de reine gorishi à l’alchimiste Pestlezugg, à Gadgetzan.",
    [4508] = "Apporter le Rapport de Pestlezugg sur Un'Goro à Gracina Spiritmight, à Darnassus.",
    [4509] = "Apporter le Rapport de Pestlezugg sur Un'Goro à Zilzibin Drumlore, à Orgrimmar.",
    [4510] = "Apporter le Reçu bancaire à Idriana, à la banque de Darnassus.",
    [4511] = "Apporter le Reçu bancaire à Karus, à la banque d'Orgrimmar.",
    [4512] = "Apporter 6 Pots de Limons maudits remplis et 6 Pots de Limons corrompus remplis à Laris Geardawdle, à Forgefer .",
    [4513] = "Apporter 10 Pots remplis d'échantillon pur à Laris Geardawdle, à Forgefer. Si vous éprouvez des difficultés à les trouver, allez voir Laris pour obtenir plus d’indices.",
    [4521] = "Trull Failbane de Gangrebois veut que vous tuiez 15 Chouettards enragés et 15 Chouettards éreintés.",
    [4542] = "Apporter le Message urgent au garde-falaise Longhorn au Poste de Librevent.",
    [4581] = "Apporter la Note de Shindrell à Kayneth Stillwind au Chant des Forêts.",
    [4621] = "Tuez l'amiral Corne-de-Mer et le baron Revilgaz de Baie-du-Butin, puis retrouvez l'amiral Firallon à bord de la Voile cramoisie, au large des côtes de la vallée de Strangleronce.",
    [4641] = "Parler à Gornek. Souvenez-vous que Kaltunk vous a indiqué où il se trouvait sur votre carte et vous a dit que Gornek résidait dans l'Antre, un bâtiment vers l'ouest.",
    [4642] = "Apporter un Echantillon de Limon mélangé au chimiste Fuely à Undercity.",
    [4681] = "Récupérer les Restes de tortue de mer sur le Squelette de la tortue de mer, dans les eaux à l’ouest d’Auberdine, puis parler à Gwennyth Bly'Leggonde, à Auberdine.",
    [4701] = "Allez au pic Rochenoire et anéantir la menace worg à sa source. Tandis que vous quittiez Helendis, il a crié un nom : Halycon. C'est ce que disent les orcs en parlant des worgs.",
    [4721] = "Trull Failbane à Gangrebois veut que vous chassiez 10 Chouettards berserk au Berceau-de-l'Hiver.",
    [4722] = "Apporter les Restes de tortue de mer à Gwennyth Bly'Leggonde à Auberdine.",
    [4723] = "Apporter les Os de créature marine à Gwennyth Bly'Leggonde à Auberdine.",
    [4724] = "Tuer Halycon, la maîtresse de la meute des worgs Bloodaxe.",
    [4725] = "Apporter la Boîte aux marques étranges à Gwennyth Bly'Leggonde à Auberdine.",
    [4726] = "Apporter 8 Essences de Rejeton et le Draco-Incarcinatrix 900 à Tinkee Steamboil à la Corniche des flammes dans les Steppes ardentes.",
    [4727] = "Apporter les Restes de tortue de mer à Gwennyth Bly'Leggonde à Auberdine.",
    [4728] = "Apporter les Os de créature marine à Gwennyth Bly'Leggonde à Auberdine.",
    [4729] = "Aller au pic Rochenoire et trouver de Jeunes worgs Bloodaxe. Utiliser la cage pour transporter ces petites bêtes féroces. Rapporter un Jeune worg en cage à Kibler.",
    [4730] = "Apporter les Os de créature marine à Gwennyth Bly'Leggonde à Auberdine.",
    [4731] = "Apporter la Boîte aux marques étranges à Gwennyth Bly'Leggonde à Auberdine.",
    [4732] = "Apporter les Restes de tortue de mer à Gwennyth Bly'Leggonde à Auberdine.",
    [4733] = "Apporter les Os de créature marine à Gwennyth Bly'Leggonde à Auberdine.",
    [4734] = "Utiliser le Prototype d'Oeufilloscope sur un oeuf dans la Colonie.",
    [4735] = "Apporter 8 Oeufs de dragon collectés et le Module collectronique à Tinkee Steamboil à la Corniche des flammes dans les Steppes Ardentes.",
    [4736] = "Parler à Menara Voidrender dans les Tarides.",
    [4737] = "Parler à Menara Voidrender dans les Tarides.",
    [4738] = "Parler à Menara Voidrender dans les Tarides.",
    [4739] = "Parler à Menara Voidrender dans les Tarides.",
    [4740] = "Trouver et tuer le murloc connu sous le nom de Fondeboue. On pense que la créature défend les huttes des murlocs au sud d'Auberdine près de l'eau. Annoncer la mort de Fondeboue à la Sentinelle Glynda Nal'Shea à Auberdine.",
    [4741] = "Trull Failbane à Gangrebois veut que vous chassiez 13 Chouettards lunaires.",
    [4742] = "Trouver les trois gemmes de commandement : la Gemme de Smolderthorn, la Gemme de Pierre-du-pic et la Gemme de Bloodaxe. Rapportez-les, ainsi que le Sceau d'ascension non décoré, à Vaelan. Les généraux, comme vous l'a dit Vaelan, sont : le maître de guerre Voone de Smolderthorn ; le généralissime Omokk des Pierres-du-pic ; et le seigneur Wyrmthalak de Bloodaxe.",
    [4743] = "Allez à la tourbière du Ver dans le marécage d'Âprefange. Trouvez l'ancien drake, Brandeguerre, et frappez-le sans merci jusqu'à ce que sa volonté soit brisée. A cet instant précis, vous devez placer le Sceau d'ascension brut devant l'énorme bête. Vous devez ensuite utiliser rapidement l'Orbe d'énergie draconique sur sa forme affaiblie et prendre possession de ses facultés mentales. Contrôlez la bête et dirigez les flammes du Vol noir sur le Sceau d'ascension brut !",
    [4761] = "Parler à Thundris Windweaver, à Auberdine.",
    [4762] = "Aller au nord d’Auberdine, à la première chute d’eau, le long de la Bondissante et prélever un échantillon de l’eau de l’étang. Retourner voir Thundris Windweaver, à Auberdine, avec le Prélèvement de la Bondissante.",
    [4763] = "Remplir le Bol de purification vide au Puits de lune d’Auberdine. Collecter un échantillon de fruit, de noix et de céréales dans les camps nord des furbolgs Noirbois. Mélanger les échantillons de nourriture à l’eau du bol et le placer à proximité du feu le plus proche de la rivière Bondissante, au camp nord. Cela fera venir le satyre corrupteur. Prendre son Talisman de corruption et l'apporter à Thundris Windweaver, à Auberdine.",
    [4764] = "Apporter le Fermoir de Doomrigger à Mayara Brightwing, dans les Steppes ardentes.",
    [4765] = "Apporter la Caisse de Ridgewell à Remington Ridgewell, à Stormwind.",
    [4766] = "Parler à Mayara Brightwing, dans les Steppes Ardentes.",
    [4767] = "Apporter 10 Oeufs de wyverne de Haut-perchoir à Elu au poste de Librevent.",
    [4768] = "Apporter la Tablette de Darkstone à l'ombremage Vivian Lagrave à Kargath.",
    [4769] = "Parler à l'ombremage Vivian Lagrave.",
    [4770] = "Escorter Pao'ka Swiftmountain à partir de Haut-perchoir, puis parler à Motega Firemane au poste de Blanc-relais.",
    [4771] = "Placer le Gambit de l'aube dans la Chambre des visions de Scholomance. Vaincre Vectus, puis retourner auprès de Betina Bigglezink.",
    [4781] = "Apporter une Barre d'or à Xizk Goodstitch dans la vallée de Strangleronce.",
    [4782] = "Retourner voir Menara Voidrender dans les Tarides.",
    [4783] = "Apporter 10 Fioles de sang de Fielfurie et 1 Pierre infernale inférieure à Menara Voidrender dans les Tarides.",
    [4784] = "Apporter du Fil d'or fin, 2 Charbons ardents et un Fragment d'âme à Menara Voidrender dans les Tarides.",
    [4786] = "Attendre que Menara Voidrender ait terminé votre robe puis lui parler de nouveau.",
    [4787] = "Apporter l'Oeuf antique à Yeh'kinya à Tanaris.",
    [4788] = "Apporter la cinquième et la sixième Tablette Mosh'aru au Prospecteur Ironboot à Tanaris.",
    [4808] = "Donner la Lettre de Tinkee à Felnok Steelspring.",
    [4809] = "Apporter 8 Cornes intactes de Noroît à Felnok Steelspring.",
    [4810] = "Apporter le Paquet de Felnok à Tinkee Steamboil dans les Steppes ardentes.",
    [4811] = "Voyager en direction de l’est en partant d'Auberdine et chercher un gros cristal rouge le long de la chaîne de montagne est de Sombrivage. Aller faire un rapport de ce que vous avez trouvé à la Sentinelle Glynda Nal'Shea à Auberdine.",
    [4812] = "Remplir le Tube d'eau vide au Puits de lune d’Auberdine, puis chercher le cristal rouge le long des falaises des montagnes à l’est de Sombrivage.",
    [4813] = "Aller faire un rapport de ce que vous avez trouvé à la Sentinelle Glynda Nal'Shea à Auberdine.",
    [4821] = "Rapporter l'Oeuf étrange à Hagar Lightninghoof au Poste de Librevent.",
    [4841] = "Tuer 12 Eclaireurs galak, 10 Querelleurs galak, et 6 Chasse-vent galak, puis retourner auprès du garde-falaise Longhorn au Poste de Librevent.",
    [4842] = "Suivre les instructions de Donova Snowden, puis faire un rapport.",
    [4861] = "Localiser le camp démoli et les fournitures de Jaron Stoneshaper, au sud du Berceau-de-l'Hiver.",
    [4862] = "Aller au pic Rochenoire et ramasser 15 Oeuf d'araignée du pic pour Kibler. Ces oeufs peuvent être trouvés à proximité des araignées.",
    [4863] = "Trouver le chariot saccagé de Jaron Stoneshaper.",
    [4864] = "Ramasser les Fournitures de Jaron dans la neige, puis trouver l'Indomptable qui a volé l'amulette dont Jaron a parlé. Rapporter les fournitures de Jaron et l'Amulette de la plume bleue à Jaron Stoneshaper au pavillon, dans le Berceau-de-l'Hiver.",
    [4865] = "Faire un rapport de vos trouvailles à Motega Firemane.",
    [4866] = "Vous trouverez la Matriarche Couveuse au coeur du pic Rochenoire. Attaquez-la et poussez-la à vous empoisonner. Vous devrez sans doute la tuer. Une fois empoisonné, trouvez John le Loqueteux afin qu'il puisse prélever un échantillon.",
    [4867] = "Lire le Parchemin de Warosh. Apporter le Mojo de Warosh à Warosh.",
    [4881] = "Prévenir Kanati Greycloud au Poste de Blanc-relais qu'un complot le menace.",
    [4882] = "Apporter le Collier de plumes bleues à Trull Failbane au Poste de la Vénéneuse.",
    [4883] = "Apporter le Collier de plumes bleues à Nara Wildmane.",
    [4901] = "Protéger Ranshalla pendant qu’elle s’efforce de réactiver l’Autel d’Elune. Faire un rapport de vos découvertes à Erelas Ambersky, au village de Rut'theran.",
    [4902] = "Parler à l’archidruide Fandral Staghelm, à Darnassus.",
    [4903] = "Tuer le généralissime Omokk, le maître de guerre Voone et le seigneur Wyrmthalak. Récupérer les Importants documents de Rochenoire. Retourner voir le chef de guerre Goretooth à Kargath une fois la mission accomplie.",
    [4904] = "Escorter Lakota Windsong hors de la Cime de Noir-nuage, puis parler à Thalia Amberhide au Poste de Librevent.",
    [4906] = "Eridan Bluewind de Gangrebois veut que vous tuiez 8 Implorateurs de l'enfer Jadefeu, 8 Traîtres Jadefeu, 8 Entourloupeurs Jadefeu, et Xavaric. Revenir auprès d’Eridan quand la tâche est accomplie.",
    [4907] = "Parler à Tinkee Steamboil.",
    [4921] = "Trouver la femme de Mankrik puis retourner le voir à la Croisée.",
    [4941] = "Parler à Eitrigg, à Orgrimmar. Après avoir discuté avec Eitrigg, demander conseil à Thrall. Vous avez déjà vu Eitrigg dans les Appartements de Thrall.",
    [4961] = "Tuer le Démon de l’Orbe, puis parler à Tabetha.",
    [4962] = "Prendre le Rubis de Felhas et l’utiliser sur l’un des gangrechiens de Désolace. Quand vous aurez réussi, rapporter le Rubis de Felhas et l’Esprit de gangrechien emprisonné à Menara Voidrender, dans les Tarides.",
    [4963] = "Prendre l’Emeraude d'Infus et l’utiliser sur les Infernaux qui se trouvent en Désolace. Quand vous aurez réussi, rapporter l’Emeraude d'Infus et l’Esprit d'Infernal emprisonné à Menara Voidrender, dans les Tarides.",
    [4964] = "Attendre que Menara Voidrender termine l’Orbe de Dar'Orahil, puis lui reparler.",
    [4965] = "Parler à Menara Voidrender dans les Tarides.",
    [4966] = "Protéger Kanati Greycloud contre l’attaque centaure.",
    [4967] = "Parler à Menara Voidrender dans les Tarides.",
    [4968] = "Parler à Menara Voidrender dans les Tarides.",
    [4969] = "Parler à Menara Voidrender dans les Tarides.",
    [4970] = "Récolter 5 Viandes de Croc acéré et 5 Viandes de Noroît pour Rivern Frostwind du Berceau-de-l'Hiver.",
    [4971] = "Utiliser le Déplaceur temporel à côté de l’un des silos d’Andorhal pour révéler des Parasites temporels. Tuer 15 Parasites temporels et rapporter le Déplaceur temporel à Chromie, à l’auberge d’Andorhal, dans les Maleterres de l’ouest.",
    [4972] = "Trouver 5 Montres d'Andorhal, dans des coffrets qui se trouvent parmi les décombres de la cité, et les rapporter à Chromie à l’Auberge d’Andorhal, dans les Maleterres de l’ouest.",
    [4973] = "Trouver 5 Montres d'Andorhal parmi les décombres de la cité, et les rapporter à Chromie à l’Auberge d’Andorhal, dans les Maleterres de l’ouest.",
    [4974] = "Aller au pic Rochenoire et tuer le Chef de guerre, Rend Blackhand. Prendre sa tête et retourner à Orgrimmar.",
    [4975] = "Attendre que Menara Voidrender ait terminé l’Orbe de Noh'Orahil, puis lui reparler.",
    [4976] = "Rapporter l’Orbe infernal purifié à Menara Voidrender, dans les Tarides.",
    [4981] = "Aller au pic Rochenoire et découvrir ce qui est arrivé à Bijou.",
    [4982] = "Trouver les Affaires de Bijou et les lui rapporter. Elle vous a dit les avoir cachées dans le niveau inférieur de la ville.",
    [4983] = "Rapporter le Rapport de reconnaissance de Bijou au Grand-maître Lexlort, à Kargath.",
    [4984] = "Détruire 8 Loups malades, puis retourner voir Mulgris Deepriver, au Repaire putride dans les Maleterres de l’ouest.",
    [4985] = "Détruire 8 Grizzlis malades, puis retourner voir Mulgris Deepriver au Repaire putride, dans les Maleterres de l’ouest.",
    [4986] = "D'après la magie contenue dans la Branche de chêne à glyphes, le druide tauren voulait qu'elle soit apportée au Cercle cénarien, à Darnassus. Aller solliciter l’assistance de l’un des druides, là-bas.",
    [4987] = "D'après la magie contenue dans la Branche de chêne à glyphes, le druide tauren voulait qu'elle soit apportée au Cercle cénarien, à Thunder Bluff. Aller solliciter l’assistance de l’un des druides, là-bas.",
    [5001] = "Retrouver les Affaires de Bijou et les lui rapporter. Bonne chance !",
    [5002] = "Se rendre dans les Steppes ardentes et confier les Renseignements de Bijou au maréchal Maxwell.",
    [5021] = "Le discours incohérent de la femme fantomatique indique qu’elle a besoin qu’on livre un colis pour elle. Elle a dit que le colis se trouvait là où se trouve son cheval. Le fantôme est incompréhensible lorsqu’il s’agit de préciser où se trouve son cheval ou l’endroit où le paquet doit être livré.",
    [5022] = "Rendre visite aux Facteurs royaux de Hurlevent pour apprendre l’adresse d’une certaine Emma Felstone. En général, il y a un officier du recensement à l’Hôtel de ville.",
    [5023] = "Se renseigner auprès des Surveillants royaux de Fossoyeuse pour apprendre l’adresse d’un certain Jeremiah Felstone. En général, il y a un officier du recensement près du bureau d’inscription des guildes et tabards.",
    [5041] = "Trouver et rapporter les Caisses de ravitaillement de la Croisée à Thork dans les Tarides.",
    [5047] = "Parler à Malyfous Darkhammer à Long-guet.",
    [5048] = "Trouver la vieille Emma à Hurlevent, et découvrir si elle est en fait Emma Felstone. Si c’est le cas, elle appréciera peut-être le colis que Janice Felstone lui a préparé.",
    [5049] = "Trouver Jeremiah Payson à Fossoyeuse et découvrir s’il est en fait Jeremiah Felstone. Si c’est le cas, il appréciera peut-être le colis que Janice Felstone lui a préparé.",
    [5050] = "Rapporter son Demi-charme porte-bonheur à Janice Felstone dans les Maleterres de l’ouest.",
    [5051] = "Trouver l’autre moitié du Charme porte-bonheur quelque part dans le périmètre de la Ferme Felstone dans les Maleterres de l’ouest et le recoller. Donner le Charme porte-bonheur à Janice Felstone à la Ferme Felstone, dans les Maleterres de l’ouest.",
    [5052] = "Apporter un Joyau de sang à Mangletooth, à Camp Taurajo, dans les Tarides. Collectez plus de Joyaux de sang, si vous souhaitez qu’il vous gratifie de la puissance d’Agamaggan.",
    [5054] = "Storm Shadowhoof, à Long-guet au Berceau-de-l'Hiver, veut que vous tuiez Ursius.",
    [5055] = "Storm Shadowhoof, à Long-guet au Berceau-de-l'Hiver, veut que vous tuiez Brumeran.",
    [5056] = "Storm Shadowhoof, à Long-guet au Berceau-de-l'Hiver, veut que vous triomphiez de Shy-Rotam.",
    [5057] = "Apporter le Marqueur de Storm Shadowhoof à Melor Stonehoof à Thunder Bluff.",
    [5061] = "Retourner à Darnassus et montrer le Pendentif du lion de mer à Mathrengyl Bearwalker.",
    [5062] = "Ramasser 10 boisseaux d'agave d'Incendia, puis consulter Magatha Grimtotem sur la Cime des Anciens dans Thunderbluff.",
    [5063] = "Pour créer la Coiffe du savant écarlate, il faut rapporter les éléments suivants à Malyfous Darkhammer : 1 Peau de la Bête en parfait état ; 5 Coutures d'Abomination effilochées ; 8 Cristaux des arcanes ; 5 Fils écarlates enchantés. Il faudra aussi payer 50 pièces d’or pour le travail de fabrication.",
    [5064] = "Trouver et récupérer les trois Notes Secrètes à la Cime de Noir-nuage.",
    [5065] = "Apporter la troisième et la quatrième tablette Mosh'aru au Prospecteur Ironboot à Tanaris.",
    [5066] = "Trouver le commandant Ashlam Valorfist. Son camp de base est situé au camp du Noroît, au nord des montagnes d'Alterac.",
    [5067] = "Pour fabriquer les Jambières d'Arcana, il faut rapporter les éléments suivants à Malyfous Darkhammer : 1 Peau de la Bête en parfait état ; 5 Coutures d'Abomination effilochées ; 5 Barres d'arcanite ; 5 Fluides d'embaumement de Murmegivre. Il faudra également payer 50 pièces d’or pour le travail de fabrication.",
    [5068] = "Pour fabriquer la Cuirasse carnassière, il faut rapporter les éléments suivants à Malyfous Darkhammer : 1 Peau de la Bête en parfait état ; 10 Coutures d'Abomination effilochées ; 5 Barres d'arcanite ; 5 Peaux des ombres. Il faudra également payer 50 pièces d’or pour le travail de fabrication.",
    [5081] = "Se rendre au pic Rochenoire et tuer le maître de guerre Voone, le généralissime Omokk, et le seigneur Wyrmthalak. Retourner auprès du maréchal Maxwell quand la tâche a été accomplie.",
    [5082] = "Donova Snowden du Berceau-de-l'Hiver veut que vous tuiez 8 Guides, 8 Protecteurs et 8 Totémiques de la tribu Tombe-hiver.",
    [5083] = "Apporter le Flacon d'eau de feu vide à Donova Snowden du Berceau-de-l'Hiver.",
    [5084] = "Chercher un indice dans le camp des furbolgs Mort-bois, dans le nord de Gangrebois.",
    [5085] = "Aller faire un rapport de vos trouvailles à Donova Snowden.",
    [5086] = "Récolter 3 Gouttelettes d'Horreur toxique pour Donova Snowden au Berceau-de-l'Hiver.",
    [5087] = "Trouver les Messagers Tombe-hiver et les empêcher de livrer leur cargaison au village Tombe-hiver.",
    [5088] = "Tuez Arikara. Rapportez sa dépouille et la poudre d’incendia à Motega Crin-de-feu au poste de Blanc-relais comme preuve de vos actes.",
    [5089] = "Remettre les Ordres du général Drakkisath au maréchal Maxwell dans les Steppes ardentes.",
    [5090] = "Trouver le commandant Ashlam Valorfist. Son camp de base est le Camp du Noroît, au nord des montagnes d'Alterac.",
    [5091] = "Trouver le commandant Ashlam Valorfist. Il s'est établi au Camp du Noroît, au nord des montagnes d'Alterac.",
    [5092] = "Tuer 10 Ecorcheurs Squelettes et 10 Goules écumantes sur la Colline des chagrins. Retourner auprès du commandant Ashlam Valorfist au camp du Noroît, dans les Maleterres de l’ouest.",
    [5093] = "Partir à la recherche du Grand exécuteur Derrington. Son camp de base se trouve à la Barricade, à l’est des Clairières de Tirisfal et de Fossoyeuse.",
    [5094] = "Partir à la recherche du Grand exécuteur Derrington. Son camp de base se trouve à la Barricade, à l’est des Clairières de Tirisfal et de Fossoyeuse.",
    [5095] = "Partir à la recherche du Grand exécuteur Derrington. Son camp de base se trouve à la Barricade, à l’est des Clairières de Tirisfal et de Fossoyeuse.",
    [5096] = "Se rendre au camp de base de la Croisade écarlate situé entre le Champ de Felstone et les Larmes de Dalson et détruire leur tente d’état-major. Placer la bannière du Fléau sur le camp, puis revenir auprès du Grand exécuteur Derrington à la Barricade, dans les Maleterres de l’ouest.",
    [5097] = "À l’aide de la Torche-balise, marquer chaque tour à Andorhal ; il faut se tenir dans l’embrasure de la porte de la tour pour pouvoir la marquer. Quand les quatre tours seront marquées, rapporter la Torche-balise au commandant Ashlam Valorfist au camp du Noroît, dans les Maleterres de l’ouest.",
    [5098] = "À l’aide de la Torche-balise, marquer chaque tour à Andorhal ; il faut se tenir dans l’embrasure de la porte de la tour pour pouvoir la marquer. Quand les quatre tours seront marquées, rapporter la Torche-balise au Grand exécuteur Derrington à la Barricade, dans les Maleterres de l’ouest.",
    [5102] = "Rendez-vous au pic Rochenoire et tuez le général Drakkisath, puis retournez voir le maréchal Maxwell.",
    [5103] = "Quelqu’un dans ce monde doit bien savoir à quoi servent ces gantelets. Bonne chance !",
    [5121] = "Donova Snowden du Berceau-de-l'Hiver veut que vous triomphiez du Grand chef Tombe-hiver.",
    [5123] = "Apporter le Journal mal écrit à Donova Snowden au Berceau-de-l'Hiver.",
    [5124] = "Apporter à Malyfous Darkhammer 6 Barres de thorium enchanté, 2 Essences de feu, et 4 Rubis stellaires. Lui remettre également vos Gantelets en plaques inachevés.",
    [5126] = "Parler à Lorax. Écouter ce qu’il a à dire.",
    [5127] = "Se rendre au pic Blackrock et trouver Goraluk Anvilcrack. Le tuer puis utiliser la Pique tachée de sang sur son cadavre. Après avoir siphonné son âme, la pique sera devenue Tachée d'âme. Trouver aussi la Cuirasse couverte de runes inachevée. Rapporter la Pique tachée d'âme et la Cuirasse couverte de runes inachevée à Lorax au Berceau-de-l'Hiver.",
    [5128] = "Rapporter le Journal mal écrit à Kelek Skykeeper dans le sud de Gangrebois.",
    [5141] = "Apporter 2 Cuirasses armées du scorpide, 2 Gants armés du scorpide et 10 Ecailles de dragon usées à Peter Galen, à Azshara. Terminer cette quête vous donnera accès aux arts du travail du cuir en écailles de dragon. Terminer cette quête avec succès vous interdira l’apprentissage du travail du cuir élémentaire et du travail du cuir tribal. Prenez le temps de réfléchir à la voie que vous souhaitez emprunter, avant de prendre une décision.",
    [5142] = "Retrouver Pamela Redpath.",
    [5143] = "Apporter un Gilet en cuir sauvage et un Casque en cuir sauvage à Caryssia Moonhunter en Feralas. L’accomplissement de cette quête donne accès aux arts du travail du cuir tribal. L’accomplissement de cette quête vous empêchera d’apprendre le travail du cuir de dragon et le travail du cuir élémentaire ; il faut être sûr du chemin que l’on veut suivre avant de faire ce choix.",
    [5144] = "Apporter 2 Coeurs de feu, 2 Globes d’eau, 2 Noyaux de terre, et 2 Souffles de vent à Sarah Tanner dans la Gorge des Vents brûlants. L’accomplissement de cette quête donne accès aux arts du Travail du cuir élémentaire. L’accomplissement de cette quête vous empêchera d’apprendre le Travail du cuir de dragon et le Travail du cuir tribal ; il faut être sûr du chemin que l’on veut suivre avant de faire ce choix.",
    [5145] = "Apporter 2 Cuirasses armées du scorpide, 2 Gants armés du scorpide et 10 Ecailles de dragon usées à Thorkaf Dragoneye, dans les Terres ingrates. Terminer cette quête vous donnera accès aux arts du travail du cuir en écailles de dragon. Terminer cette quête avec succès vous interdira l’apprentissage du travail du cuir élémentaire et du travail du cuir tribal. Prenez le temps de réfléchir à la voie que vous souhaitez emprunter, avant de prendre une décision.",
    [5146] = "Apporter 2 Coeurs de feu, 2 Globes d'eau, 2 Noyaux de terre, et 2 Souffles de vent à Brumn Winterhoof dans les montagnes d’Arathi. L’accomplissement de cette quête donne accès aux arts du travail du cuir élémentaire. L’accomplissement de cette quête vous empêchera d’apprendre le travail du cuir de dragon et le travail du cuir tribal ; il faut être sûr du chemin que l’on veut suivre avant de faire ce choix.",
    [5147] = "Tuer Arnak Grimtotem et apporter une preuve de votre acte au garde-falaise Longhorn au Poste de Librevent.",
    [5148] = "Apporter un Gilet en cuir sauvage et un Casque en cuir sauvage à Se'Jib dans la vallée de Strangleronce. L’accomplissement de cette quête donne accès aux arts du travail du cuir tribal. L’accomplissement de cette quête vous empêchera d’apprendre le travail du cuir de dragon et le travail du cuir élémentaire ; il faut être sûr du chemin que l’on veut suivre avant de faire ce choix.",
    [5149] = "Trouver la poupée de Pamela.",
    [5151] = "Tuer la bête et rapporter l'Hypercapaciteur et la Clé de la cage de la panthèse à Wizlo Bearingshiner.",
    [5152] = "Parler à Marlene, au sud des ruines d'Andorhal.",
    [5153] = "Apporter l’Alliance de Joseph à Chromie.",
    [5154] = "Apporter les Annales de Darrowshire à Chromie, à Andorhal.",
    [5155] = "Entrer dans Jaedenar et tuer 4 Molosses de Jaedenar, 4 Gardiens de Jaedenar, 6 Adeptes de Jaedenar, et 6 Sectateurs de Jaedenar avant de retourner auprès de Greta Mosshoof dans Gangrebois.",
    [5156] = "Trouver et détruire 2 Bêtes d'entropie et 2 Horreurs d'entropie tout en explorant le Val Grêlé. Après avoir vérifié que les cratères à cet endroit sont toujours remplis d’eau corrompue, retourner auprès de Taronn Redfeather dans Gangrebois.",
    [5157] = "Amener la Gourde vide au Puits de lune au centre de Jaedenar et la remplir avant de retourner voir Greta Mosshoof dans Gangrebois.",
    [5158] = "Apporter l’Eau de Puits de lune corrompue à Islen Waterseer dans les Tarides.",
    [5159] = "Apporter l’Eau de Puits de lune purifiée à Greta Mosshoof dans Gangrebois.",
    [5160] = "Aller jusqu’au Berceau-de-l'Hiver et trouver Haleh. Lui donner l’Ecaille d'Awbee.",
    [5161] = "Si vous souhaitez continuer, parlez à Haleh.",
    [5162] = "Parler à Jeziba dans les Maleterres. Il vit à Andorhal.",
    [5163] = "Prendre le yéti mécanique d'Umi et effrayer ses amis avec : Legacki, à Long-guet (Berceau-de-l'Hiver) Sprinkle, à Gadgetzan (Tanaris) Quixxil, au refuge des Marshal (Cratère d'Un'Goro) Quand vous aurez terminé, rapporter le yéti mécanique à Umi.",
    [5164] = "Lire le Guide de l'Indocile.",
    [5165] = "Avec de l’Eau de Puits de lune purifiée, éteindre les flammes des quatre braseros de protection à l’intérieur du Fort des ombres dans Gangrebois.",
    [5166] = "Pour forger la Cuirasse du vol chromatique, il faut apporter les éléments suivants à Jeziba le 'Sculpteur' : 1 Carapace chromatique. 10 Ecailles chromatiques brillantes. 10 Sangs de héros. 10 Coutures d'Abomination effilochées.",
    [5167] = "Pour forger les Cuissardes des duellistes chromatiques, il faut apporter les éléments suivants à Jeziba le 'Sculpteur' : 1 Carapace chromatique. 10 Ecailles chromatiques brillantes. 10 Sangs de héros. 5 Peaux des ombres.",
    [5168] = "Apporter le Libram de Davil et le Bouclier Redpath à Carlin Redpath.",
    [5181] = "Rapporter le Crâne d'Horgus et l’Epée brisée de Marduk à Carlin Redpath à la chapelle de l'Espoir de Lumière.",
    [5201] = "Rivern Frostwind veut que vous tuiez 5 Chamans Tombe-hiver et 5 Ursas Tombe-hiver.",
    [5202] = "Chercher dans Jaedenar à quoi sert la Clé rouge sang.",
    [5203] = "Escorter Arko'narin à l’endroit où Lightforge et son équipement sont détenus, puis la protéger lors de l’évasion du Fort des ombres. Ensuite, aller trouver Jessir Moonbow dans Gangrebois pour lui apprendre ce qui est arrivé à ses amis.",
    [5204] = "Revenir à Jaedenar et tuer la succube Rakaiah avant de trouver le Cadavre de Trey Lightforge.",
    [5206] = "Apporter 5 Crânes résonants et le Cristal mystique à Carlin Redpath, dans les Maleterres de l’est.",
    [5210] = "Apporter les Annales complètes de Darrowshire à Carlin Redpath dans les Maleterres de l’est.",
    [5211] = "Libérer 15 Esprits de Darrowshire et retourner auprès de Carlin Redpath.",
    [5212] = "Récupérer 20 Echantillons de chair pestiférée à Stratholme puis les rapporter à Betina Bigglezink. Vous pensez que toutes les créatures de Stratholme possèdent de tels échantillons de chair.",
    [5213] = "Se rendre jusqu’à Stratholme et fouiller les ziggourats. Trouver et ramener de nouvelles informations sur le Fléau à Betina Bigglezink.",
    [5214] = "Trouver le magasin de tabac d’Ezra Grimm à Stratholme et récupérer une boîte de Tabac d’Ezra. Retourner auprès de Smokey LaRue quand ce sera fait.",
    [5215] = "Parler à la grande prêtresse MacDonnell à la pointe du Noroît, dans les Maleterres de l’ouest.",
    [5216] = "Se rendre au Champ de Felstone dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve. Il aura peut-être une clé qui permet d’accéder au chaudron. Il faut se munir de la Bouteille d'échantillon du Champ de Felstone vide pour pouvoir prélever un échantillon des poisons qui sont dans le chaudron.",
    [5217] = "Apporter une Bouteille du Champ de Felstone remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l’ouest.",
    [5219] = "Se rendre aux Larmes de Dalson dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve, puis utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille des larmes de Dalson vide pour pouvoir prendre un échantillon des poisons qui sont dans le chaudron.",
    [5220] = "Apporter la Bouteille des Larmes de Dalson remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l’ouest.",
    [5222] = "Se rendre au Repaire putride dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille vide du Repaire putride pour pouvoir récupérer un échantillon des poisons à l’intérieur du chaudron.",
    [5223] = "Apporter la Bouteille du Repaire putride remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l’ouest.",
    [5225] = "Se rendre à la Flétrissure de Gahrron dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille vide de la Flétrissure de Gahrron pour pouvoir récupérer un échantillon des poisons à l’intérieur du chaudron.",
    [5226] = "Apporter la Bouteille de la Flétrissure de Gahrron remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l’ouest.",
    [5228] = "Parler à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l’ouest.",
    [5229] = "Se rendre au Champ de Felstone, dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve. Il aura peut-être une clé qui permet d’accéder au chaudron. Il faut se munir de la Bouteille d'échantillon du Champ de Felstone vide pour pouvoir prélever un échantillon des poisons qui sont dans le chaudron.",
    [5230] = "Apporter la Bouteille du Champ de Felstone remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l’ouest.",
    [5231] = "Se rendre aux Larmes de Dalson dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve, puis utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille des larmes de Dalson vide pour pouvoir prendre un échantillon des poisons qui sont dans le chaudron.",
    [5232] = "Apporter la Bouteille des Larmes de Dalson remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l’ouest.",
    [5233] = "Se rendre au Repaire putride dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille vide du Repaire putride pour pouvoir récupérer un échantillon des poisons à l’intérieur du chaudron.",
    [5234] = "Ramener la Bouteille du Repaire putride remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l’ouest.",
    [5235] = "Se rendre à la Flétrissure de Gahrron dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille vide de la Flétrissure de Gahrron pour pouvoir récupérer un échantillon des poisons à l’intérieur du chaudron.",
    [5236] = "Apporter la Bouteille de la Flétrissure de Gahrron remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l’ouest.",
    [5241] = "Trouver Carlin Redpath.",
    [5242] = "Tuer Moora et Salia, et rapporter la Tête du Seigneur des ténèbres Fel'dan à Greta Mosshoof dans Gangrebois.",
    [5243] = "Se rendre à Stratholme, au nord. Fouiller les caisses de fournitures qui encombrent la cité et récupérer 5 Eaux sacrées de Stratholme. Retourner auprès de Leonid Barthalomew le Révéré quand vous avez récolté assez de liquide béni.",
    [5244] = "Parler à Jaron Stoneshaper au village de Pluie-d'Etoiles",
    [5245] = "Utiliser la Pique de Jaron pour trouver les quatre Fragments de relique des Bien-nés. Les apporter à Aurora Skycaller dans les Maleterres de l’est.",
    [5246] = "Trouver les Ecrits sacrés des Bien-nés dans le temple de Zin-Malor à Azshara et les apporter à Aurora Skycaller à la tour du Col du nord, dans les Maleterres de l'est.",
    [5247] = "Apporter une Barre de thorium enchanté, 5 Cristaux de restauration et une Fiole d'eau redoutable à Aurora Skycaller à la tour du Col du nord, dans les Maleterres de l’est.",
    [5248] = "Amener le Cristal de Zin-Malor au lac Kel'Theril dans le Berceau-de-l'Hiver et trouver un esprit Bien-né qui veuille bien vous parler.",
    [5249] = "Trouver le village de Pluie-d'Etoiles dans le Berceau-de-l'Hiver, et parler à Wynd Nightchaser.",
    [5250] = "Trouver le village de Pluie-d'Etoiles dans le Berceau-de-l'Hiver et parler à Wynd Nightchaser.",
    [5251] = "Voyager jusqu’à Stratholme et trouver l’Archiviste Galford de la Croisade écarlate. L’abattre et brûler les Archives écarlates.",
    [5252] = "Parler à Wynd Nightchaser au village de Pluie-d'Etoiles et lui demander quel est le bon endroit pour le Cristal de Zin-Malor.",
    [5253] = "Apporter le Cristal de Zin-Malor à l’archidruide Fandral Staghelm à Darnassus.",
    [5261] = "Parler à Eagan Peltskinner.",
    [5262] = "Apporter la Tête de Balnazzar au duc Nicholas Zverenhoff dans les Maleterres de l’est.",
    [5263] = "S’aventurer dans Stratholme et tuer le baron Rivendare. Prendre sa tête et retourner auprès du duc Nicholas Zverenhoff.",
    [5264] = "Parler au seigneur Maxwell Tyrosus. Il est à l’intérieur de l’église.",
    [5265] = "Ouvrir le Coffre prendre votre récompense.",
    [5281] = "Trouver Egan. Vous savez seulement qu’on l’a vu pour la dernière fois aux alentours de Stratholme.",
    [5282] = "Se servir du Libérateur d'Egan sur les citoyens fantomatiques et spectraux de Stratholme. Quand les esprits sans repos se libèrent de leur enveloppes fantomatiques, utiliser de nouveau le Libérateur – ils seront enfin libres ! Libérer 15 Esprits sans repos puis retourner auprès d’Egan.",
    [5283] = "Pour devenir un fabricant d'armures, il faut fabriquer les éléments suivants et les rapporter à Grumnus : 4 Heaumes ornés en mithril, 2 Bottes ornées en mithril, 1 Cuirasse ornée en mithril.",
    [5284] = "Pour devenir un Fabricant d'armes, il faut fabriquer les éléments suivants et les rapporter à Ironus : 4 Epées d'acier lunaire, 4 Gigantesques haches en fer, 2 Haches en mithril lourd, et 2 Grandes masses noires.",
    [5301] = "Pour devenir un fabricant d'armures, il faut fabriquer les éléments suivants puis les apporter à Okothos : 4 Heaumes ornés en mithril, 2 Bottes ornées en mithril, 1 Cuirasse ornée en mithril.",
    [5302] = "Pour devenir un Fabricant d'armes, vous devez fabriquer les éléments suivants et les rapporter à Borgosh : 4 Epées d'acier lunaire, 4 Gigantesques haches en fer, 2 Haches en mithril lourd, et 2 Grandes masses noires.",
    [5305] = "Aller jusqu’à Stratholme et tuer le Forgeur de marteaux cramoisi. Récupérer son Tablier et le ramener à Lilith.",
    [5306] = "Aller jusqu’au Pic Blackrock et abattre la chasseresse des ombres Vosh'gajin. Récupérer la Pierre du serpent de Vosh'gajin et la ramener à Kilram.",
    [5307] = "Trouver le Fabricant d'épées de la Garde noire à Stratholme et le tuer. Récupérer l’Insigne de la Garde noire et retourner auprès de Seril Scourgebane.",
    [5321] = "Escortez Kerlonian Éternombre jusqu’à Liladris Ondelune, vers le sud le long de la route, afin de retrouver son sac, à Sombrivage.",
    [5341] = "S’aventurer jusqu’à Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété d’Austrivage. Revenir auprès d’Alexi Barov quand la tâche est accomplie.",
    [5342] = "Voyagez jusqu’au Camp du Noroît, dans le territoire de l’Alliance, et y assassiner Weldon Barov. Prenez sa tête et revenez auprès d’Alexi Barov. Attention : Weldon sera probablement bien protégé par la racaille de l’Alliance.",
    [5343] = "S’aventurer jusqu’à la Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété d’Austrivage. Revenir auprès de Weldon Barov quand la tâche est accomplie.",
    [5344] = "Voyager jusqu’à la Barricade - territoire de la Horde - et assassiner Alexi Barov. Prendre sa tête et revenir auprès de Weldon Barov. Attention : Alexi sera probablement bien protégé par les vandales de la Horde.",
    [5361] = "Apporter le Rapport du garde-falaise Longhorn à Nataka Longhorn au poste de Rôdeur-fantôme en Désolace.",
    [5381] = "Récupérer la Boîte démoniaque dans la forteresse de Hache-Tonnerre, puis la rapporter à Taiga Wisemane, à Proie-de-l'Ombre.",
    [5382] = "Trouver le docteur Theolen Krastinov à l’intérieur de la Scholomance. Le tuer, puis brûler le Cadavre d’Eva Sarkhoff et le Cadavre de Lucien Sarkhoff. Retourner auprès d’Eva Sarkhoff quand la tâche est accomplie.",
    [5384] = "Revenir à Scholomance avec le Sang des innocents. Trouver le porche et placer le Sang des innocents dans le brasero. Kirtonos viendra dévorer votre âme. Combattre vaillamment, sans perdre un pouce de terrain ! Détruire Kirtonos et revenir auprès d’Eva Sarkhoff.",
    [5385] = "Rapporter le Cadavre de Trey Lightforge à Jessir Moonbow dans Gangrebois.",
    [5386] = "Parler à Jinar'Zillen à Proie-de-l'Ombre, puis amener 2 poissons Ventre-rouge à Nataka Longhorn.",
    [5441] = "Utiliser la Masse du contremaître sur les Péons paresseux, lorsqu’ils sont en train de dormir. Réveiller 5 Péons, puis rapporter la Masse du contremaître au contremaître Thazz'ril, dans la Vallée des épreuves.",
    [5461] = "Voyager jusqu’aux hautes-terres d'Arathi, et aller aux ruines de Stromgarde. Fouiller Stromgarde pour trouver un Souvenir de la mémoire. Si une telle trouvaille est faite, rapporter l’objet au magistrat Marduke.",
    [5462] = "Voyager jusqu’à l’Espoir de lumière dans les Maleterres de l'est et trouver Leonid Barthalomew le Révéré. Lui montrer le Souvenir de la mémoire et lui dire tout ce que vous avez découvert.",
    [5463] = "Voyager jusqu’à Stratholme et trouver le cadeau de Menethil. Placer le Souvenir de la mémoire sur le sol impie.",
    [5464] = "Apporter le Souvenir lié à Leonid Barthalomew dans les Maleterres de l’est.",
    [5465] = "Retourner auprès du Magistrat Marduke à Caer Darrow. Lui montrer le Souvenir lié.",
    [5466] = "Trouver Ras Murmegivre dans Scholomance. Après l’avoir trouvé, utiliser le Souvenir lié sur son visage mort-vivant. Si sa transformation en mortel réussit, l’abattre et prendre la Tête humaine de Ras Murmegivre. Apporter la tête au Magistrat Marduke.",
    [5481] = "Récolter 3 herbes des ténèbres et les apporter à l’Apprenti Apothicaire Holland au cimetière de Brill.",
    [5482] = "Récolter 10 Herbes maléfiques et les apporter à l’apprenti apothicaire Holland.",
    [5501] = "Apporter à Bibbly F'utzbuckle à la Hutte de Kormek 10 Os de kodo provenant du Cimetière des kodos.",
    [5504] = "Apporter 10 Marques de valeur de l’Aube d'argent au Quartier-maître Hasana à la Barricade, dans les Maleterres de l’ouest",
    [5507] = "Apporter 10 Marques de valeur de l’Aube d'argent au quartier-maître Lightspark au camp du Noroît, dans les Maleterres de l’ouest.",
    [5513] = "Apporter 10 Marques de valeur de l’Aube d'argent à l'intendante Breechlock, à la chapelle de l'Espoir de Lumière, dans les Maleterres de l’est.",
    [5514] = "Apporter les Fragments de squelette imprégnés et 15 pièces d’or à Krinkle Goodsteel à Gadgetzan.",
    [5515] = "Trouver Jandice Barov dans Scholomance et la tuer. Sur son cadavre, récupérer le Sac des horreurs de Krastinov. Rapporter le sac à Eva Sarkhoff.",
    [5517] = "Apporter 25 Marques de valeur de l’Aube d'argent à l'intendante Breechlock, à la chapelle de l'Espoir de Lumière, dans les Maleterres de l’est.",
    [5518] = "Apportez 4 Rouleaux d'étoffe runique, 8 Cuirs robustes, 2 Fils runiques et du Tanin ogre à Knot Thimblejack. Il est actuellement enchaîné dans l’aile Gordok de Hache-tripes.",
    [5521] = "Apporter 25 Marques de valeur de l’Aube d'argent au quartier-maître Lightspark au camp du Noroît, dans les Maleterres de l’ouest.",
    [5522] = "Apporter les Oeufs congelés à Leonid Barthalomew dans les Maleterres de l’est.",
    [5524] = "Apporter 25 Marques de valeur de l’Aube d'argent au Quartier-maître Hasana à la Barricade, dans les Maleterres de l’ouest.",
    [5526] = "Trouvez la Gangrevigne à Hache-tripes et prenez-en un fragment. Il est probable que vous ne pourrez vous en emparer qu’après la mort d’Alzzin le Modeleur. Servez-vous du Reliquaire de Pureté pour conserver le fragment, et retournez à Reflet-de-Lune voir Rabine Saturna au village de Havrenuit.",
    [5527] = "Rendez-vous en Silithus et cherchez un Reliquaire de pureté dans les ruines du village de Sudevent. Si vous parvenez à le trouver, ramenez-le à Rabine Saturna à Havrenuit, Reflet-de-Lune.",
    [5529] = "Tuer 20 Jeunes pestiférés, puis retourner auprès de Betina Bigglezink à la Chapelle de l’Espoir de Lumière.",
    [5531] = "Apporter les Oeufs congelés à Betina Bigglezink.",
    [5533] = "Parler à l’alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l’ouest.",
    [5534] = "Trouver \"une rune\" détenue par les nagas dans les ruines d’Eldarath et la rapporter à Kim'jael à Azshara.",
    [5535] = "Détruire 6 Apparitions de Bien-nés et 6 Jeunes liches bien-nées avant de retourner auprès de Loh'atu à Azshara.",
    [5536] = "Tuer 6 satyres Haldarr, 2 Entourloupeurs Haldarr, 2 Lige de la corruption Haldarr puis revenir auprès de Loh'atu à la frontière d’Ashenvale.",
    [5537] = "Apporter 15 Fragments de squelette à l’alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l’ouest.",
    [5538] = "Apporter les Fragments de squelette imprégnés et 15 pièces d’or à Krinkle Goodsteel à Gadgetzan.",
    [5541] = "Apporter les Munitions de Rumbleshot à Hegnar Rumbleshot à Dun Morogh.",
    [5542] = "Tuer 20 Chiens pestiférés chétifs, 5 Chiens pestiférés et 5 Chiens pestiférés frénétiques. Retourner voir Tirion Fordring, quand la mission sera terminée.",
    [5543] = "Tuer 30 Chauves-souris pestiférées, puis retourner voir Tirion Fordring.",
    [5544] = "Chercher les Larves putrides et les Dévoreurs de la région. Les tuer et récupérer leur viande. Retourner voir Tirion Fordring quand 15 pièces de Chair de Ver putride auront été récupérées.",
    [5545] = "Apporter 8 fagots de bois à Raelen au Camp de bûcherons du Val d'est.",
    [5561] = "Ramener cinq Kodos domptés et le Kombobulateur kodo à Smeed Scrabblescrew au camp de Scrabblescrew.",
    [5581] = "Bannir 6 Portails, dans le convent de Mannoroc, puis retourner voir Taiga Wisemane, à Proie-de-l'Ombre.",
    [5582] = "Apporter l’Ecaille de dragon luisante à Betina Bigglezink à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est.",
    [5601] = "Trouver Pamela Redpath dans le Darrowshire.",
    [5621] = "Trouver la Sentinelle Shaya et la guérir de ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir Laurna Morninglight, à Dolanaar.",
    [5622] = "Parler à Laurna Morninglight à Teldrassil.",
    [5623] = "Parler à la prêtresse Josetta dans la Forêt d’Elwynn.",
    [5624] = "Trouver le garde Roberts et soigner ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir la prêtresse Josetta, à Comté-de-l’Or.",
    [5625] = "Trouver le Montagnard Dolf et guérir ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir Maxan Anvol, à Kharanos.",
    [5626] = "Parler à Maxan Anvol à Dun Morogh.",
    [5628] = "Parler à la prêtresse Alathea à Darnassus.",
    [5629] = "Parler à la prêtresse Alathea à Darnassus.",
    [5630] = "Parler à la prêtresse Alathea à Darnassus.",
    [5631] = "Parler à la prêtresse Alathea à Darnassus.",
    [5632] = "Parler à la prêtresse Alathea à Darnassus.",
    [5633] = "Parler à la prêtresse Alathea à Darnassus.",
    [5635] = "Parlez au grand prêtre Rohan, à Forgefer.",
    [5636] = "Parlez au grand prêtre Rohan, à Forgefer.",
    [5637] = "Parlez au grand prêtre Rohan, à Forgefer.",
    [5638] = "Parler à la grande prêtresse Laurena à Stormwind.",
    [5639] = "Parler à la grande prêtresse Laurena à Stormwind.",
    [5642] = "Parler à Ur'kyo à Orgrimmar.",
    [5643] = "Parler à Ur'kyo à Orgrimmar.",
    [5644] = "Parler à Aelthalyste à Fossoyeuse.",
    [5645] = "Parler au grand prêtre Rohan à Forgefer.",
    [5646] = "Parler à Aelthalyste à Fossoyeuse.",
    [5647] = "Parler au grand prêtre Rohan à Forgefer.",
    [5648] = "Trouver le grunt Kor'ja et la guérir de ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir Tai'jin, sur Tranchecolline.",
    [5649] = "Parler à Tai'jin en Durotar.",
    [5650] = "Trouver le Garde noir Kel et le guérir de ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir le sombre clerc Beryl, à Brill.",
    [5651] = "Parler au sombre clerc Beryl dans les Clairières de Tirisfal.",
    [5654] = "Parler à Ur'kyo à Orgrimmar.",
    [5655] = "Parler à Ur'kyo à Orgrimmar.",
    [5656] = "Parler à Ur'kyo à Orgrimmar.",
    [5657] = "Parler à Ur'kyo à Orgrimmar.",
    [5660] = "Parler à Aelthalyste à Fossoyeuse.",
    [5661] = "Parler à Aelthalyste à Undercity.",
    [5662] = "Parler à Aelthalyste à Fossoyeuse.",
    [5663] = "Parler à Aelthalyste à Undercity.",
    [5673] = "Parler à la prêtresse Alathea à Darnassus.",
    [5674] = "Parler à la prêtresse Alathea à Darnassus.",
    [5675] = "Parler à la prêtresse Alathea à Darnassus.",
    [5677] = "Parler à la grande prêtresse Laurena à Hurlevent.",
    [5678] = "Parler à la grande prêtresse Laurena à Hurlevent.",
    [5713] = "Protéger la Sentinelle Aynasha, puis parler à Onaeya au poste de Maestra, en Ashenvale.",
    [5721] = "Placer la Liasse de reliques sur la place centrale de Darrowshire. Empêcher la mort de Davil Lightfire, jusqu’à la mort de Horgus. Empêcher la mort du capitaine Redpath, jusqu’à ce que Redpath le Corrompu apparaisse. Vaincre Redpath le Corrompu. Parler à l’esprit de Joseph Redpath, quand il apparaît sur la place centrale, puis parler à Pamela, dans sa maison.",
    [5722] = "Fouiller le Gouffre de Ragefeu pour trouver le cadavre de Maur Grimtotem et tout élément intéressant.",
    [5723] = "Chercher le gouffre de Ragefeu dans Orgrimmar, puis tuer 8 Troggs Ragefeu et 8 Chamans Ragefeu avant de revenir auprès de Rahauro à Thunder Bluff.",
    [5724] = "Apporter la Sacoche du Totem sinistre à Rahauro à Thunder Bluff.",
    [5725] = "Apporter les livres de Sorts des Ombres et d’Incantations du Néant à Varimathras, à Fossoyeuse.",
    [5726] = "Apporter un Insigne de lieutenant à Thrall à Orgrimmar.",
    [5727] = "Apporter l'Insigne du Lieutenant à Neeru Fireblade et lui parler. Essayer de déterminer s'il vous croit membre de la Lame ardente puis retourner voir Thrall à Orgrimmar.",
    [5728] = "Tuer Bazzalan et Jergosh l'Invocateur avant de retourner voir Thrall à Orgrimmar.",
    [5729] = "Parler à Neeru Fireblade à Orgrimmar.",
    [5730] = "Parler à Thrall à Orgrimmar et lui dire ce que vous avez appris.",
    [5741] = "Prendre le Sceptre de lumière et le rapporter à Azore Aldamort, dans la tour d’Ethel Rethor.",
    [5742] = "Écouter ce que Tirion Fordring a à dire.",
    [5761] = "Pénétrer dans le Gouffre de Ragefeu et tuer Taragaman l'Affameur, puis rapporter son coeur à Neeru Fireblade à Orgrimmar.",
    [5762] = "Apporter la Caisse de Kravel à Hemet Nesingwary, à Strangleronce.",
    [5763] = "Apporter la Corne de kodo de Roon à Hemet Nesingwary à Strangleronce.",
    [5781] = "Aller au caveau de Zaeldarr - situé dans la section la plus au sud des Maleterres de l’est - et récupérer le Marteau de Taelan. Retourner auprès de Tirion Fordring après avoir accompli la mission.",
    [5801] = "Emporter le Moule de Clé squelette et 2 Barres de thorium au sommet de la crête de la Fournaise dans le cratère d’Un'Goro. Utiliser le Moule de Clé squelette au lac de lave pour forger la Clé squelette inachevée. Apporter la Clé squelette inachevée à l’alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l’ouest.",
    [5802] = "Prendre le moule de la Clé squelette et deux barres de thorium au sommet de la crête de la Fournaise dans le cratère d'Un'Goro. Se servir du moule de la Clé squelette pour forger la Clé squelette inachevée. Apporter la Clé squelette inachevée à l'Apothicaire Dithers à la Barricade, Maleterres de l'Ouest.",
    [5803] = "Vaincre Araj l'Invocateur et apporter le Scarabée d'Araj à l’alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l’ouest.",
    [5804] = "Vaincre Araj l'Invocateur et apporter le Scarabée d'Araj à l’apothicaire Dithers à la Barricade, dans les Maleterres de l’ouest.",
    [5821] = "Escorter la Caravane de Gizelton et l’aider à passer le village des centaures Kolkar. Parler à Smeed, au camp de Scrabblescrew, pour toucher la récompense.",
    [5845] = "Se rendre à Valnord, dans la région nord-est des Maleterres de l’est, et récupérer le Symbole de l’honneur perdu. Revenir auprès de Tirion Fordring quand la tâche est accomplie.",
    [5846] = "Voyager jusqu’à l’île de Caer Darrow, dans la région centre-sud des Maleterres, et chercher un indice de l’emplacement du tableau.",
    [5848] = "Se rendre à Stratholme, dans la partie nord des Maleterres. C’est dans le Bastion écarlate que se trouve le tableau De l'amour et de la famille, caché derrière une autre peinture représentant les lunes jumelles. Rapporter le tableau à Tirion Fordring.",
    [5861] = "Se rendre au tombeau d’Uther, au sud des Maleterres. Montrer à Myranda la Mégère le Don de Tirion.",
    [5862] = "Parler à Myranda pour obtenir l’Illusion écarlate. Aller à Âtreval pendant que vous êtes sous l’effet de l’Illusion écarlate, et apporter le Don de Tirion au généralissime Taelan Fordring. Âtreval se trouve au nord, et Taelan devrait se trouver à l’intérieur du Donjon de Mardenholde.",
    [5863] = "Andi Lynn de Gadgetzan veut que vous détruisiez la Base des Cognedunes en tuant 10 Brutes Cognedunes, 10 Massacreurs Cognedunes, et Gor'marok le Ravageur.",
    [5881] = "Maggran voudrait que vous apportiez une lettre à Grish Longrunner, à la Grande élévation, dans les Tarides.",
    [5892] = "Apporter 10 Fournitures de Gouffrefer à l’Intendant de l'Alliance de Dun Baldar.",
    [5893] = "Apporter 10 Fournitures de Froide-dent à l’intendant de la Horde, au donjon Loup-de-Givre.",
    [5901] = "Utiliser le Pot de Termites vide sur la Termitière, dans les Maleterres de l’est. Après avoir récupéré 100 Termites des Maleterres, retourner voir Mickey Levine, à la Barricade, dans les Clairières de Tirisfal.",
    [5902] = "Trouver un endroit judicieux, au centre de la scierie de la Crête du nord, dans les Maleterres de l’ouest, pour placer le Tonneau de Termites des Maleterres.",
    [5903] = "Utiliser le Pot de Termites vide sur la Termitière, dans les Maleterres de l’est. Après avoir récupéré 100 Termites des Maleterres, retourner voir Nathaniel Dumah, au camp du Noroît, dans les Maleterres de l’ouest.",
    [5904] = "Trouver un endroit propice, au centre de la scierie de la Crête du nord, dans les Maleterres de l’ouest, pour placer le Tonneau de Termites des Maleterres.",
    [5921] = "Utiliser le sort \"Téléportation : Reflet-de-Lune\" pour aller à Reflet-de-Lune. Une fois sur place, parler à Dendrite Starblaze, au village de Havrenuit.",
    [5922] = "Utiliser le sort \"Téléportation : Reflet-de-Lune\" pour aller à Reflet-de-Lune. Une fois sur place, parler à Dendrite Starblaze, au village de Havrenuit.",
    [5923] = "Parler à Mathrengyl Bearwalker, dans l’Enclave cénarienne, à Darnassus.",
    [5924] = "Parler à Mathrengyl Bearwalker, dans l’Enclave cénarienne, à Darnassus.",
    [5925] = "Parler à Mathrengyl Bearwalker, dans l’Enclave cénarienne, à Darnassus.",
    [5926] = "Parler à Turak Runetotem, sur la Cime des Anciens de Thunder Bluff.",
    [5927] = "Parler à Turak Runetotem, sur la Cime des Anciens de Thunder Bluff.",
    [5928] = "Parler à Turak Runetotem, sur la Cime des Anciens de Thunder Bluff.",
    [5929] = "Aller voir l'esprit du Grand ours, au nord-ouest de Reflet-de-Lune et apprendre ce qu'il peut vous enseigner sur la nature de l'ours. Quand cela est fait, retourner voir Dendrite Starblaze, à Havrenuit, dans Reflet-de-Lune.",
    [5930] = "Aller voir l'esprit du Grand ours, au nord-ouest de Reflet-de-Lune et apprendre ce qu'il peut vous enseigner sur la nature de l'ours. Quand cela est fait, retourner voir Dendrite Starblaze, à Havrenuit, dans Reflet-de-Lune.",
    [5931] = "Retourner à Darnassus et parler à Mathrengyl Bearwalker, dans l’Enclave cénarienne.",
    [5932] = "Retourner à Thunder Bluff, et parler à Turak Runetotem, sur la Cime des Anciens.",
    [5941] = "Apporter la Liasse de reliques à Chromie, à Andorhal.",
    [5942] = "Utiliser la Clé de Joseph sur le Coffre de Joseph.",
    [5943] = "Escorter la caravane de Gizelton à travers le convent de Mannoroc. Parler à Smeed, au camp de Scrabblescrew, pour toucher la récompense.",
    [5944] = "Escortez Taelan Fordring jusqu'à la sortie d’Âtreval.",
    [5961] = "Parler à Nathanos le Flétrisseur, dans les Maleterres de l’est. Il se trouve actuellement à la ferme des Marris.",
    [5981] = "Rivern Frostwind voudrait que vous tuiez 4 Géants Cognegivre et 4 Protecteurs Cognegivre.",
    [6001] = "Utiliser la Poussière de lune cénarienne sur la Pierre des séléniens d’Auberdine pour invoquer Lunegriffe. Affronter Lunegriffe, et gagner la force physique et spirituelle qu’il possède. Quand cela est fait, parler à Mathrengyl Bearwalker, à Darnassus.",
    [6002] = "Utiliser la Poussière lunaire cénarienne sur la Pierre des séléniens, entre Mulgore et les Tarides, pour invoquer Lunegriffe. Affronter Lunegriffe, et gagner la force physique et spirituelle qu’il possède. Quand cela est fait, parler à Turak Runetotem, à Thunder Bluff.",
    [6004] = "Tuer deux Médecins écarlates, deux Chasseurs écarlates, deux Magi écarlates et deux Chevaliers écarlates avant de revenir vers Krista Deepshadow dans les Maleterres de l'ouest.",
    [6021] = "Apporter la Tête de Zaeldarr au Conservateur Alen, à la chapelle de l'Espoir de Lumière.",
    [6022] = "Allez à l'est à la Croisée de Corin et détruisez les membres du Fléau qui habitent la ville. Rassemblez sept morceaux de Pourriture vivante en moins de dix minutes. Utilisez le Mortier et le pilon pour réduire la Pourriture vivante en Pourriture coagulée.",
    [6023] = "Tuer le veneur Radley et le cavalier Durgen, avant de retourner voir Kirsta Deepshadow, dans les Maleterres de l’ouest.",
    [6024] = "Tuer l’Infiltrateur Hameya. Utiliser sa clé sur le Monticule de poussière, derrière le caveau de Zaeldarr.",
    [6025] = "Aller dans Âtreval, et trouver un poste d’observation élevé d’où voir la ville et jauger les forces de la Croisade écarlate, puis retourner voir Kirsta Deepshadow, dans les Maleterres de l’ouest.",
    [6026] = "Smokey LaRue veut que vous lui apportiez 2 Barres de thorium, 1 Bâtonnet doré, 8 Bombes explosives et 8 Déclencheurs instables. Vous devrez trouver un forgeron et un ingénieur pour obtenir ces objets.",
    [6027] = "Obtenir le Livre des Anciens, puis le rapporter à Azore Aldamort, dans la tour d’Ethel Rethor.",
    [6028] = "Apportez le Rapport de Long-guet à l'officier de l'Aube d'argent Pureheart au Camp du Noroît, dans les Maleterres de l'ouest.",
    [6029] = "Livrer le Rapport de Long-guet à l’officier Garush de l'Aube d'argent, à la Barricade, dans les Maleterres de l’ouest.",
    [6030] = "Apportez le livre \" Etudes sur la langue des Esprits \" au duc Nicholas Zverenhoff, à la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est.",
    [6031] = "Apportez 30 pièces d'étoffe runique à Meilosh au Repaire des Grumegueules.",
    [6032] = "Apporter 2 pièces d’Etoffe lunaire à Meilosh, au Repaire des Grumegueules.",
    [6041] = "Aller à Pestebois, au nord-ouest de la chapelle de l'Espoir de Lumière. Détruire 8 Bâtiments du Fléau en utilisant le Mélange spécial de Smokey sur les Marques de détonation que portent les bâtiments destinés à être détruits. Smokey a fait marquer les ziggourats et les abattoirs. Une fois la bombe placée, quitter le bâtiment et contempler le résultat de votre opération. Garder en tête que le Mélange spécial de Smokey est très... instable.",
    [6042] = "Tuer 20 Chauves-souris pestiférées nuisibles et 10 Chauves-souris pestiférées monstrueuses. Retourner voir Nathanos le Flétrisseur quand ce sera fait.",
    [6061] = "Utiliser le Bâtonnet de domptage pour dompter un trotteur des plaines adulte. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, à Sabot-de-Sang.",
    [6062] = "Utiliser le Bâtonnet de domptage pour dompter un sanglier tacheté redoutable. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Thotar de Tranchecolline.",
    [6063] = "Utiliser le Bâtonnet de domptage pour dompter une Rôdeuse Tissebois. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar.",
    [6064] = "Utiliser le Bâtonnet de domptage pour dompter un Grand sanglier des rochers. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Grif Wildheart, à Kharanos.",
    [6065] = "Parler à Yaw Sharpmane, au village Bloodhoof.",
    [6066] = "Parler à Yaw Sharpmane, au village Bloodhoof.",
    [6067] = "Parler à Yaw Sharpmane, à Sabot-de-Sang.",
    [6068] = "Parler à Thotar, à Tranchecolline.",
    [6069] = "Parler à Thotar, à Tranchecolline.",
    [6070] = "Parler à Thotar, à Tranchecolline.",
    [6071] = "Parler à Dazalar, à Dolanaar.",
    [6073] = "Parler à Dazalar, à Dolanaar.",
    [6074] = "Parler à Grif Wildheart, à Kharanos.",
    [6075] = "Parler à Grif Wildheart, à Kharanos.",
    [6076] = "Parler à Grif Wildheart, à Kharanos.",
    [6081] = "Adressez-vous à Orkmar Grimshot à Orgrimmar.",
    [6082] = "Domptez un Scorpide blindé à l'aide du Bâtonnet de domptage. Entraînez-vous puis retournez voir Thotar à Tranchecolline.",
    [6083] = "Utiliser le Bâtonnet de domptage pour dompter un Clampant de l'écume. S’entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Thotar, à Tranchecolline.",
    [6084] = "Domptez un Léopard des neiges à l'aide du Bâtonnet de domptage. Entraînez-vous puis retournez voir Grif Wildheart à Kharanos.",
    [6085] = "Domptez un ours Griffeglace à l'aide du Bâtonnet de domptage. Entraînez-vous puis retournez voir Grif Wildheart à Kharanos.",
    [6086] = "Adressez-vous à Belia Thundergranite à Forgefer.",
    [6087] = "Utiliser le Bâtonnet de domptage pour dompter un Traqueur des prairies. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, à Sabot-de-Sang.",
    [6088] = "Utiliser le Bâtonnet de domptage pour dompter un Rapace. S’entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, à Sabot-de-Sang.",
    [6089] = "Parler à Holt Thunderhorn, sur la Cime des Chasseurs, à Thunder Bluff.",
    [6101] = "Utiliser le Bâtonnet de domptage pour dompter un Rôdeur sabre-de-nuit. S’entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar.",
    [6102] = "Utiliser le Bâtonnet de domptage pour dompter un Hurleur Strigid. S’entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar.",
    [6103] = "Parler à Jocaste, à l'enclave cénarienne de Darnassus.",
    [6121] = "Aller à Reflet-de-Lune, et parler à Dendrite Starblaze, au village de Havrenuit.",
    [6122] = "Utiliser une Fiole d'échantillon des Chutes de la Bondissante vide pour collecter un échantillon d’eau, à l’entrée de la grotte, à proximité des Chutes. Apporter la Fiole d'échantillon des Chutes de la Bondissante remplie à Alanndarian Nightsong, à Auberdine, dans Sombrivage.",
    [6123] = "Apporter 5 Terrestrines et 12 Champignons lunaires à Alanndarian Nightsong, à Auberdine ; elle pourra ainsi commencer à préparer son remède.",
    [6124] = "Utiliser le Remède pour animaux sur 10 Daims malades qui se trouvent dans Sombrivage ; ceci les soignera. Les Daims malades ont été aperçus d’abord entre le sud de la rivière Bondissante et le nord d’Auberdine ; on en trouve également tout au sud de Sombrivage, à la frontière d’Ashenvale.",
    [6125] = "Retourner voir Mathrengyl Bearwalker, dans l’Enclave cénarienne, à Darnassus.",
    [6126] = "Aller à Reflet-de-Lune, et parler à Dendrite Starblaze, au village de Havrenuit.",
    [6127] = "Utiliser la Fiole d'échantillon vide du Pic de Brume-funeste pour collecter un échantillon de l’eau d’un bassin, au sommet du Pic de Brume-funeste. Apporter ensuite la Fiole d'échantillon remplie à Tonga Runetotem, à la Croisée, dans les Tarides.",
    [6128] = "Apporter 5 Terrestrines et 5 Cornes de kodo à Tonga Runetotem, à la Croisée, pour qu'il puisse préparer un baume curatif.",
    [6129] = "Utiliser le Remède pour animaux sur 10 Gazelles malades qui se trouvent dans la partie nord des Tarides ; ceci les soignera. Les Gazelles malades ont été vues au nord de la route orientée est-ouest qui traverse la Croisée.",
    [6130] = "Retourner voir Turak Runetotem, sur la Cime des Anciens, à Thunder Bluff.",
    [6132] = "Escorter Melizza Brimbuzzle, puis parler à Hornizz Brimbuzzle au cimetière des Kodos en Désolace.",
    [6133] = "Aller vers la frontière nord des Maleterres de l’est et récupérer le Registre de Quel'Thalas. L’objet se trouve quelque part dans le gîte de Quel'Lithien. Tuer également 8 Forestiers, 8 Eclaireurs et 8 Bûcherons.",
    [6134] = "Apporter 8 Fantôm-o-plasmes et la Caisse d'aimants fantômes à Hornizz Brimbuzzle, en Désolace.",
    [6135] = "Trouver Crépuscaile et la tuer. Récupérer une Touffe de fourrure de Crépuscaile sur son cadavre, puis l’apporter à Nathanos le Flétrisseur. Il paraît que Crépuscaile hante les terres qui se trouvent au nord de la ferme des Marris.",
    [6136] = "Trouver Creusechair, dans les terres au nord des Maleterres de l’est, et le tuer. Retourner voir Nathanos le Flétrisseur quand la mission sera terminée.",
    [6141] = "Adressez-vous au frère Anton, en Désolace.",
    [6142] = "Trouver 10 morceaux de Chair de praire et les apporter à Mai'Lahii, à Proie-de-l'Ombre.",
    [6143] = "Tuer 7 Myrmidons Ondulame, 7 Nagas Ondulame et 5 Sorcières Ondulame, puis parler à Drulzegar, à Proie-de-l'Ombre, en Désolace.",
    [6144] = "Aller à Fossoyeuse et parler à Varimathras.",
    [6145] = "Retourner dans les Maleterres de l’est et traquer le Messager cramoisi, le tuer et récupérer les Ordres du Grand Croisé. Apporter les Ordres à Nathanos le Flétrisseur pour obtenir des instructions supplémentaires.",
    [6146] = "Aller à la Main de Tyr, au sud-est de la ferme des Marris. Une fois sur place, mordre dans la Pomme pourrie. Profiter d’avoir revêtu l’apparence d’un membre de la Croisade écarlate pour apporter les Ordres du Grand Croisé au Grand maître Valdelmar.",
    [6147] = "Retourner voir Nathanos le Flétrisseur avec la nouvelle information.",
    [6148] = "La Croisade écarlate fait mouvement. Quelque part le long de la route, entre la Main de Tyr et Stratholm, vous trouverez l’Oracle Demetria et sa fratrie. La tuer et retourner voir Nathanos le Flétrisseur.",
    [6161] = "Trouver la Clé d'argent de Rackmore. Trouver la Clé d'or de Rackmore. Trouver et ouvrir le Coffre de Rackmore.",
    [6162] = "Tuer le Seigneur Ror et apporter sa Griffe à Dreka'Sur, au Poste de la Vénéneuse, en Gangrebois.",
    [6163] = "Aller à Stratholme et tuer Ramstein Grandgosier. Prendre sa tête, et l’apporter à Nathanos.",
    [6164] = "Apporter le Livre de compte d'Augustus à Augustus le Touché à Val-Terreur.",
    [6181] = "Apporter la Note de Lewis à Thor, le Maître des gryphons.",
    [6182] = "Parler à Mathias Shaw, dans la vieille ville de Hurlevent. Il se trouve dans la caserne.",
    [6183] = "Reparlez à Mathias Shaw, quand vous aurez décidé d’accepter son travail.",
    [6184] = "Allez au camp du Noroît, dans les Maleterres de l’ouest, et rencontrez votre contact, Flint Shadowmore.",
    [6185] = "Fouillez les Maleterres de l’est pour trouver des indices relatifs au \"Flétrisseur\" et aux agents du SI:7 portés disparus. Si vous trouvez un quelconque Insigne du SI:7, rapportez-le à Flint Shadowmore, au camp du Noroît.",
    [6186] = "Retourner à Hurlevent et informer le généralissime Bolvar Fordragon du destin de Nathanos Marris.",
    [6187] = "Montez une armée et portez-vous vers les Maleterres de l’est. Lancez un assaut total sur Nathanos le Flétrisseur et détruisez tout misérable élément de la Horde qui tenterait de le défendre. Gardez votre présence d’esprit, <name> : la Horde le défendra jusqu’à la mort.",
    [6261] = "Apportez la Caisse d'Osric à Dungar Longdrink, le Maître des gryphons.",
    [6281] = "Achetez un voyage en gryphon à Thor, Maître des gryphons, puis apportez la Note de Lewis à Osric Strang au magasin “Immunité limitée”, dans la vieille ville de Hurlevent.",
    [6282] = "Maggran Earthbinder de la retraite de Roche-Soleil veut que vous anéantissiez sept Harpies, sept Embusquées, sept Tueuses et sept Volplumes Rougefuries.",
    [6283] = "Maggran, à la Retraite de Roche-Soleil, vous demande de détruire la Déchiqueteuse Rougefurie et de rapporter son corps comme preuve de votre exploit.",
    [6284] = "Tuer Besseleth, et apporter le Croc de Besseleth à Maggran, dans la Retraite de Roche-Soleil.",
    [6285] = "Achetez un voyage en gryphon pour la Colline des sentinelles à Dungar Longdrink, Maître des gryphons, puis apportez la Caisse d'Olric à Lewis à la Colline des sentinelles.",
    [6301] = "Tammra Windfield, de la retraite de Roche-Soleil, vous demande de rassembler 10 Graines de Gaea.",
    [6321] = "Apporter l’Ordre de Podrig à Karos Razok.",
    [6322] = "Apporter la Caisse de Gordon à Michael Garret.",
    [6323] = "Acheter un voyage en chauve-souris pour Fossoyeuse, auprès du Maître des chauves-souris, Karos Razok, puis apporter l’Ordre de Podrig à Gordon Wendham, à Fossoyeuse.",
    [6324] = "Acheter un voyage en chauve-souris pour le Sépulcre, auprès du Maître des chauves-souris Michael Garret, puis apporter la Caisse de Gordon au Garde noir Podrig, au Sépulcre.",
    [6341] = "Apporter la Collection de Nessa à Vesprystus.",
    [6342] = "Prenez un hippogryphe vers Auberdine chez le maître des hippogryphes Vesprystus, puis apportez la Collection de Nessa à Laird.",
    [6343] = "Réponse de Laird à Nessa Shadowsong.",
    [6344] = "Parler à Nessa Shadowsong.",
    [6361] = "Apporter le Tas de peaux au Maître des Cavaliers célestes, Devrak, à la Croisée.",
    [6362] = "Acheter un voyage pour Thunder Bluff, auprès du Maître des Cavaliers célestes, Devrak, puis apporter le Tas de peaux à Ahanu, à Thunder Bluff.",
    [6363] = "Apporter les Marchandises en cuir d'Ahanu à Tal, à Thunder Bluff.",
    [6364] = "Acheter un voyage pour la Croisée auprès du Maître des Cavaliers célestes Tal, puis apporter les Marchandises en cuir d’Ahanu à Jahan Hawkwing.",
    [6365] = "Apporter la Chair de Zargh à Devrak, à la Croisée.",
    [6381] = "Planter 10 Graines de Gaea sur les Monticules de Gaea, puis parler à Tammra, à la Retraite de Roche-Soleil.",
    [6382] = "Parler à Senani Thunderheart, au Poste de Bois-brisé, à Ashenvale.",
    [6384] = "Acheter un voyage pour Orgrimmar, auprès du Maître des Cavaliers célestes, Devrak, puis apporter la Chair de Zargh à Gryshka, à Orgrimmar.",
    [6385] = "Apporter la Lettre de Gryshka à Doras, à Orgrimmar.",
    [6386] = "Acheter un voyage pour la Croisée auprès du Maître des Cavalier célestes, Doras, puis apporter la Lettre de Gryshka à Zargh, à la Croisée.",
    [6387] = "Apportez la Liste de Brock à Thorgrum Borrelson à Thelsamar.",
    [6388] = "Apportez les Pioches d'honneur à Gryth Thurden à Forgefer.",
    [6389] = "Libérez les Termites des Maleterres dans la scierie de la Crête du nord, puis retournez voir Nathaniel Dumah, au camp du Noroît, dans les Maleterres de l'ouest, avec le Tonneau de Termites des Maleterres.",
    [6390] = "Libérez les Termites des Maleterres dans la scierie de la Crête du nord, puis retournez voir Mickey Levine, à la Barricade, dans les Clairières de Tirisfal, avec le Tonneau de Termites des Maleterres.",
    [6391] = "Acheter un billet de gryphon pour Forgefer, auprès du Maître des gryphons, Thorgrum Borrelson, puis apporter la Liste de Brock à Golnir Bouldertoe, à Forgefer.",
    [6392] = "Acheter un billet de gryphon pour Thelsamar, auprès du Maître des gyphons Gryth Thurden, puis apporter les Pioches d'honneur à Brock Stoneseeker, à Thelsamar.",
    [6393] = "Apporter 10 Incendrites à Tsunaman, dans la Retraite de Roche-Soleil.",
    [6394] = "Apportez la Pioche de Thazz'rill au contremaître Thazz'rill.",
    [6395] = "Apporter le Cadavre de Samuel Fipps sur la Tombe de Marla, puis retourner voir la novice Elreth.",
    [6401] = "Apprendre la bonne nouvelle à Tammra Windfield, dans la Retraite de Roche-Soleil.",
    [6402] = "Aller à la Cité de Hurlevent et se rendre aux portes de la ville. Parlez à l'écuyer Rowe, afin qu'il informe le maréchal Windsor de votre arrivée.",
    [6403] = "Suivez Reginald Windsor dans Hurlevent. Protégez-le de tout danger ! Parlez à l’écuyer Rowe si vous avez de nouveau besoin de contacter Reginald Windsor.",
    [6421] = "Explorer la grotte du ravin des Eboulis, et apporter 10 Cristaux de résonite à Mor'rogal, dans la Retraite de Roche-Soleil.",
    [6441] = "Collecter 16 Cornes de satyre pour Pixel, au Poste de Bois-brisé.",
    [6442] = "Apporter 20 Têtes d'Irequeue à Marukai, le long de la grève de Zoram.",
    [6461] = "Xen'zilla, à Malaka'Jin, voudrait que vous tuiez 10 Rampants des mousses profondes et 7 Venimeux des mousses profondes.",
    [6462] = "Apporter 8 Charmes trolls à Mitsuwa, à l’Avant-poste de Zoram'gar.",
    [6481] = "Ouvrir la Gangue de résonite avec le Cristal de résonite enchanté, puis tuer Goggeroc. Retourner voir Mor'rogal pour l'informer et lui rapporter le Cristal de résonite enchanté.",
    [6482] = "Escorter Ruul, puis parler à Yama Snowhoof, au Poste de Bois-brisé.",
    [6501] = "Vous devez écumer le monde pour pouvoir rétablir le pouvoir du Fragment de l'Oeil de dragon. La seule information dont vous disposez à propos de cette chose, c’est qu’elle existe.",
    [6502] = "Récupérez le sang du Champion des dragons noirs sur le général Drakkisath. Il se trouve dans sa salle du trône, derrière les halls d’Ascension, dans le pic Rochenoire.",
    [6503] = "Tuer 9 Estafettes d'Ashenvale, puis retourner voir Kuray'bin, à l’avant-poste de Bois-brisé.",
    [6504] = "Trouver les 12 pages manquantes du Manuel d'utilisation du Déchiqueteur, puis les rassembler pour constituer les Chapitres 1, 2, et 3. Ramener les pages à Gurda Ragescar près du poste de Bois-brisé.",
    [6521] = "Apporter la Tête de l'Ambassadeur Malcin à Varimathras, à Fossoyeuse.",
    [6522] = "Apporter le Petit parchemin à Varimathras, à Fossoyeuse.",
    [6523] = "Escorter Kaya Flathoof au Camp Aparaje, puis retourner voir Makaba Flathoof, à côté de la frontière sud-est des Serres-Rocheuses.",
    [6541] = "Faire un rapport à Kadrak, dans la tour de guet, dans le nord des Tarides.",
    [6542] = "Faire un rapport à Kadrak, dans la tour de guet, dans le nord des Tarides.",
    [6543] = "Apporter les Rapports du clan Chanteguerre à l’Eclaireur chanteguerre, au Messager chanteguerre et au Voltigeur chanteguerre. Rapporter leurs comptes rendus mis à jour à Kadrak, dans la tour de guet nord, dans les Tarides.",
    [6544] = "Escorter Torek lors de son attaque contre l’Avant-poste d'Aile-argent et Duriel Moonfire, puis faire un rapport à Ertog Ragetusk, au Poste de Bois-brisé.",
    [6548] = "Tuez 8 Forbans du Totem sinistre et 6 Mercenaires du Totem sinistre, puis retournez voir Makaba Flathoof, près de la lisière sud-est des Serres-Rocheuses.",
    [6561] = "Apporter la tête du Seigneur du crépuscule Kelris à Bashana Runetotem, à Thunder Bluff.",
    [6562] = "Parler à Je'neu Sancrea, à Ashenvale.",
    [6563] = "Apporter 20 Saphirs d'Aku'Mai à Je'neu Sancrea, à Ashenvale.",
    [6564] = "Apporter la Note humide à Je'neu Sancrea, à Ashenvale.",
    [6565] = "Tuer Lorgus Jett, dans les Profondeurs de Brassenoire et retourner voir Je'neu Sancrea, à Ashenvale.",
    [6566] = "Écouter Thrall.",
    [6567] = "Chercher Rexxar. Le Chef de guerre vous a dit où il était. Chercher sur les chemins de Désolace, entre les Serres-Rocheuses et Feralas.",
    [6568] = "Apporter le Testament de Rexxar à Myranda la Mégère, dans les Maleterres de l’ouest.",
    [6569] = "Aller au pic Rochenoire et collecter 20 Yeux de draconide noir. Retourner voir Myranda la Mégère, quand la tâche sera terminée.",
    [6570] = "Aller à la tourbière du Ver, dans le marécage d'Âprefange, et chercher la tanière de Brandeguerre. Une fois à l’intérieur, porter l’Amulette de subversion draconique, et parler à Brandeguerre.",
    [6571] = "Collecter les Fournitures chanteguerres : Lames du clan Chanteguerre, Huile des Chanteguerres, et la Cargaison de Haches des Chanteguerres ayant pour destinataire Locke Okarr, au Poste de Bois-brisé.",
    [6582] = "Vous devez trouver Clairvoyant, le drake champion du Vol bleu, et le tuer. Arracher son crâne à son cadavre, et le rapporter à Brandeguerre. Clairvoyant se trouve au Berceau-de-l'Hiver.",
    [6583] = "Détruire le Champion drake du Vol vert, Somnus. Arracher son crâne à son cadavre, puis le rapporter à Brandeguerre.",
    [6584] = "Chronalis, enfant de Nozdormu, garde les Grottes du temps, dans le Désert de Tanaris. Tuez-le et rapportez son crâne à Brandeguerre.",
    [6585] = "Aller à Grim Batol et traquer Axtroz, le Champion drake du Vol rouge. Le tuer et arracher son crâne, puis l’apporter à Brandeguerre.",
    [6601] = "Il semble que la comédie soit finie. Vous savez que l’Amulette de subversion draconique, créée par Myranda la Mégère, ne fonctionnera pas à l’intérieur du pic Blackrock. Peut-être devriez-vous trouver Rexxar et lui exposer votre fâcheuse situation. Montrez-lui l'Amulette drakefeu terne. Avec un peu de chance, il saura quoi faire.",
    [6602] = "Aller au Pic Blackrock, et tuer le général Drakkisath. Récupérer son sang et retourner voir Rexxar.",
    [6603] = "Trouver Donova Snowden, à côté des sources chaudes du Berceau-de-l'Hiver.",
    [6604] = "Parler à Jaron Stoneshaper, au village de Pluie-d'Etoiles.",
    [6605] = "Parler à Winna Hazzard, à Gangrebois.",
    [6607] = "Nat Pagle voudrait que vous attrapiez les poissons suivants : Le Mahi Mahi de Brumejonc, de la grève de Brumejonc, dans le marais des Chagrins. Un Frappeur Sar'theris, de la grève de Sar'theris en Désolace. L'Ahi de Feralas, de la rivière Verdantis de Feralas. Le Sailfin bleu de la Côte sauvage, de la Côte sauvage de la vallée de Strangleronce. Retournez voir Nat Pagle quand la collecte sera terminée.",
    [6608] = "Vous pensez que Lumak essaie de vous dire qu’il ne peut plus vous aider à améliorer votre compétence de pêche. Vous devriez essayer de vous adresser maintenant à son ami, Nat Pagle, un pêcheur humain des îles au sud de Theramore (c’est du moins ce que vous croyez comprendre du discours de Lumak).",
    [6609] = "Aller à Kalimdor, dans la ville côtière de Theramore. À partir de là, chercher une île au sud de la ville principale. Nat Pagle vous attend !",
    [6610] = "Dirge Quikcleave voudrait que vous lui apportiez les objets suivants : 12 Oeufs géants. Vous les trouverez sur les Rocs qui hantent Tanaris ou sur toute autre espèce de grand oiseau. 10 morceaux de Chair de palourde piquante. Vous pouvez trouver la chair de palourde sur... les palourdes, naturellement ! 20 Emmentals d'Alterac. Vous les trouverez dans une fromagerie ! Collectez tous ces objets, puis retournez voir Dirge.",
    [6611] = "Aller à Gadgetzan, dans le Désert de Tanaris, et parler de votre carrière de cuisinier à Dirge Quikcleave.",
    [6612] = "Aller à Gadgetzan, dans le Désert de Tanaris, et parler de votre carrière de cuisinier à Dirge Quikcleave.",
    [6621] = "Placer la Bannière de Karang sur le Monticule du totem Vile-sylve. Ne pas laisser les furbolgs détruire la Bannière. Tuer le chef Murgut, et apporter le Totem de Murgut à Karang Amakkar, à Zoram'gar.",
    [6622] = "Sauver des patients en utilisant des Bandages de Triage, afin de panser leurs blessures. Vous devez sauver 15 patients avant que 6 d’entre eux ne meurent de leurs blessures. Rappelez-vous l’ordre du triage ! Les Soldats agonisants meurent les premiers, suivis des Soldats grièvement blessés. Les Soldats blessés sont ceux qui meurent les derniers, et ils doivent être soignés APRES ceux qui agonisent et ceux qui sont grièvement blessés ; selon le tri que vous avez fait.",
    [6623] = "Aller au Trépas-d'Orgrim, dans les hautes-terres d'Arathi, et évoquer avec le docteur Gregory Victor la possibilité de rejoindre les rangs des médecins de la Horde.",
    [6624] = "Sauver des patients en utilisant des Bandages de Triage, afin de panser leurs blessures. Vous devez sauver 15 patients avant que 6 d’entre eux ne meurent de leurs blessures. Rappelez-vous l’ordre du triage ! Les Soldats agonisants meurent les premiers, suivis des Soldats grièvement blessés. Les Soldats blessés sont ceux qui meurent les derniers, et ils doivent être soignés APRES ceux qui agonisent et ceux qui sont grièvement blessés ; selon le tri que vous avez fait.",
    [6625] = "Aller à Theramore, dans le marécage d'Âprefange, et parler au docteur Gustaf VanHowzen de la possibilité de rejoindre les rangs des médecins de l’Alliance.",
    [6626] = "Tuer 8 Gardes de guerre Tranchebauge, 8 Tisseurs d'épines Tranchebauge et 8 Sectateur de la Tête de mort, puis retourner voir Myriam Moonsinger, à l’entrée des Souilles de Tranchebauge.",
    [6627] = "Réussir à répondre à la question de Braug Dimspirit, puis lui reparler. Il se trouve dans les Serres-Rocheuses.",
    [6628] = "Réussir à répondre à la question de Parqual Fintallas, puis lui reparler. Il se trouve à Fossoyeuse.",
    [6629] = "Tuer Grundig Darkcloud et 6 Brutes du Totem sinistre, puis retourner voir Makaba Flathoof, à côté de la frontière sud-est des Serres Rocheuses.",
    [6641] = "Garantir la sécurité de Muglash tandis qu’il voyage vers le brasero. L’aider à éteindre le brasero, puis le protéger, en combattant les nagas. En cas de réussite, retourner à l’avant-poste de Zoram'gar et informer le messager chanteguerre de la mort de Vorsha la Flagellante.",
    [6661] = "Capturer 5 Rats des profondeurs en utilisant le Pipeau du dératiseur. Conduire les Rats vers Monty. N’oubliez pas de rendre le Pipeau quand vous aurez terminé.",
    [6662] = "Apporter le Carton de viande mystère à Nipsy, au Dépôt du Tram des profondeurs de Hurlevent.",
    [6681] = "Apporter le Sceau de Ravenholdt à Fahrad, au Manoir de Ravenholdt, dans les collines d'Hillsbrad. Votre sagacité sera mise à l’épreuve tout au long de la route. Préparez-vous.",
    [6721] = "Parler à Dazalar, à Dolanaar.",
    [6722] = "Parler à Dazalar, à Dolanaar.",
    [6761] = "Parler à Mathrengyl Bearwalker, dans l’Enclave cénarienne de Darnassus.",
    [6762] = "Parler à Rabine Saturna, au village de Havrenuit, à Reflet-de-Lune. Reflet-de-Lune se trouve entre Gangrebois et le Berceau-de-l'Hiver. Le chemin qui y mène traverse le Repaire des Grumegueules.",
    [6804] = "Utiliser l’Aspect de Neptulon sur les élémentaires empoisonnés des Maleterres de l’est. Apporter 12 Bracelets discordants et l’Aspect de Neptulon au duc Hydraxis, en Azshara.",
    [6805] = "Tuer 15 Tempétueux de poussière et 15 Grondeurs du désert, puis retourner voir le duc Hydraxis, en Azshara.",
    [6821] = "Apporter l’Oeil du Prophète ardent au duc Hydraxis, en Azshara.",
    [6822] = "Tuer 1 Seigneur du feu, 1 Géant de lave, 1 Chien antique du Magma et 1 Surgisseur de lave, puis retourner voir le duc Hydraxis, à Azshara.",
    [6823] = "Parvenir au niveau de réputation Honoré auprès des Hydraxiens, puis parler au duc Hydraxis, en Azshara.",
    [6824] = "Apporter les Mains de Lucifron, de Sulfuron, de Gehennas et de Shazzrah au duc Hydraxis, en Azshara.",
    [6844] = "Apporter l’Objet silithide incrusté à Umber, l’archiviste du Cercle cénarien, au village de Havrenuit, à Reflet-de-Lune.",
    [6845] = "Parler à Rabine Saturna, au village de Havrenuit, à Reflet-de-Lune.",
    [6921] = "Apporter le Noyau de la brasse à Je'neu Sancrea, à l’Avant-poste de Zoram'gar, dans Ashenvale.",
    [6922] = "Apporter le Globe d'eau étrange à Je'neu Sancrea, à l’Avant-poste de Zoram'gar, dans Ashenvale.",
    [6981] = "Allez à Ratchet pour trouver quelqu'un qui puisse vous en dire plus sur l'Eclat luminescent. Puis livrez l'Eclat, selon les instructions.",
    [6982] = "Apporter 10 Fournitures de Froide-dent à l'intendant de l’Alliance, à Dun Baldar.",
    [6985] = "Apporter 5 Fournitures de Gouffrefer à l'Intendant de la Horde, au donjon Frostwolf.",
    [7001] = "Trouvez un Loup des glaces dans la vallée d’Alterac. Servez-vous de la Muselière loup-de-givre pour « dompter » la bête. Lorsque ce sera fait, le loup des glaces vous suivra jusqu’au Maître des écuries loup-de-givre. Parlez au Maître des écuries loup-de-givre pour être crédité de cette capture.",
    [7003] = "Utilisez l’Ultra-réducteur de Zorbin sur des géants de n’importe quel type en Féralas afin les rendre plus faciles à gérer. Apportez 15 résidus de miniaturisation que vous trouverez sur les versions rétrécies des géants à Zorbin Poudrozieu aux quais de la côte Oubliée, en Féralas.",
    [7027] = "Trouvez un Bélier d'Alterac dans la vallée d'Alterac. Lorsque vous serez à proximité, servez-vous du Collier d'entraînement Stormpike pour le \"dompter\". Une fois dompté, le Bélier d'Alterac vous suivra jusqu'au Maître des écuries. Parlez au Maître des écuries pour être crédité de cette capture.",
    [7028] = "Collecter 25 Ciselures de Cristaux Théradriques pour Saule, en Désolace.",
    [7029] = "Remplir la Fiole céruléenne renforcée, au Bassin de cristal orange, dans Maraudon. En faire usage sur les Vignes de Vylevrille pour forcer les Engeances de Noxxious corrompues à en sortir. Soigner 8 plantes en tuant les Engeances de Noxxious, puis retourner voir Vark Battlescar, à Proie-de-l'Ombre.",
    [7041] = "Remplir la Fiole céruléenne renforcée, au Bassin de cristal orange dans Maraudon. En faire usage sur les vignes de Vylevrille pour forcer les Engeances de Noxxious corrompues à en sortir. Soigner 8 plantes en tuant les Engeances, puis retourner voir Taliendra, à la Combe de Nijel.",
    [7044] = "Retrouver les deux parties du Sceptre de Celebras : le Bâtonnet de Celebras et le Diamant de Celebras. Trouvez un moyen de parler à Celebras.",
    [7046] = "Aidez Celebras le Racheté pendant qu'il recrée le Sceptre de Celebras. Parlez-lui après la réussite du rituel.",
    [7064] = "Anéantir la princesse Theradras et retourner voir Selendra près de Proie-de-l'Ombre, en Désolace.",
    [7065] = "Tuer la princesse Theradras, et retourner voir le Gardien Marandis, à la Combe de Nijel en Désolace.",
    [7066] = "Chercher Remulos à Reflet-de-Lune, et lui donner la Graine de vie.",
    [7067] = "Lire les instructions du paria. Après cela, obtenir l'Amulette d'union de Maraudon et la ramener au centaure renégat, dans le sud de Désolace.",
    [7068] = "Collecter 10 Fragments d'Ombréclats dans Maraudon, et les ramener à Uthel'nay, à Orgrimmar.",
    [7070] = "Collecter 10 Fragments d'Ombréclats, et les porter à l'archimage Tervosh, dans le marécage d'Âprefange.",
    [7081] = "Attaquez un cimetière, puis présentez-vous au caporal Noreg Foudrepique à Dun Baldar.",
    [7082] = "Attaquez un cimetière, puis présentez-vous au caporal Teeka Bloodsnarl dans les montagnes d'Alterac.",
    [7101] = "Prenez une tour ennemie, puis présentez-vous au caporal Teeka Bloodsnarl dans les montagnes d'Alterac.",
    [7102] = "Détruisez la bannière d'une tour ou d'un fortin ennemi, puis présentez-vous au sergent Durgen Foudrepique à Dun Baldar.",
    [7121] = "Parlez à l’Intendant Stormpike.",
    [7122] = "Prenez une mine que les Foudrepiques ne contrôlent pas, puis présentez-vous à l’intendant Foudrepique à Dun Baldar.",
    [7123] = "Parlez à l’Intendant Frostwolf.",
    [7124] = "Prenez une mine, puis présentez-vous au caporal Teeka Bloodsnarl dans les montagnes d'Alterac.",
    [7141] = "Entrez dans la vallée d'Alterac, tuez Drek'thar, le général de la Horde, puis retournez voir la Prospectrice Stonehewer dans les montagnes d'Alterac.",
    [7142] = "Entrez dans la vallée d'Alterac, tuez Vanndar Foudrepique, le général nain, puis retournez voir Voggah Deathgrip dans les montagnes d'Alterac",
    [7161] = "Rendez-vous dans les cavernes des Follepattes, au sud-est de la base principale, et récupérez la Bannière loup-de-givre qui s’y trouve. Ramenez-la au Maître de guerre Laggrond.",
    [7162] = "Rendez-vous dans les cavernes de l'Aile de glace, au sud-ouest de la base principale, et récupérez la Bannière Foudrepique qui s’y trouve. Ramenez-la au lieutenant Haggerdin.",
    [7181] = "Korrak le Ragesang se cache dans les profondeurs des cavernes Winterax. D’après la légende, le chef des puissants trolls Winterax ne se montre qu’après la mort de 500 de ses guerriers. Rendez-vous aux cavernes Winterax et massacrez tout ce qui vous fait obstacle jusqu’à ce que Korrak se montre. Tuez-le et présentez-vous au Maître de guerre Laggrond.",
    [7201] = "Rejoignez les profondeurs de Rochenoire et trouvez 10 essences des éléments. Commencez vos recherches par les golems et par les créateurs de golems. Vivian Lagrave a aussi marmonné quelque chose à propos d’élémentaires.",
    [7202] = "Korrak le Ragesang se cache dans les profondeurs des cavernes Winterax. D’après la légende, le chef des puissants trolls Winterax ne se montre qu’après la mort de 500 de ses guerriers. Rendez-vous aux cavernes Winterax et massacrez tout ce qui vous fait obstacle jusqu’à ce que Korrak se montre. Tuez-le et présentez-vous au Lieutenant Haggerdin.",
    [7223] = "Apportez 20 Morceaux d’armure à Murgot Deepforge à Dun Baldar.",
    [7224] = "Apportez 20 Morceaux d’armure au forgeron Regzar au village Loup-de-Givre.",
    [7241] = "Rendez-vous dans la vallée d'Alterac, dans les contreforts d'Hillsbrad. Trouvez le maître de guerre Laggrond, parlez-lui et commencez votre carrière comme soldat loup-de-givre.",
    [7261] = "Rendez-vous dans la vallée d'Alterac, dans les contreforts d'Hillsbrad. Présentez-vous au lieutenant Haggerdin. Pour la gloire de Bronzebeard !",
    [7281] = "Pénétrez en territoire foudrepique et tuez le commandant Karl Philips. Lorsque ce sera fait, présentez-vous au commandant Louis Philips.",
    [7282] = "Pénétrez en territoire loup-de-givre et tuez le commandant Louis Philips. Lorsque ce sera fait, présentez-vous au commandant Karl Philips.",
    [7301] = "Enfoncez-vous en territoire loup-de-givre à la recherche des chefs d’escadrille Slidor, Vipore et Ichman. Si vous les retrouvez, présentez-vous au commandant Duffy.",
    [7302] = "Découvrez ce qui est arrivé aux chefs d’escadrille Guse, Jetzor et Mulverick. Lorsque vous les aurez retrouvés, présentez-vous au commandant Mulfort.",
    [7321] = "Apporter 10 morceaux de Viande de tortue et des Epices apaisantes à Christoph Jeffcoat au Moulin-de-Tarren.",
    [7361] = "Vous avez été <chargé/chargée> de tuer les personnages Elfes de la nuit présents dans la vallée d’Alterac. Tuez un Elfe de la nuit et présentez-vous à Najak Maléficas avec une Tête coupée d’Elfe de la nuit.",
    [7362] = "Vous avez été <chargé/chargée> de tuer les personnages gnomes présents dans la vallée d’Alterac. Tuez un Gnome et présentez-vous à Ravak Totem-Sinistre au donjon Loup-de-givre avec une Touffe de cheveux de Gnome.",
    [7363] = "Vous avez été <chargé/chargée> de tuer les personnages humains présents dans la vallée d’Alterac. Tuez un humain et présentez-vous au commandant Louis Philips (qui fait la navette entre le front et le donjon Loup-de-givre) avec un Bout d’os humain. Un remède à la condition humaine est à portée de main !",
    [7366] = "Vous avez été <chargé/chargée> de tuer les personnages Réprouvés présents dans la vallée d’Alterac. Tuez un Réprouvé et présentez-vous au commandant Karl Philips (qui fait la navette entre le scierie et la mine) avec un Cœur de Réprouvé.",
    [7381] = "Si Korrak le Ragesang devait réapparaître dans le Champ sanglant, traquez-le et tuez-le. Apportez le Crâne de Korrak au Maître de guerre Laggrond dans les contreforts de Hautebrande.",
    [7382] = "Si Korrak le Ragesang réapparaît dans le Champ sanglant, traquez-le et tuez-le. Apportez le Crâne de Korrak au lieutenant Haggerdin dans les Contreforts de Hautebrande.",
    [7383] = "Remplir la Fiole d'améthyste et la rapporter à Corithras Moonrage à Dolanaar.",
    [7441] = "Rendez-vous à Hache-tripes et trouvez le diablotin Pusillin. Persuadez-le par tous les moyens de vous rendre le Livre d’Incantations d’Azj’Tordin. Si vous parvenez à le récupérer, retournez voir Azj’Tordin au Pavillon de Lariss, en Feralas.",
    [7461] = "Vous devez détruire les gardiens qui protègent les 5 Pylônes qui alimentent la Prison d’Immol’thar. Une fois que les Pylônes seront coupés, le champ de force qui entoure Immol’thar se dissipera. Entrez dans la Prison d’Immol’thar et éradiquez l’infâme démon qui se trouve en son cœur. Enfin, affrontez le prince Tortheldrin à l’Athenaeum. Lorsque vous aurez terminé, retournez voir l’Ancienne des Shen’dralar dans la cour.",
    [7463] = "Rendez-vous dans le quartier de Crochebois de Hache-tripes et tuez Hydrogénos, l’élémentaire de l’eau. Retournez voir le Gardien du savoir Lydros à l’Athenaeum avec l’Essence d’Hydrogénos.",
    [7481] = "Fouillez Hache-tripes à la recherche de Telmius Cherche-Rêve. Lorsque vous aurez des informations, donnez-les au Sage Korolusk du Camp Mojache.",
    [7482] = "Fouillez Hache-tripes à la recherche de Telmius Cherche-Rêve. Lorsque vous aurez des informations, donnez-les à l’Erudite Runethorn, à Feathermoon.",
    [7483] = "Apportez un Libram de rapidité, 1 Diamant noir en parfait état, 2 Grands éclats brillants et 2 doses de Sang des héros au Gardien du savoir Lydros à Hache-tripes pour recevoir un Arcanum de rapidité.",
    [7484] = "Apportez un Libram de focalisation, 1 Diamant noir en parfait état, 4 Grands éclats brillants et 2 Peaux des ombres au Gardien du savoir Lydros à Hache-tripes pour recevoir un arcanum de focalisation.",
    [7485] = "Apportez un Libram de protection, 1 Diamant noir en parfait état, 2 Grands éclats brillants et 1 Couture d'abomination effilochée au Gardien du savoir Lydros à Hache-tripes pour recevoir un Arcanum de protection.",
    [7486] = "Allez chercher votre récompense dans le Coffre d’Hydraxis.",
    [7488] = "Ramenez le Filet de Lethtendris à Latronicus Moonspear au bastion de Feathermoon en Feralas.",
    [7489] = "Ramenez le Filet de Lethtendris à Talo Thornhoof au Camp Mojache, en Feralas.",
    [7490] = "Apportez la Tête d’Onyxia à Thrall à Orgrimmar.",
    [7491] = "Allez voir le seigneur Runthak dans la vallée de la Force.",
    [7492] = "Parlez à Talo Thornhoof au Camp Mojache, en Feralas.",
    [7494] = "Parlez à Latronicus Moonspear au bastion de Feathermoon en Feralas.",
    [7495] = "Apportez la Tête d’Onyxia au généralissime Bolvar Fordragon à Stormwind.",
    [7496] = "Allez voir le major Mattingly dans la vallée des Héros.",
    [7498] = "Rendez ce livre à ses légitimes propriétaires.",
    [7499] = "Rendez ce livre à ses légitimes propriétaires.",
    [7500] = "Rendez ce livre à ses légitimes propriétaires.",
    [7501] = "Rendez ce livre à ses légitimes propriétaires.",
    [7502] = "Rendez ce livre à ses légitimes propriétaires.",
    [7503] = "Rendez ce livre à ses légitimes propriétaires.",
    [7504] = "Rendez ce livre à ses légitimes propriétaires.",
    [7505] = "Rendez ce livre à ses légitimes propriétaires.",
    [7506] = "Rendez ce livre à ses légitimes propriétaires.",
    [7507] = "Rapporter « Le guide de Nostro du tueur de dragons » à l’Athenaeum.",
    [7508] = "Donnez la Lame elfique inachevée au Gardien du savoir Lydros.",
    [7509] = "Vous devez amener Onyxia à cracher le feu sur la Lame ancienne brute. Lorsque ce sera fait, ramassez la Lame ancienne chauffée. Attention, elle ne restera pas chaude éternellement. Le temps est très important. Avant de revenir me voir, il vous faudra tuer la bête et plonger la Lame ancienne chauffée dans son cadavre. Si vous y parvenez, Quel’Serrar sera à vous.",
    [7562] = "Parler à Mor'zul Bloodbringer dans les Steppes ardentes.",
    [7563] = "Apporter 30 bouteilles de Sang de bêtes enragées à Mor'zul Bloodbringer dans les Steppes ardentes.",
    [7564] = "Apporter la Caisse de sang à Gorzeeki Wildeyes dans les Steppes ardentes.",
    [7581] = "Rendez-vous à Hache-tripes en Feralas et récupérez 15 doses de Sang de satyre sur les satyres Follengeance qui habitent le quartier de Crochebois. Lorsque ce sera fait, retournez voir Levandre à la Balafre impure.",
    [7582] = "Rendez-vous à la gorge du Sombre murmure, dans le Berceau-de-l'Hiver, et récupérez 5 Larmes de l’Hederine sur les démons Hederine qui occupent la gorge. Lorsque ce sera fait, retournez voir Levandre à la Balafre impure.",
    [7583] = "Pénétrez dans la Balafre impure et localisez un Commandant de la garde funeste. Servez-vous de la Prison de cristal luminescente sur lui. Attendez-vous à être sauvagement <attaqué/attaquée>, car le démon fera l’impossible pour éviter d’être capturé. Si vous réussissez, amenez le garde funeste emprisonné à Levadre à la Balafre impure.",
    [7601] = "Parlez à Démonet à Gangrebois.",
    [7602] = "Démonet vous a demandé de lui apporter trois Gangressences parfaites, venant de trois régions distinctes. Les satyres Legashi d'Azshara, les légionnaires de Jaedenar et les gangregardes sentinelles des Terres foudroyées détiennent la Gangressence parfaite de leur région. Récupérez les Gangressences parfaites et rapportez-les à Démonet, à Gangrebois.",
    [7603] = "Fouillez le Val Grêlé pour trouver les restes de Kroshius. Quand vous les aurez localisés, utilisez le Gangrefeu à proximité et attendez le retour de Kroshius. Quand l'Infernal se sera réveillé, tuez-le et prenez le Noyau infernal sur son cadavre. Rapportez le Noyau infernal de Kroshius à Niby le Tout-Puissant, à Gangrebois.",
    [7604] = "Apportez le Contrat de la Confrérie du Thorium à Lokhtos Darkbargainer, si vous voulez recevoir les plans du marteau de sulfuron.",
    [7622] = "Sauvez 50 Paysans avant que 15 d'entre eux aient été tués. Si vous y parvenez, allez parler à Eris Havenfire. Consultez le Panneau des morts pour voir combien de paysans ont été tués.",
    [7623] = "Achetez des Potions des ténèbres à Gorzeeki dans les Steppes ardentes. Servez-vous en pour vous rendre à Jaedenar, et parlez au seigneur Banehollow.",
    [7624] = "Affrontez Ulathek, puis apportez le Coeur du traître au seigneur Banehollow à Jaedenar.",
    [7625] = "Acheter de la Poussière d’étoiles xorothienne à Ur’dan. L’apporter à Gorzeeki dans les Steppes ardentes.",
    [7626] = "Apportez 10 Elixirs de Puissance de l'ombre à Gorzeeki Wildeyes dans les Steppes ardentes.",
    [7627] = "Apportez 6 Grands éclats brilliants et 25 charges de Minerai de sombre fer à Gorzeeki dans les Steppes ardentes.",
    [7628] = "Apportez 35 Ecailles de dragon noir à Gozeeki WIldeyes dans les Steppes ardentes.",
    [7629] = "Apporter le Diablotin en bouteille au laboratoire d'alchimie de la Scholomance. Une fois le parchemin créé, retournez voir Gorzeeki Wildeyes.",
    [7630] = "Apporter 3 Barres d’arcanite à Gorzeeki dans les Steppes ardentes.",
    [7631] = "Lisez les Instructions de Mor’zul. Invoquez un Destrier de l’effroi xorothien, vainquez-le, et liez son esprit.",
    [7632] = "Trouvez le propriétaire de la Feuille ancienne pétrifiée. Bonne chance, <nom>, le monde est vaste.",
    [7634] = "L'Ancien Hasat vous demande de lui ramener un Tendon de dragon bleu adulte. Si vous en trouvez un, ramenez-le-lui à Gangrebois",
    [7635] = "L’Ancien Stoma vous demande de lui ramener un Tendon de dragon noir adulte. Si vous en trouvez un, ramenez-le à Stoma à Gangrebois.",
    [7636] = "Vous devez trouver et tuer quatre corrupteurs démoniaques : Simona la Séductrice. Klinfran l’Enragé. Solenor le Tueur. Artorius le Néfaste. Détruisez ces créatures et retournez voir l’Ancien Vartus à Gangrebois. Vous trouverez des indices sur leurs faits et gestes sur l’Ecorce pétrifiée qui se trouve dans votre inventaire. Vous DEVEZ agir seul.",
    [7637] = "Rendez-vous à Forgefer et procurez-vous l’Encensoir d’exorcisme du grand prêtre Rohan. Pour vous le procurer, il vous faudra verser une donation de 150 pièces d’or.",
    [7638] = "Parler au seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Hurlevent.",
    [7639] = "Ramener l’Encensoir d’exorcisme au seigneur Grayson Shadowbreaker, dans le Quartier de cathédrale de Hurlevent.",
    [7640] = "Servez-vous de l’Encensoir d’exorcisme pour chasser les esprits qui tourmentent Val-Terreur. Lorsque vous aurez tué 25 Esprits de Val-Terreur, retournez voir le seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Hurlevent.",
    [7641] = "Parlez à Grimand Elmore dans le Quartier des nains de Hurlevent.",
    [7642] = "Apporter 40 Etoffes runiques, 6 Barres d’arcanite, 10 Larmes d’Arthas, 5 Fioles d’eau sacrée de Stratholme, et 150 pièces d’or à Grimand Elmore, au Quartier des nains de Hurlevent.",
    [7643] = "Procurez-vous un aliment pour chevaux capable de nourrir un esprit équin. Il semble que Merideth Carlson, à Southshore, sache en fabriquer. Ensuite, rendez-vous au donjon de Hache-tripes en Feralas, et tuez Tendris Crochebois. Sa mort libérera l’Ancien esprit équin. Nourrissez-le avec l’aliment spécial afin de l’apaiser. Enfin, donnez-lui le Caparaçon d’arcanite pour qu’il le bénisse.",
    [7644] = "Retourner dans le quartier de la cathédrale de Stormwind avec le Caparaçon d’arcanite béni pour voir le seigneur Grayson Shadowbreaker.",
    [7645] = "Récupérer 20 Biscuits enrichis en manne, l’ingrédient vital qui permet de préparer du Fourrage enrichi en manne, pour le compte de Merideth Carlson de Southore dans les contreforts d’Hillsbrad. L’Aube d’argent est la seule à fabriquer ces biscuits. Vous devrez également lui donner 50 pièces d’or pour apaiser sa susceptibilité.",
    [7646] = "Apportez un Diamant d’Azeroth et un Diamant noir en parfait état au seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind.",
    [7647] = "Utilisez le Clairvoyant au coeur du sous-sol du Grand ossuaire, dans la Scholomance. Cela attirera des esprits que vous devrez juger. Lorsqu’ils seront vaincus, le Chevalier de la mort Ravassombre apparaîtra. Vainquez-le et purifiez l’âme du destrier déchu. Ensuite, donnez l’Ame rachetée du destrier et le Caparaçon enchanté et béni au Destrier déchu de Ravassombre.",
    [7648] = "Présentez le Caparaçon d’arcanite au seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Hurlevent, pour inspection.",
    [7649] = "Rendez ce livre à ses légitimes propriétaires.",
    [7650] = "Rendez ce livre à ses légitimes propriétaires.",
    [7651] = "Rendez ce livre à ses légitimes propriétaires.",
    [7667] = "Si vous voulez aider Sagorne Crestrider de la vallée de la Sagesse d'Orgrimmar, apportez-lui un Diamant d’Azeroth et un Diamant noir en parfait état.",
    [7670] = "Parler au seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind.",
    [7701] = "Loin dans les profondeurs de la Fosse aux scories dans le Chaudron, dans la Gorge des Vents brûlants, vous trouverez le nain traître du clan Sombrefer répondant au nom de surveillant Maltorius. Tuez le surveillant Maltorius et prenez sa tête. Apportez-la au capitaine de guet Lolo Longstriker dans la Gorge des Vents brûlants pour la récompense.",
    [7703] = "Trouvez le Gantelet de Puissance Gordok et rendez-le au capitaine Kromcrush à Hache-tripes. Selon Kromcrush, les histoires des « vieux » racontent que Tortheldrin – un « vilain » elfe qui se fait appeler prince – l’a volé à l’un des rois gordok.",
    [7721] = "Récupérez 10 Noyaux élémentaires d'eau sur les Elémentaires marins et les Embruns le long de la Côte oubliée de Feralas, et rapportez-les à Zorbin Fandazzle, près du quai là-bas.",
    [7722] = "Quelque part dans la Fosse aux scories du Chaudron, vous trouverez les Plans secrets : Flux embrasé dérobés par le surveillant Maltorius. Trouvez ces plans et rapportez-les au Maître forgeron Burninate dans la gorge des Vents brûlants.",
    [7723] = "Hansel Heavyhands veut que vous tuiez 20 Golems de guerre lourds. Les golems de guerre lourds errent dans les régions qui entourent le Chaudron dans la Gorge des Vents brûlants. Quand vous en aurez tué assez, revenez voir Hansel dans la Gorge des Vents brûlants.",
    [7724] = "Hansel Lourdemains veut que vous tuiez 20 araignées de lave incendiaires dans la gorge des Vents brûlants. Vous pouvez trouver les araignées de lave incendiaires dans les plateaux et les mares de lave de la gorge des Vents brûlants. Revenez voir Hansel Lourdemains dans la gorge des Vents brûlants quand vous aurez tué assez de araignées de lave incendiaires.",
    [7725] = "Utilisez l'Ultra-réducteur de Zorbin sur des géants de n'importe quel type en Feralas afin les rendre plus faciles à gérer. Apportez 10 Résidus de miniaturisation que vous trouverez sur les versions rétrécies des géants à Zorbin Fandazzle aux docks de la Côte oubliée en Feralas.",
    [7726] = "Récupérez 6 Noyaux élémentaires d'eau sur les Elémentaires marins et les Embruns le long de la Côte oubliée de Feralas, et rapportez-les à Zorbin Fandazzle, près du quai.",
    [7727] = "Hansel Heavyhands veut que vous tuiez 20 Incendosaures. On peut les trouver dans les bassins de lave de la Fosse aux scories, qui occupe une partie du Chaudron de la gorge des Vents brûlants. Retournez voir Hansel Heavyhands dans la gorge des Vents brûlants lorsque vous aurez tué suffisamment d’Incendosaures.",
    [7728] = "Trouvez la Tuyère de forge et la Longue-vue du guetteur et rapportez-les au sous-chef Scrange dans la gorge des Vents brûlants. Les seules informations dont vous disposez sur ces objets sont les suivantes : ils ont été dérobés par les nains Sombrefer, la Tuyère de forge est un outil utilisé par les forgerons et la Longue-vue du guetteur est un outil de surveillance inestimable pour les guetteurs.",
    [7729] = "Tuez 15 Sous-chefs Sombrefer et 15 Esclavagistes Sombrefer. Revenez voir le sous-chef Scrange dans la gorge des Vents brûlants quand vous aurez accompli cette tâche.",
    [7730] = "Rapportez 20 Carapaces de Zukk'ash à Hadoken Swiftstrider au Camp Mojache en Feralas.",
    [7731] = "Battez Fouet-cuisant dans le Gouffre grouillant et rapportez ses glandes à Hadoken Swiftstrider au Camp Mojache en Feralas.",
    [7732] = "Apportez le rapport sur les Zukk'ash du Camp Mojache à Zilzibin Drumlore. Il réside à la Herse d'Orgrimmar",
    [7733] = "Fournir 10 Peaux de yéti Griffe Féroce à Pratt McGrubben au bastion de Feathermoon, en Feralas.",
    [7734] = "Fournir 10 Peaux de yéti Griffe Féroce à Jangdor Swiftstrider au Camp Mojache, en Feralas.",
    [7735] = "Apporter la Peau de yéti en parfait état à Pratt McGrubben au bastion de Feathermoon, en Feralas.",
    [7738] = "Apporter la Peau de yéti parfaite à Jangdor Swiftstrider au Camp Mojache, en Feralas.",
    [7761] = "Cet orc est stupide. Il semble que vous deviez trouver un moyen d’obtenir la Marque de Drakkisath pour accéder à l’Orbe de commandement. D’après la lettre, la Marque est gardée par le général Drakkisath. Vous devriez peut-être enquêter.",
    [7781] = "Apporter la Tête de Nefarian au généralissime Bolvar Fordragon à Stormwind.",
    [7782] = "Allez à la vallée des Héros de Hurlevent et parlez au grand maréchal Afrasiabi.",
    [7783] = "Apportez la Tête de Nefarian à Thrall à Orgrimmar.",
    [7784] = "Parlez au Haut seigneur Saurfang à Orgrimmar. Il vous attend dans la vallée de la Force.",
    [7785] = "Examiner le Calice de la renaissance et le rapporter au généralissime Demitrian.",
    [7786] = "Pour libérer Thunderaan le Cherchevent de sa prison, vous devez présenter au généralissime Demetrian les moitiés droite et gauche des Liens du Cherchevent, 10 barres d'élémentium, et l'Essence du Seigneur du feu.",
    [7787] = "Présenter la Lame du baiser du vent dormante au généralissime Demitrian.",
    [7790] = "Cherchez ce qui est à l’origine du conflit des Éolides le long de la Thondroril.",
    [7810] = "Parler à Short John Mithril dans l’arène de Strangleronce.",
    [7815] = "Katoom le pêcheur, du village des Revantusk des Hinterlands, veut que vous tuiez 15 tortues Gueules d’acier des mers. Retournez le voir lorsque vous aurez terminé.",
    [7816] = "Katoom le pêcheur, du village des Revantusk dans les Hinterlands, veut que vous tuiez Gammerita et que vous récupériez le Meilleur appât de Katoom sur son cadavre. Katoom a mentionné que Gammerita rôdait sur la côte, avec d’autres tortues.",
    [7828] = "Le veneur Markhor du village des Revantusk, dans les Hinterlands, veut que vous tuiez 15 Traqueurs Crins-d'argent et 15 Hurleurs Crins-d'argent. Retournez le voir lorsque vous aurez terminé. D’après Makhor, les loups se cachent dans les régions sauvages des Hinterlands.",
    [7829] = "Le veneur Markhor du village des Revantusk des Hinterlands veut que vous tuiez 20 Chouettards sauvages. Retournez le voir lorsque vous aurez terminé. Markhor a mentionné que les Chouettards sauvages vivaient dans les régions sauvages des Hinterlands.",
    [7830] = "Le veneur Markhor, du village des Revantusk des Hinterlands, veut que vous tuiez un Seigneur du ciel Bec-rasoir et que vous récupériez une Plume de Seigneur du ciel. Revenez le voir lorsque vous aurez terminé votre tâche. D’après Makhor, les Seigneurs du ciel Bec-rasoir sont des créatures rares qui vivent dans les régions sauvages des Hinterlands.",
    [7839] = "Le forgeron Slagtree du village des Revantusk, dans les Hinterlands, vous demande de retrouver les Outils perdus de Slagtree. Retournez le voir lorsque vous les aurez. Il a laissé entendre qu’ils pourraient se trouver dans l’un des temples des Vilebranch, au nord-est des Hinterlands. Vous devriez aussi jeter un coup d’œil au rocher de l’Affût.",
    [7840] = "Lard, du village des Revantusk, dans les Hinterlands, veut que vous retrouviez le Repas de Lard. Retournez le voir lorsque ce sera fait. D’après Lard, il l’aurait laissé dans l’île, au nord. Prenez garde aux trolls Vilebranch !",
    [7841] = "Otho Moji'ko du village des Revantusk dans les Hinterlands veut que vous massacriez 15 Estafettes du Haut-val, 15 Eclaireurs du Haut-val, 15 Tireurs d'élite du Haut-val et 15 Forestiers du Haut-val. Revenez le voir lorsque vous aurez terminé. Vous pouvez trouver les elfes du Haut-val au Gîte de Quel’Danil, au nord-ouest des Hinterlands.",
    [7842] = "Otho Moji'ko, du village des Revantusk dans les Hinterlands, vous demande de lui ramener 10 Longues plumes élégantes prélevées sur les gryphons qui vivent dans les Hinterlands. Retournez le voir lorsque vous les aurez. On trouve des gryphons dans tous les Hinterlands.",
    [7843] = "Otho Moji'ko, du village des Revantusk dans les Hinterlands, vous demande de vous rendre au Nid-de-l’Aigle, à l’ouest des Hinterlands. Vous devez placer le Message final pour les Wildhammer près du puits, au cœur de la ville. Retournez le voir lorsque vous aurez accompli votre tâche. Faites attention aux nains Wildhammer, qui risquent de mal le prendre, et aux autres membres de l’Alliance.",
    [7844] = "Yayo’jin la Mystique, du village des Revantusk des Hinterlands, veut que tuiez 30 Scalpeurs Vilebranch et 15 Devins Vilebranch. Retournez la voir lorsque vous aurez terminé. D’après Yayo’jin, ces trolls se trouvent près des temples de Shaol'watha et d’Agol'watha, au nord-nord-est des Hinterlands.",
    [7845] = "L’Aînée Torntusk du village des Raventusk des Hinterlands vous demande de libérer son compagnon, l’Ancien Torntusk, de Jintha’alor. Vous savez qu’il est prisonnier au sommet de Jintha’alor, la capitale des Vilebranch, qui se trouve au sud des Hinterlands.",
    [7846] = "L’Ancien Torntusk, à Jintha’alor, veut que vous tuiez Hitah’ya la Gardienne afin de récupérer la Clé des menottes qui le retiennent. Lorsque vous aurez cette clé, retournez voir l’Ancien Torntusk.",
    [7847] = "L’Ancien Torntusk, à Jintha’alor, veut que vous retourniez voir l’Aînée Torntusk du village des Revantusk et que vous lui appreniez qu’il est sauvé.",
    [7848] = "Aventurez-vous jusqu'au portail d'entrée du Cœur du Magma dans les profondeurs de Blackrock et récupérez un Fragment du Magma. Lorsque ce sera fait, retournez voir Lothos Riftwalker au mont Blackrock.",
    [7849] = "Le veneur Markhor du village des Revantusk, dans les Hinterlands, veut que vous récupériez les restes de son frère jumeau. Trouvez le Crâne du veneur Malkhor et les Os du veneur Malkhor, et ramenez-les au veneur Markhor. Markhor vous a dit que les restes de son frère avaient été abandonnés aux limons et aux loups des Vilebranch. Il a également mentionné l’existence d’une décharge remplie de limons à Jintha’alor, ainsi que celle d’un enclos à loups. Tous deux se trouvent près du sommet du temple.",
    [7850] = "L’Aînée Torntusk du village des Revantusk, dans les Hinterlands, veut que vous récupériez 10 Calices de sang corrompu à Jintha’alor. Retournez voir l’Aînée Torntusk lorsque vous aurez terminé.",
    [7861] = "Vous avez reçu l’ordre de tuer la vile prêtresse Maléficia et 20 Gardes Ama’zasi Vilebranch. Lorsque vous aurez terminé, allez voir l’Aînée Torntusk au village des Revantusk, dans les Hinterlands. La vile prêtresse Maléficia et la garde Aman’zasi ont leurs quartiers au sommet de Jintha’alor, dans les Hinterlands.",
    [7862] = "Vous avez été chargée de liquider 20 Berserkers Vilebranch, 20 Chasseurs des ombres Vilebranch, 20 Sanguinaires Vilebranch et 20 Mangeurs d’âmes Vilebranch. Lorsque vous aurez terminé, allez parler à l’Aînée Torntusk, du village de Revantusk dans les Hinterlands.",
    [7877] = "Retournez à l’Athenaeum et trouvez le Trésor des Shen’dralar. Prenez votre récompense !",
    [7907] = "Rapporter la suite de Fauves à la foire de Sombrelune quand elle reviendra en ville.",
    [7927] = "Rapporter la suite de Portails à la foire de Sombrelune quand elle reviendra en ville.",
    [7928] = "Rapporter la suite de Seigneurs de guerre à la foire de Sombrelune quand elle reviendra en ville.",
    [7929] = "Rapporter la suite d'Elémentaires à la foire de Sombrelune quand elle reviendra en ville.",
    [8053] = "Ramenez des Manchettes primordiales hakkari à Jin'rokh le Briseur. La tribu Zandalar doit aussi être Amicale envers vous (au minimum). Jin'rokh le Briseur se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8054] = "Ramenez un Châle primordial hakkari à Jin’rokh le Briseur. La tribu Zandalar doit aussi vous Honorer (au minimum). Jin’rokh le Briseur se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8055] = "Ramenez un Tabard primordial hakkari à Jin'rokh le Briseur. La tribu Zandalar doit aussi vous Révérer (au minimum). Jin'rokh le Briseur se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8056] = "Ramenez des Brachiales primordiales hakkari à Maywiki de Zuldazar. La tribu Zandalar doit aussi être Amicale envers vous (au minimum). Maywiki de Zuldazar se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8057] = "Rapportez un Étançon primordial hakkari à Maywiki de Zuldazar. La tribu Zandalar doit aussi être Amicale (au minimum). Maywiki de Zuldazar se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8058] = "Ramenez des Brachiales primordiales hakkari à Jin'rokh le Briseur. La tribu Zandalar doit aussi être Amicale envers vous (au minimum). Jin'rokh le Briseur se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8059] = "Ramenez un Etançon primordial hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi être Amicale (au minimum). Al’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8060] = "Ramenez des Manchettes primordiales hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi être Amicale (au minimum). Al’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8061] = "Ramenez un Etançon primordial hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi être Amicale (au minimum). Al’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8062] = "Ramenez des Manchettes primordiales hakkari à Falthir le Sans-vue. La tribu Zandalar doit aussi être Amicale envers vous (au minimum). Falthir le Sans-vue se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8063] = "Ramenez des Brachiales primordiales hakkari à Falthir le Sans-vue. La tribu Zandalar doit aussi être Amicale envers vous (au minimum). Falthir le Sans-vue se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8064] = "Rapportez une Écharpe primordiale hakkari à Maywiki de Zuldazar. Maywiki de Zuldazar se trouve sur l’île de Yojamba, dans la vallée de Strangleronce. La tribu Zandalar doit aussi vous Honorer (au minimum).",
    [8065] = "Rapportez un Tabard primordial hakkari à Maywiki de Zuldazar. Maywiki de Zuldazar se trouve sur l’île de Yojamba, dans la vallée de Strangleronce. La tribu Zandalar doit aussi vous Révérer (au minimum).",
    [8066] = "Ramenez un Châle primordial hakkari à Falthir le Sans-vue. La tribu Zandalar doit aussi vous Honorer (au minimum). Falthir le Sans-vue se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8067] = "Ramenez une Egide primordiale hakkari à Falthir le Sans-vue. La tribu Zandalar doit aussi vous Révérer (au minimum). Falthir le Sans-vue se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8068] = "Ramenez un Châle primordial hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi vous Honorer (au minimum). Al’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8069] = "Ramenez une Casaque primordiale hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi vous Révérer (au minimum). Al’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8070] = "Ramenez une Echarpe primordiale hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi vous Honorer (au minimum). Al’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8071] = "Ramenez une Egide primordiale hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi vous Révérer (au minimum). Al’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8072] = "Ramenez un Ceinturon primordial hakkari à Falthir le Sans-vue. La tribu Zandalar doit aussi vous Honorer (au minimum). Falthir le Sans-vue se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8073] = "Ramenez une Egide primordiale hakkari à Falthir le Sans-vue. La tribu Zandalar doit aussi vous Révérer (au minimum). Falthir le Sans-vue se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8074] = "Ramenez un Ceinturon primordial hakkari à Maywiki de Zuldazar. La tribu Zandalar doit aussi vous Honorer (au minimum). Maywiki de Zuldazar se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8075] = "Ramenez un Tabard primordial hakkari à Maywiki de Zuldazar. La tribu Zandalar doit aussi vous Révérer (au minimum). Maywiki de Zuldazar se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8076] = "Ramenez une Echarpe primordiale hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi vous Honorer (au minimum). Al’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8077] = "Ramenez une Casaque primordiale hakkari à Al’tabim Qui-voit-tout. La tribu Zandalar doit aussi vous Révérer (au minimum). Al’tabim Qui-voit-tout se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8078] = "Ramenez un Ceinturon primordial hakkari à Jin’rokh le Briseur. La tribu Zandalar doit aussi vous Honorer (au minimum). Jin’rokh le Briseur se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8079] = "Ramenez une Casaque primordiale hakkari à Jin’rokh le Briseur. La tribu Zandalar doit aussi vous Révérer (au minimum). Jin’rokh le Briseur se trouve sur l’île de Yojamba, dans la vallée de Strangleronce.",
    [8105] = "Attaquez la mine, la scierie, la forge et la ferme, puis revenez voir le grand maréchal Oslight au Refuge de l'Ornière.",
    [8114] = "Entrez dans le Bassin Arathi, capturez et contrôlez quatre bases simultanément, puis revenez voir le grand maréchal Oslight au Refuge de l'Ornière.",
    [8115] = "Contrôlez 5 bases du bassin d'Arathi simultanément, puis revenez voir le grand maréchal Oslight au Refuge de l'Ornière.",
    [8120] = "Attaquez la mine, la scierie, la forge et l’écurie du bassin d’Arathi, puis revenez voir le Maître noir Dwire, au Trépas-d’Orgrim.",
    [8121] = "Contrôlez quatre bases du bassin d'Arathi simultanément, puis revenez voir le Maître noir Dwire, au Trépas-d’Orgrim.",
    [8122] = "Contrôlez 5 bases du Bassin Arathi simultanément, puis revenez voir le Maître de la mort Dwire, au Trépas-d’Orgrim.",
    [8151] = "Parlez à Ogtinc en Azshara.",
    [8152] = "Rendez-vous à la chapelle de l’Espoir de Lumière et interrogez quelqu’un au sujet des indices détrempés que vous avez trouvés.",
    [8153] = "Rapporter deux Ramures de coursier parfaites à Ogtinc en Azshara. Ogtinc vit au sommet des collines au nord-est des ruines d’Eldarath.",
    [8166] = "Attaquez la mine, la scierie, la forge et la ferme, puis revenez voir le grand maréchal Oslight au Refuge de l'Ornière.",
    [8167] = "Attaquez la mine, la scierie, la forge et la ferme, puis revenez voir le grand maréchal Oslight au Refuge de l'Ornière.",
    [8168] = "Attaquez la mine, la scierie, la forge et la ferme, puis revenez voir le grand maréchal Oslight au Refuge de l'Ornière.",
    [8169] = "Attaquez la mine, la scierie, la forge et l’écurie du bassin d’Arathi, puis revenez voir le Maître noir Dwire, au Trépas-d’Orgrim.",
    [8170] = "Attaquez la mine, la scierie, la forge et l’écurie du bassin Arathi, puis revenez voir le Maître noir Dwire, au Trépas-d’Orgrim.",
    [8171] = "Attaquez la mine, la scierie, la forge et l’écurie du bassin Arathi, puis revenez voir le Maître noir Dwire, au Trépas-d’Orgrim.",
    [8181] = "Parlez à Yeh'kinya.",
    [8182] = "Parlez à Molthor à Strangleronce.",
    [8183] = "Donnez le Cœur d'Hakkar à Molthor sur l'île de Yojamba.",
    [8201] = "Attachez 5 Têtes de canalistes, puis ramenez la Collection de têtes de Gurubashi à Exzhal sur l’île des Zandalar.",
    [8227] = "Rendre le Mètre ruban de Nat à Nat Pagle, au marécage d’Âprefange.",
    [8231] = "Apporter 6 Ecailles de vandale des flots à Ogtinc en Azshara.  Ogtinc demeure au sommet des falaises au nord-est des ruines d'Eldarath.",
    [8232] = "Apporter la Dent de Morphaz à Ogtinc en Azshara.  Ogtinc demeure au sommet des falaises au nord-est des ruines d'Eldarath.",
    [8233] = "Parler au seigneur Jorach Ravenholdt, au manoir de Ravenholdt.",
    [8234] = "Récupérer le Sac azur scellé auprès du chaman Grumegueule en Azshara.  Puis apportez le sac à l'archimage Xylem, également en Azshara.",
    [8235] = "Apporter 10 Fragments codés à l'archimage Xylem à Azshara.",
    [8236] = "Rendre la Clé d'azur au seigneur Jorach Ravenholdt.",
    [8240] = "Détruisez n'importe lequel des Bijoux hakkari trouvé à Zul'Gurub à l'Autel de Zanza, sur l'Ile de Yojamba. Quand ce sera fait, parlez à Vinchaxa qui se trouve à côté.",
    [8250] = "Trouver Sanath Lim-yo et obtenir d'être mené à l'archimage Xylem.",
    [8251] = "Procurer 10 doses de Poussière lumineuse à l’archimage Xylem.",
    [8252] = "Récupérer 6 Coraux enchantés et les apporter à l’archimage Xylem.",
    [8253] = "Récupérer le Fragment d’arcane sur Morphaz et le rendre à l’archimage Xylem.",
    [8254] = "Chercher Ogtinc en Azshara.",
    [8255] = "Récupérer 4 Glandes de coursier en bonne santé et les apporter à Ogtinc en Azshara. Ogtinc réside au sommet des falaises, au nord-est des ruines d’Eldarath.",
    [8256] = "Récupérer une dose d’Ichor de non-mort pour le compte d’Ogtinc en Azshara. Ogtinc réside au sommet des falaises, au nord-est des ruines d’Eldarath.",
    [8257] = "Tuez Morphaz dans le temple englouti d’Atal'Hakkar, et ramenez son sang à Greta Mosshoof à Gangrebois. L’entrée du temple englouti se trouve dans le marais des Chagrins.",
    [8258] = "Servez-vous du Clairvoyant au centre du sous-sol du Grand ossuaire de la Scholomance. Cela attirera des esprits que vous devrez combattre. Les vaincre fera apparaître le Chevalier de la mort Ravassombre. Tuez-le. Rapportez la Tête de Ravassombre à Sagorne Rôdeur-des-crêtes de la Vallée de la Sagesse, à Orgrimmar.",
    [8275] = "Parler à l'imploratrice céleste Proudhorn au Fort cénarien, en Silithus.",
    [8276] = "Parler à l'imploratrice céleste Proudhorn au Fort cénarien, en Silithus.",
    [8277] = "Beetix Ficklespragg au Fort cénarien en Silithus veut que vous ramassiez 8 Dards de scorpide Cinglepierre et 8 Crocs de Glisseuse du sable. Retournez la voir quand vous aurez terminé.",
    [8278] = "Beetix Ficklespragg, du Fort cénarien en Silithus, veut que vous ramassiez 3 Dards de pinceurs Cinglepierre, 3 Dards d'écorcheur Cinglepierre et 3 Crocs de traqueuse des rochers.",
    [8279] = "Apporter les trois chapitres du Lexique du crépuscule à l'ermite Ortell, en Silithus.",
    [8280] = "L'Imploratrice céleste Proudhorn au Fort cénarien en Silithus veut que vous tuiez 15 Frappeurs térébrants.",
    [8281] = "L'Imploratrice céleste Proudhorn au Fort cénarien en Silithus veut que vous tuiez 20 Ecraseurs térébrants.",
    [8282] = "Récupérez la Sacoche de Noggle dans les montagnes au sud de Silithus et rapportez-la-lui au Fort cénarien.",
    [8283] = "Apporter la Pince de Poigne-de-mort à Vish Kozus, capitaine de la garde.",
    [8284] = "La géologue Larksbane du Fort cénarien en Silithus veut que vous rassembliez 8 Fragments de Tablette du crépuscule.",
    [8285] = "Apporter la tablette réparée à l'ermite Ortell à Silithus.",
    [8286] = "Rendez vous dans les grottes du Temps en Tanaris et trouvez Anachronos, la progéniture de Nozdormu.",
    [8287] = "Remettez la Transcirption décodée de la tablette au commandant Mar'alith.",
    [8288] = "Rapportez la Tête du seigneur des couvées Lanistaire à Baristolth des Sables changeants, au Fort cénarien en Silithus.",
    [8301] = "Récupérez 200 Fragments de carapaces de silithides et retournez voir Baristolth.",
    [8302] = "Récupérez 200 Fragments de carapaces de silithides et retournez voir Baristolth.",
    [8303] = "Chercher Anachronos dans les Grottes du temps à Tanaris.",
    [8304] = "Le commandant Mar’alith, du Fort cénarien en Silithus, veut que vous interrogiez les habitants du Campement de Bronzebeard, qui se trouve au sud du Fort cénarien. Lorsque vous aurez réuni les informations demandées, retournez voir le commandant Mar’alith.",
    [8305] = "Trouvez la Larme cristalline, en Silithus, et contemplez ses profondeurs.",
    [8306] = "Le Commandant Mar'alith au Fort cénarien en Silithus veut que vous retrouviez sa bien-aimée, Natalia. Selon les informations que vous avez réunies, la Ruche'Regal au sud serait l'endroit où vous pourriez trouver Dame Natalia Mar'alith. N'oubliez pas de rendre visite aux nains au camp de Barbe-de-bronze avant de vous aventurer dans la ruche. Ils ont peut-être d'autres tâches à vous confier et des conseils pour vous. Et <name>, souvenez-vous des mots du commandant : « Faites votre devoir… »",
    [8307] = "Cherchez des informations sur la façon de cuisiner la Chair de ver de sable, au camp du Marteau du crépuscule à l'ouest du Fort cénarien.",
    [8308] = "Apporter la Lettre de Brann Bronzebeard au Campement de Bronzebeard dans le sud de Silithus.",
    [8309] = "Rutgar Glyphshaper, du campement de Bronzebeard en Silithus, veut que vous entriez dans Ruche’Ashi, Ruche’Zora et Ruche’Regal et que vous récupériez des reproductions des Cristaux ornés de glyphes dans chaque ruche. Utilisez la Trousse de transcription du géologue pour obtenir une copie correcte de ces glyphes antiques. Lorsque vous aurez terminé, retournez voir Rutgar Glyphshaper.",
    [8310] = "Obtenez un Cerveau de silithide intact provenant de la Ruche’Regal. N’importe quel silithide de cette ruche fera l’affaire.",
    [8313] = "Apportez la Page de recette déchirée à Calandrath, à l’auberge du Fort cénarien.",
    [8314] = "Rutgar Glyphshaper, du campement de Bronzebeard, veut que vous remettiez le Prisme cristallin orné de glyphes à la géologue Larksbane, au Fort cénarien en Silithus.",
    [8315] = "La géologue Larksbane, au Fort cénarien en Silithus, veut que vous récupériez le Mécanisme de déverrouillage du cristal sur le Maître des clés. Elle vous a demandé de vous rendre près des Restes de Grakkarond, au sud du Fort cénarien, et d’y dessiner les glyphes d'appel dans le sable. Si le Maître des clés apparaît, tuez-le et récupérez le Mécanisme de déverrouillage du cristal. Ensuite, si vous avez réussi, retournez voir la géologue Larksbane. Elle vous a conseillé d’emmener une armée, <nom>.",
    [8317] = "Calandrath, du Fort cénarien, a besoin d’une fournée de 10 Boulettes du desert fumées.",
    [8318] = "Apporter 10 Textes du crépuscule cryptés à Bor Wildmane au Fort cénarien.",
    [8320] = "Tuer 10 Géoseigneurs du crépuscule, puis retourner voir Huum Wildmane au Fort cénarien.",
    [8321] = "Remettre la Chevalière de Vyral à Huum Wildmane au Fort cénarien.",
    [8323] = "L'ermite Ortell veut que vous lui apportiez 10 Textes du crépuscule cryptés.",
    [8331] = "Parlez à Aurel Feuilledor au Fort cénarien.",
    [8332] = "Apportez 1 Grand éclat brillant et 3 Blasons abyssaux à Aurel Goldleaf, au Fort cénarien.",
    [8341] = "Apportez 5 Grands éclats brillants et 3 Chevalières abyssales à Aurel Feuilledor, au Fort cénarien.",
    [8343] = "Parlez à Aurel Feuilledor au Fort cénarien.",
    [8348] = "Apportez la Chevalière abyssale à Bor Crin-sauvage, au Fort cénarien.",
