    [8917] = "Procurez-vous 15 Echantillons de venin de Silithus et 20 pièces d’or, et apportez-les avec une paire de Bracelets Sombreruse à Mokvar, à Orgrimmar.",
    [8918] = "Procurez-vous 15 Echantillons de venin de Silithus et 20 pièces d’or, et apportez-les avec une paire de Bracelets des éléments à Mokvar, à Orgrimmar.",
    [8919] = "Procurez-vous 15 Echantillons de venin de Silithus et 20 pièces d’or, et apportez-les avec une paire de Brassards de Brume-funeste à Mokvar, à Orgrimmar.",
    [8920] = "Procurez-vous 15 Echantillons de venin de Silithus et 20 pièces d’or, et apportez-les avec une paire de Brassards de vaillance à Mokvar, à Orgrimmar.",
    [8921] = "Retournez voir Mux Manascrambler à Gadgetzan avec 1 Convertisseur d’arcanite délicat, 4 Essences éternelles supérieures, 10 Huiles de pierre-écaille, 25 Cendres volcaniques et 40 pièces d’or.",
    [8922] = "Remettre le Récipient de sang scellé à Mux Manascrambler, à Gadgetzan en Tanaris.",
    [8923] = "Remettez le Récipient de venin scellé à Mux Manascrambler, à Gadgetzan.",
    [8924] = "Utilisez l’Alambic ectoplasmique à proximité de morts-vivants désincarnés pour recueillir 12 Ectoplasmes brûlés en Silithus, 12 Ectoplasmes glacés au Berceau-de-l’hiver et 12 Ectoplasmes stables dans les Maleterres de l’est. Remettez à Mux Manascrambler à Gadgetzan. Il veut aussi récupérer l'Alambic ectoplasmique.",
    [8925] = "Trouvez le Seigneur-magma Bokk dans les Steppes ardentes, prenez son Coeur de magma et rapportez-le à Mux Manascrambler, à Gadgetzan.",
    [8926] = "Apportez une Ceinture du Coeur-sauvage et une paire de Gants du Cœur-sauvage à Deliana à Ironforge.",
    [8927] = "Apportez une Ceinture du Coeur-sauvage et une paire de Gants du Cœur-sauvage à Mokvar à Orgrimmar.",
    [8928] = "Trouvez un diablotin qui vivrait dans une caverne à l'entrée de la gorge du Sombre murmure, au sud du Berceau-de-l'hiver. Achetez-lui un Bâtonnet élémentaire de corruption, puis retournez voir Mux Manascrambler à Gadgetzan.",
    [8929] = "Utilisez le Révélateur de fantômes extradimensionnel à l’entrée de Stratholme et parlez au fantôme d’Anthion Harmon.",
    [8930] = "Utilisez le Révélateur de fantômes extradimensionnel à l'entrée de Stratholme, et parlez au fantôme d'Anthion Harmon.",
    [8931] = "Apportez une Ceinture de bestiaire et une paire de Gants de bestiaire à Deliana à Forgefer.",
    [8932] = "Apportez une Ceinture de magistère et une paire de Gants de magistère à Deliana à Forgefer.",
    [8933] = "Apportez une Ceinture de Sancteforge et une paire de Gantelets de Sancteforge à Deliana à Forgefer.",
    [8934] = "Apportez une Ceinture de dévot et une paire de Gants de dévot à Deliana à Forgefer.",
    [8935] = "Apportez une Ceinture Sombreruse et une paire de Gants Sombreruse à Deliana à Forgefer.",
