    [8942] = "Apportez une Corde des éléments et une paire de Gantelets des éléments à Mokvar à Orgrimmar.",
    [8943] = "Apportez une Ceinture de Brume-funeste et des Gants de Brume-funeste à Mokvar à Orgrimmar.",
    [8944] = "Apportez une Ceinture de vaillance et une paire de Gantelets de vaillance à Mokvar à Orgrimmar.",
    [8945] = "Entrez à Stratholme et sauvez Ysida Harmon du baron Vaillefendre.",
    [8946] = "Remettre le Médaillon d’Ysida à Anthion Harmon, dans les Maleterres de l’est.",
    [8947] = "Remettre 3 Barres de sombre fer, 20 Cuirs enchantés, 3 Etoffes lunaires et 4 Peaux robustes traitées à Anthion Harmon dans les Maleterres de l’est.",
    [8948] = "Apportez la Bannière de défi incomplète à Farlin Sculpteflore, dans la bibliothèque de Hache-Tripes.",
    [8949] = "Collecter 25 Perles de guerre ogres à l’intérieur de Hache-Tripes ou du Pic Rochenoire, puis revenir voir Falrin Sculpteflore, à l'intérieur de l'Athenaeum à Hache-Tripes.",
    [8950] = "Apportez les choses suivantes à Falrin Sculpteflore dans Hache-Tripes : 1 Essence de spectre railleur, 4 Runes ténébreuses et 8 Grands éclats brillants.",
    [8951] = "Retournez voir Deliana à Ironforge avec des bottes du Cœur-sauvage, un Kilt du Cœur-sauvage et des Spallières du Cœur-sauvage.",
    [8952] = "Retournez voir Deliana à Ironforge avec des Bottes de bestiaire, un Pantalon de bestiaire et un Mantelet de bestiaire.",
    [8953] = "Retournez voir Deliana à Ironforge avec des Bottes de magistère, des Jambières de magistère et un Mantelet de magistère.",
    [8954] = "Retournez voir Deliana à Ironforge avec des Bottes de Sancteforge, des Jambières de Sancteforge et des Spallières de Sancteforge.",
    [8955] = "Retournez voir Deliana à Ironforge avec des Sandales de dévot, un Pantalon de dévot et un Mantelet de dévot.",
    [8956] = "Retournez voir Deliana à Ironforge avec des Bottes Sombreruse, un Pantalon Sombreruse et des Spallières Sombreruse.",
    [8957] = "Retournez voir Mokvar à Orgrimmar avec des Bottes des éléments, un Kilt des éléments et des Espauliers des éléments.",
    [8958] = "Retournez voir Deliana à Ironforge avec des Sandales de Brume-funeste, des Jambières de Brume-funeste et un Mantelet de Brume-funeste.",
    [8959] = "Retournez voir Deliana à Ironforge avec des Bottes de vaillance, des Jambières de vaillance et des Spallières de vaillance.",
    [8960] = "Rendez-vous au mont Rochenoire, près du pic Rochenoire, et utilisez le Révélateur de fantômes extradimensionnel pour trouver Bodley.",
    [8961] = "Récupérez l’Incendicite d’Incendius, la Braise du prophète ardent sur le pyrogarde Prophète ardent et les Cendres de Cendres, ainsi qu'un Brasero béni, puis retournez voir Bodley au mont Rochenoire.",
    [8962] = "Procurez-vous des Restes druidiques et rapportez-les à Bodley, à l’intérieur du mont Rochenoire.",
    [8963] = "Procurez-vous une Relique de Brise-Stellaire et rapportez-la à Bodley, à l’intérieur du Mont Rochenoire.",
    [8964] = "Procurez-vous une Épée brillante de fanatisme, puis rapportez-la à Bodley, à l’intérieur du mont Rochenoire.",
    [8965] = "Prélevez des Cendres d’âme de banni, puis retournez voir Bodley à l’intérieur du mont Rochenoire.",
    [8966] = "Utilisez le Brasero de signal pour invoquer l’esprit de Mor Sabot-gris, puis tuez-le. Ensuite, retournez voir Bodley à l'intérieur du mont Rochenoire avec le Morceau gauche de l'amulette du seigneur Valthalak et le Brasero de signal.",
    [8967] = "Utilisez le Brasero de signal pour invoquer l’esprit d’Isalien, puis tuez-le. Retournez voir Bodley, à l'intérieur du mont Rochenoire, avec le Morceau gauche de l’amulette du seigneur Valthalak et le Brasero de signal.",
    [8968] = "Utilisez le Brasero de signal pour invoquer Jarien et Sothos et les tuer. Retournez voir Bodley, à l'intérieur du mont Rochenoire, avec le Morceau gauche de l’amulette du seigneur Valthalak et le Brasero de signal.",
    [8969] = "Utilisez le Brasero de signal pour invoquer l’esprit de Kormok, puis tuez-le. Retournez voir Bodley, à l'intérieur du mont Rochenoire, avec le Morceau gauche de l'amulette du seigneur Valthalak et le Brasero de signal.",
    [8970] = "Récupérez 20 Varechs de sang sur les nagas Strashaz, puis retournez voir Bodley au mont Rochenoire.",
    [8977] = "Apportez le Révélateur de fantômes extradimensionnel à Deliana à Ironforge.",
    [8978] = "Retournez voir Mokvar à Orgrimmar avec le Révélateur de fantômes extradimensionnel.",
    [8985] = "Procurez-vous une Relique de Brise-Stellaire et rapportez-la à Bodley, à l’intérieur du Mont Rochenoire.",
    [8986] = "Procurez-vous des Restes druidiques et rapportez-les à Bodley, à l’intérieur du mont Rochenoire.",
    [8987] = "Procurez-vous une Épée brillante de fanatisme, puis rapportez-la à Bodley, à l’intérieur du mont Rochenoire.",
    [8988] = "Prélevez des Cendres d’âme de banni, puis retournez voir Bodley à l’intérieur du mont Rochenoire.",
    [8989] = "Utilisez le Brasero de signal pour invoquer l’esprit de Mor Sabot-gris, puis tuez-le. Ensuite, retournez voir Bodley, à l'intérieur du mont Rochenoire, avec l’Amulette du seigneur Valthalak reconstituée et le Brasero de signal.",
    [8990] = "Utilisez le Brasero de signal pour invoquer l’esprit d’Isalien, puis tuez-le. Retournez voir Bodley, à l'intérieur du mont Rochenoire, avec l’Amulette du seigneur Valthalak reconstituée et le Brasero de signal.",
    [8991] = "Utilisez le Brasero de signal pour invoquer Jarien et Sothos, puis tuez-les. Retournez voir Bodley, à l'intérieur du mont Blackrock, avec l’Amulette du seigneur Valthalak reconstituée et le Brasero de signal.",
    [8992] = "Utilisez le Brasero de signal pour invoquer l’esprit de Kormok, puis tuez-le. Retournez voir Bodley, à l'intérieur du mont Rochenoire, avec l’Amulette du seigneur Valthalak reconstituée et le Brasero de signal.",
    [8994] = "Collectez 40 Brassards rochenoire et un Flacon de pouvoir suprême. Ensuite, retournez voir Bodley au mont Rochenoire.",
    [8995] = "Utilisez le Brasero de signal pour invoquer le seigneur Valthalak. Tuez-le, puis utilisez l’Amulette du seigneur Valthalak sur le corps. Ensuite, rendez l’amulette à l’Esprit du seigneur Valthalak.",
    [8996] = "Retournez voir Bodley à l'intérieur du mont Rochenoire et donnez-lui le Brasero de signal.",
    [8997] = "Parlez à Deliana au Haut Siège d'Ironforge.",
    [8998] = "Parlez à Mokvar au Fort Grommash, dans la Vallée de la Sagesse d'Orgrimmar.",
    [8999] = "Donnez votre Coiffe du Coeur-sauvage et votre Gilet du Coeur-sauvage à Deliana.",
    [9000] = "Donnez votre Coiffe de bestiaire et votre Tunique de bestiaire à Deliana.",
    [9001] = "Donnez votre Collerette de magistère et votre Robe de magistère à Deliana.",
    [9002] = "Donnez votre Casque de Sancteforge et votre Cuirasse de Sancteforge à Deliana.",
    [9003] = "Donnez votre Collerette de dévot et votre Robe de dévot à Deliana.",
    [9004] = "Donnez votre Cagoule Sombreruse et votre Tunique Sombreruse à Deliana.",
    [9005] = "Donnez votre Masque de Brume-funeste et votre Robe de Brume-funeste à Deliana.",
    [9006] = "Donnez votre Casque de vaillance et votre Cuirasse de vaillance à Deliana.",
    [9007] = "Donnez votre Coiffe du Coeur-sauvage et votre Gilet du Coeur-sauvage à Mokvar.",
    [9008] = "Donnez votre Coiffe de bestiaire et votre Tunique de bestiaire à Mokvar.",
    [9009] = "Donnez votre Collerette de dévot et votre Robe de dévot à Mokvar.",
    [9010] = "Donnez votre Cagoule Sombreruse et votre Tunique Sombreruse à Mokvar.",
    [9011] = "Donnez votre Coiffe des éléments et votre Haubergeon des éléments à Mokvar.",
    [9012] = "Donnez votre Masque de Brume-funeste et votre Robe de Brume-funeste à Mokvar.",
    [9013] = "Donnez votre Casque de vaillance et votre Cuirasse de vaillance à Mokvar.",
    [9014] = "Donnez votre Collerette de magistère et votre Robe de magistère à Mokvar.",
    [9015] = "Rendez-vous dans le Cercle de la loi, dans les profondeurs de Rochenoire, et placez la Bannière de provocation en son centre lorsque vous serez <condamné/condamnée> par le Juge supérieur Mornepierre. Tuez Theldren et ses gladiateurs, puis retournez voir Anthion Harmon dans les Maleterres de l’Est avec le premier morceau de l’amulette du seigneur Valthalak.",
    [9016] = "Retournez voir Mokvar à Orgrimmar avec des bottes du Cœur-sauvage, un Kilt du Cœur-sauvage et des Spallières du Cœur-sauvage.",
    [9017] = "Retournez voir Mokvar à Orgrimmar avec des Bottes de bestiaire, un Pantalon de bestiaire et un Mantelet de bestiaire.",
    [9018] = "Retournez voir Mokvar à Orgrimmar avec des Bottes de magistère, des Jambières de magistère et un Mantelet de magistère.",
    [9019] = "Retournez voir Mokvar à Orgrimmar avec des Sandales de dévot, un Pantalon de dévot et un Mantelet de dévot.",
    [9020] = "Retournez voir Mokvar à Orgrimmar avec des Bottes Sombreruse, un Pantalon Sombreruse et des Spallières Sombreruse.",
    [9021] = "Retournez voir Mokvar à Orgrimmar avec des Sandales de Brume-funeste, des Jambières de Brume-funeste et un Mantelet de Brume-funeste.",
    [9022] = "Retournez voir Mokvar à Orgrimmar avec des Bottes de vaillance, des Jambières de vaillance et des Spallières de vaillance.",
    [9023] = "Dirk Thunderwood, du Fort cénarien en Silithus, veut que vous lui rameniez la Glande à venin de Venoxis et la Glande à venin de Kurinaxx.",
    [9032] = "Rendez-vous au mont Rochenoire, près du pic Rochenoire, et utilisez le Révélateur de fantômes extradimensionnel pour trouver Bodley.",
    [9033] = "Le commandant Eligor Portelaube, de la chapelle de l’Espoir de Lumière dans les Maleterres de l'Est, veut que vous tuiez 5 Monstruosités vivantes, 5 Gargouilles peau de pierre, 8 Capitaines des chevaliers de la mort et 3 Traque-venin.",
    [9034] = "Korfax, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera une cuirasse de cuirassier si vous lui apportez les choses suivantes : 1 Cuirasse désacralisée, 25 Débris d’armure en plaques, 4 Barres d’arcanite et 2 Cristaux de nexus.",
    [9036] = "Korfax, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera des cuissards de cuirassier si vous lui apportez les choses suivantes : 1 paire de Cuissars désacralisés, 20 Débris d’armure en plaques, 4 Barres d’arcanite et 3 Peaux robustes traitées.",
    [9037] = "Korfax, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera un casque de cuirassier si vous lui apportez les choses suivantes : 1 Heaume désacralisé, 15 Débris d’armure en plaques, 5 Barres d’arcanite et 1 Cristal de nexus.",
    [9038] = "Korfax, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera des espauliers de cuirassier si vous lui apportez les choses suivantes : 1 paire d'Espauliers désacralisés, 12 Débris d’armure en plaques, 2 Barres d’arcanite et 3 Peaux robustes traitées.",
    [9039] = "Korfax, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera des solerets de cuirassier si vous lui apportez les choses suivantes : 1 paire de Solerets désacralisés, 12 Débris d’armure en plaques, 2 Barres d’arcanite et 3 Peaux robustes traitées.",
    [9040] = "Korfax, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera des gantelets de cuirassier si vous lui apportez les choses suivantes : 1 paire de Gantelets désacralisés, 8 Débris d’armure en plaques, 1 Barre d’arcanite et 5 Peaux robustes traitées.",
    [9041] = "Korfax, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera une sangle de cuirassier si vous lui apportez les choses suivantes : 1 Sangle désacralisée, 8 Débris d’armure en plaques, 1 Barre d’arcanite et 5 Peaux robustes traitées.",
    [9042] = "Korfax, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera des brassards de cuirassier si vous lui apportez les choses suivantes : 1 paire de Brassards désacralisés, 6 Débris d’armure en plaques, 1 Barre d’arcanite et 1 Cristal de nexus.",
    [9043] = "Le commandant Eligor Portelaube de la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera une Tunique de rédemption si vous lui rapportez 1 Tunique désacralisée, 25 Débris d'armure en plaques, 4 Barres d’arcanite et 3 Peaux robustes traitées.",
    [9044] = "Le commandant Eligor Portelaube de la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera des Garde-jambes de rédemption si vous lui rapportez 1 paire de Garde-jambes désacralisés, 20 Débris d'armure en plaques, 4 Barres d’arcanite et 2 Cristaux de nexus.",
    [9045] = "Le commandant Eligor Portelaube de la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera un chapel de rédemption si vous lui rapportez 1 Couvre-chef désacralisé, 15 Débris d'armure en plaques, 5 Barres d’arcanite et 2 Peaux robustes traitées.",
    [9046] = "Le commandant Eligor Portelaube de la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera des Spallières de rédemption si vous lui rapportez 1 paire de Spallières désacralisées, 12 Débris d'armure en plaques, 2 Barres d’arcanite et 2 Cristaux de nexus.",
    [9047] = "Le commandant Eligor Portelaube de la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera des Bottes de rédemption si vous lui rapportez 1 paire de Bottes désacralisées, 12 Débris d'armure en plaques, 2 Barres d’arcanite et 3 Peaux robustes traitées.",
    [9048] = "Le commandant Eligor Portelaube de la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera des garde-mains de rédemption si vous lui rapportez 1 paire de Garde-mains désacralisés, 8 Débris d'armure en plaques, 1 Barre d’arcanite et 5 Peaux robustes traitées.",
    [9049] = "Le commandant Eligor Portelaube de la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera un Ceinturon de rédemption si vous lui rapportez 1 Ceinturon désacralisé, 8 Débris d'armure en plaques, 1 Barre d’arcanite et 3 Cristaux de nexus.",
    [9050] = "Le commandant Eligor Portelaube de la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera des Garde-poignets de rédemption si vous lui rapportez 1 paire de Garde-poignets désacralisés, 6 Débris d'armure en plaques, 1 Barre d’arcanite et 2 Peaux robustes traitées.",
    [9051] = "Piquez un Diablosaure avec l'Aiguillon de diablosaure. Retournez voir Torwa Pathfinder au Cratère d'Un'goro lorsque vous aurez accompli cette tâche.",
    [9052] = "Récupérez 8 Chapeaux de sang et 8 Dards de Gorishi, puis retournez voir Torwa Pathfinder au cratère d'Un'goro.",
    [9053] = "Récupérez une Liane putride sur le Gardien au fond du Temple englouti et revenez voir Torwa Pathfinder.",
    [9054] = "Le veneur Leopold, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera une tunique de traqueur des cryptes si vous lui apportez les choses suivantes : 1 Tunique désacralisée, 25 Débris d’armure en mailles, 4 Barres d’arcanite, et 3 Peaux robustes traitées.",
    [9055] = "Le veneur Leopold, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera des garde-jambes de traqueur des cryptes si vous lui apportez les choses suivantes : 1 paire de Garde-jambes désacralisés, 20 Débris d’armure en mailles, 3 Barres d’arcanite, et 5 Peaux robustes traitées.",
    [9056] = "Le veneur Leopold, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera un Chapel de traqueur des cryptes si vous lui apportez les choses suivantes : 1 Couvre-chef désacralisé, 15 Débris d’armure en mailles, 4 Barres d’arcanite et 2 Cristaux de nexus.",
