    [9059] = "Le veneur Leopold, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera des garde-mains de traqueur des cryptes si vous lui apportez les choses suivantes : 1 paire de Garde-mains désacralisés, 8 Débris d’armure en mailles, 1 Barre d’arcanite et 5 Peaux robustes traitées.",
    [9060] = "Le veneur Leopold, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera un ceinturon de traqueur des cryptes si vous lui apportez les choses suivantes : 1 Ceinturon désacralisé, 8 Débris d’armure en mailles, 1 Barre d’arcanite et 3 Cristaux de nexus.",
    [9061] = "Le veneur Leopold, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera des Garde-poignets de traqueur des cryptes si vous lui apportez les choses suivantes : 1 paire de Protège-poignets désacralisés, 6 Débris d’armure en mailles, 1 Barre d’arcanite et 2 Peaux robustes traitées.",
    [9063] = "Parler à Torwa Pathfinder au cratère d'Un'goro.",
    [9071] = "Rimblat Brise-terre à la chapelle de l'Espoir de Lumière dans les Maleterres de l'Est vous fabriquera des spallières de Brise-terre si vous lui apportez les objets suivants : 1 paire de Spallières désacralisées, 12 Débris d'armure en mailles, 2 Barres d'arcanite et 2 Etoffes lunaires.",
    [9077] = "Rohan l’assassin, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera une cuirasse de la faucheuse d’os si vous lui apportez les éléments suivants : 1 Cuirasse désacralisée, 25 Débris d'armure en cuir, 2 Barres d'arcanite et 6 Peaux robustes traitées.",
    [9078] = "Rohan l’assassin, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera des cuissards de la faucheuse d’os si vous lui apportez les éléments suivants : 1 paire de Cuissards désacralisés, 20 Débris d'armure en cuir, 1 Barre d’arcanite, 8 Peaux robustes traitées et 100 pièces d’or.",
    [9079] = "Rohan l’assassin, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera un casque de la faucheuse d’os si vous lui apportez les éléments suivants : 1 Heaume désacralisé, 15 Débris d'armure en cuir, 8 Peaux robustes traitées, 1 Cristal de nexus et 75 pièces d'or.",
