    [9081] = "Rohan l’assassin, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera des solerets de la faucheuse d’os si vous lui apportez les éléments suivants : 1 paire de Solerets désacralisés, 12 Débris d'armure en cuir, 3 Peaux robustes traitées, 2 Cristaux de nexus et 25 pièces d’or.",
    [9082] = "Rohan l’assassin, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera des gantelets de la faucheuse d’os si vous lui apportez les éléments suivants : 1 paire de Gantelets désacralisés, 8 Débris d'armure en cuir, 1 Barre d'arcanite et 5 Peaux robustes traitées.",
    [9083] = "Rohan l’assassin, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera une sangle de la faucheuse d’os si vous lui apportez les éléments suivants : 1 Sangle désacralisée, 8 Débris d'armure en cuir, 5 Peaux robustes traitées, 1 Cristal de nexus et 15 pièces d’or.",
    [9084] = "Rohan l’assassin, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera des brassards de la faucheuse d’os si vous lui apportez les éléments suivants : 1 paire de Brassards désacralisés, 6 Débris d'armure en cuir, 1 Barre d'arcanite, 2 Peaux robustes traitées et 10 pièces d'or.",
    [9085] = "Rendez-vous sur un cercle d'invocation et tuez une Ombre funeste, puis retournez auprès du commandant Thomas Helleran, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est.",
    [9086] = "Rayne, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous confectionnera une tunique de marcherêve si vous lui apportez les choses suivantes : 1 Tunique désacralisée, 25 Débris d’armure en cuir, 6 Peaux robustes traitées et 2 Cristaux de nexus.",
