    [9422] = "Trouver de la Silithyste et la livrer à un Extracteur de silithyste, puis parler au général Kirika au campement de la Horde près de Ruche’Regal.",
    [9664] = "Capturez la Tour de la garde de la couronne, la Tour du Mur d’est, la Tour du Col du nord et la Tour de Pestebois dans les Maleterres de l’est. Revenez ensuite voir l’émissaire Whitebeard à la Chapelle de l’Espoir de Lumière.",
    [9665] = "Capturez la Tour de la garde de la couronne, la Tour du Mur d’est, la Tour du Col du nord et la Tour de Pestebois dans les Maleterres de l’est. Revenez ensuite voir l’émissaire Gormok à la Chapelle de l’Espoir de Lumière.",
    [65593] = "Apportez les Cœurs d’Avelina Lilly et d’Isaac Pearson à Carendin Halgar dans le Temple des Damnés.",
    [65597] = "Utilisez les Cœurs des amoureux pour invoquer et soumettre un incube, puis rapportez les Cœurs des amoureux à Carendin Halgar, dans le Quartier de la magie de Fossoyeuse.",
    [65601] = "Parlez à Magar, à Orgrimmar.",
    [65602] = "Récupérez la Figurine en bois et rapportez-la à Gakin le Tisse-noir, au Quartier des mages de Hurlevent.",
    [65603] = "Utilisez la Figurine en bois pour invoquer et asservir un incube, puis rapportez l’objet à Gakin le Tisse-noir à l’Agneau assassiné.",
    [65604] = "Utilisez l’Écharpe flétrie pour invoquer et asservir un Incube, puis rapportez-la à Gan’rul Bloodeye, à Orgrimmar.",
    [65610] = "Explorez le Lac Tombeciel en Ashenvale et rendez compte de vos découvertes à Gan’rul Bloodeye, à Orgrimmar.",
    [76156] = "Faufilez-vous dans la mine de la KapitalRisk au sud-est de Thunder Bluff et récupérez 5 charges excavatrices d’hydroglycérine dans les chariots de fournitures, puis retournez voir Boarton Ombre-Totem à Thunder Bluff.",
    [76160] = "Ramassez 8 pommes de Furie des vents au nord de Thunder Bluff, utilisez-les avec le mortier et le pilon, puis rapportez le résultat à Boarton Ombre-Totem.",
    [76240] = "Acheter ou attrapez un goujon brillant cru, puis utilisez l’ensemble de couteaux pour lever ses filets devant Boarton Ombre-Totem à Thunder Bluff.",
    [78088] = "Apportez l’orbe d’Althalaxx à Delgren le Purificateur au poste de Maestra en Orneval.",
    [78089] = "Apportez l’orbe d’Althalaxx à Katherine la Pure, à Hurlevent.",
    [78090] = "Trouvez le sanctuaire des démonistes dans Hurlevent et demandez un avis sur l’orbe.",
    [78091] = "Récupérez 14 sels d’invocateur sur les invocateurs rochenoires des Carmines, puis retournez voir Ursula Deline à Hurlevent.",
    [78092] = "Récupérez 12 particules de Mannoroth sur les démons d’Orneval. Apportez-les, avec l’orbe d’Althalaxx, jusqu’à la lance de Mannoroth, au canyon de la Malechute.",
    [78093] = "Rapportez les éclats de l’orbe à Delgren.",
    [78261] = "Trouvez la Corne de Xelthos dans le donjon d’Ombrecroc. Puis rapportez-la au point de livraison de C, près du village de Bois-du-Bûcher. Vous devez accomplir cette tâche sans l’aide de personne.",
    [78676] = "Trouvez l’Œil de Bhossca dans le monastère Écarlate. Puis rapportez-la au point de livraison de C, près du village de Bois-du-Bûcher. Vous devez accomplir cette tâche sans l’aide de personne.",
    [78823] = "Apportez le dessin primitif à Hemet Nesingwary, dans la vallée de Strangleronce.",
