    [93160] = "Collectez 8 glands de Trombenoire dans la forêt de Trombenoire.",
    [93161] = "Trouvez quelqu’un qui serait intéressé par la garde antique que vous avez trouvée dans les ruines de Ban’aethal.",
    [93165] = "Récupérez 5 oreilles de sectateurs al’aketh sur les sectateurs al’aketh dans la forêt de Trombenoire, au sanctuaire d’Akir ou dans les plaines Aérelles.",
    [93172] = "Détruisez 10 creux du vent dans la forêt de Trombenoire.",
    [93176] = "Utilisez les objets du kit d’entomologiste novice pour trouver et attraper une tarentule arborescente, un spécimen de charançon des foins et un pique-chair.",
    [93188] = "Maintenez votre réputation auprès des Magram et retournez voir Orgul près de l’entrée nord de la vallée des Ossements.",
    [93196] = "Maintenez votre réputation auprès des Magram et exécutez un rituel de nécromancie pour ressusciter le khan Jehn. Vous trouverez le site rituel dans une tente du lac situé au centre du village Magram.",
    [93197] = "Remettez les paquets de lettres de Sebelia du camp du sommet du mont Hyjal à l’aubergiste Vizzie à Long-Guet.",
    [93224] = "Récupérez 5 totems centaures sculptés en tuant des Centaures de n’importe quel clan un peu partout en Désolace, puis rapportez-les au capitaine Pentigast à la combe de Nijel.",
    [93225] = "Récupérez 5 totems centaures sculptés en tuant des Centaures de n’importe quel clan un peu partout en Désolace, puis rapportez-les à Gurda Crin-Sauvage au poste de Rôdeur-fantôme.",
    [93226] = "Apportez le sac totémique à l’intendant du village des Magram en Désolace, afin d’augmenter considérablement votre réputation auprès de ce clan. Vous devez avoir un niveau de réputation Neutre ou supérieur auprès des Centaures du clan Magram.",
    [93227] = "Apportez le sac totémique à l’intendant du village des Gelkis en Désolace, afin d’augmenter considérablement votre réputation auprès de ce clan. Vous devez avoir un niveau de réputation Neutre ou supérieur auprès des Centaures du clan Gelkis.",
    [93269] = "Apportez le courrier de Long-Guet à l’aubergiste Sebelia au sommet du mont Hyjal.",
    [93317] = "Récupérez 6 morceaux de viande de clampant chantevent.",
    [93318] = "Tuez Vulgara l’Insatiable dans les hautes-terres de Shen’dar et rapportez sa tête à Danarii Soufflevoile.",
    [93319] = "Collectez 10 pierres de vent chapardées sur des bandits des hautes-terres, dans les hautes-terres de Shen’dar.",
    [93320] = "Allez voir Yorana Roseauvent à la tour de guet orientale dans les plaines Aérelles.",
    [93341] = "Inspectez les jardins Lugubres près de Shen’dralas, puis retournez voir Mithéra au temple des environs.",
    [93362] = "Abattez des plantes dans les jardins Lugubres, puis retournez voir Mithéra, à Shen’dralas.",
    [93383] = "Patientez pour ouvrir le kit de survie personnel en toute sécurité.",
    [93394] = "Trouvez le magistère Kirandis à l’intérieur du temple de Shen’dralas.",
    [93404] = "Rendez-vous à Maraudon, récupérez une fiole d’eau de Chanteterre et apportez-la à Astrebois, aux jardins Lugubres, en Désolace.",
    [93406] = "Trouvez 4 lettres manquantes dans les collines au nord de Long-Guet et rapportez-les à l’aubergiste Vizzie.",
    [93407] = "Trouvez des graines d’épineux dans les forêts du sommet du mont Hyjal et rapportez-les à Tiala Blanchetête.",
    [93422] = "Tuez la messagère noirépine et emparez-vous du message qu’elle porte.",
    [93429] = "Tuez 10 Perdus dans le sanctuaire des Friches.",
    [93430] = "Trouvez le pêcheur perdu qui a volé l’appât de Pelluk et récupérez ce dernier.",
    [93443] = "Rapportez la caisse perdue à Friz Faiblétincelle au port de Poudremèche, sur les rives Claires.",
    [93444] = "Tuez un sabre-de-nuit gardien. Avec sa carcasse, appâtez Ghansurok vers l’extrémité nord du pic et abattez-la. Revenez avec le cœur de la chimère.",
    [93450] = "Prenez l’épée inachevée de Vindael et trouvez le moyen de la convoyer dans le monde des esprits. Ensuite, rapportez-lui la lame fantasmatique, à Shen’dralas.",
    [93461] = "Parlez à Rathiril Lance-Solaire et Coriella Calmebrise à Shen’dar.",
    [93464] = "En Désolace, trouvez le mage qui connaît le pouvoir de la draenéthyste.",
    [93465] = "Emparez-vous des notes de Gimashi sur la draenéthyste et rapportez-les à Azore Aldamort.",
    [93510] = "Trouvez l’ancre du lac Placide, évoquée dans les souvenirs d’enfance du vétéran.",
    [93521] = "Rapportez les notes de recherche de Ve’han à Tiala Blanchetête.",
    [93546] = "Cherchez des gisements de fer spectral à Shen’dralas et collectez 10 morceaux de minerai de fer spectral. Retournez voir Vindael, à Shen’dralas, quand vous en aurez suffisamment.",
    [93547] = "Semez des graines d’épineux près de l’auberge, de la tour de stockage et du groupe d’arbres du camp des druides loyalistes.",
    [93551] = "Utilisez le fourreau brodé pour retrouver le vétéran de la Troisième guerre au mont Hyjal, près du canon brisé du Repos du deuil.",
    [93552] = "Récupérez 15 blocs de pierres de vent sur des pierres de vent brutes dans le bosquet de Thendal.",
    [93567] = "Écoutez l’histoire du vétéran de la Troisième guerre au canon brisé de Repos du deuil.",
    [93568] = "Rapportez le collier partiellement digéré à quelqu’un qui le reconnaît. Vous trouverez sans doute son propriétaire à l’intérieur ou dans les environs de Shen’dralas, en Désolace.",
    [93574] = "Trouvez quelqu’un intéressé par la carapace de Nécrobi.",
    [93584] = "Tuez 10 adeptes noirépines et 10 sectateurs marqués par la nature.",
    [93585] = "Escortez le père Tuttle jusqu’au havre Boueux.",
    [93594] = "Trouvez Astrebois dans les jardins Lugubres, à Shen’dralas, en Désolace.",
    [93601] = "Cherchez un Huran important dans la retraite de Dos-hirsute.",
    [93604] = "Rendez-vous aux souilles de Tranchebauge, récupérez du sang virulent d’Agamaggan, puis apportez-le à Kog’thug le Brave à la retraite des Dos-hirsute, en Désolace. Kog’thug a jugé nécessaire de vous rappeler que le simple sang d’Agamaggan du kraal de Tranchebauge ne serait pas suffisant.",
    [93606] = "Apaisez le conflit entre les Hurans en apportant un bouquet de bienfaisance et le sang virulent d’Agamaggan à Quolga. Vous trouverez de quoi faire un bouquet de fleurs dans les jardins Lugubres, près de Shen’dralas, en Désolace.",
    [93609] = "Apportez le collier de la mélancolie à Mithéra, au temple de Shen’dralas, en Désolace.",
    [93615] = "Trouvez les chatons de Shalla’kal sur les terres du mont Hyjal.",
    [93617] = "Dissuadez les cerfs d’agir en prédateurs.",
    [93644] = "Le texte semble suggérer que l’auteur du journal se trouve quelque part à Shen’dralas.",
    [93663] = "Trouvez le messager disparu et faites en sorte de livrer l’envoi de Dar au havre Boueux.",
    [93678] = "Apportez la transcription des notes d’Azore à Magtoor au havre Boueux dans le marais des Chagrins.",
    [93679] = "Observez la vision d’Onku avec Magtoor.",
    [93680] = "Récupérez la clé des égouts de Dalaran pour le magus Wordeen Toisevide à Moulin-de-Tarren.",
    [93684] = "Trouvez le Draeneï qui recherche de la draenéthyste dans les terres Foudroyées.",
    [93735] = "Trouvez Riaani Ventenuit dans la partie ouest de Valanaar.",
    [93736] = "Récupérez 10 essences de creux du vent sur les creux du vent de la forêt de Trombenoire.",
    [93737] = "Parlez à Riaani Ventenuit et écoutez ce qu’il a à dire.",
    [93738] = "Faites votre rapport à Ayessa Chantelaube à Valanaar.",
    [93739] = "Allez trouver Nazgrel au fort Grommash afin de recevoir de nouvelles instructions. Suivez ses indications pour retrouver Vol’jin, Cairne Sabot-de-Sang et dame Sylvanas Coursevent, puis entretenez-vous avec chacun d’eux.",
    [93740] = "Récupérez 10 charmes de pierre de vent sur les cadavres de sectateurs al’aketh dans les plaines Aérelles.",
    [93746] = "Confrontez Belathaan Voeu-Radieux sur la route qui mène au sanctuaire d’Akir.",
    [93747] = "Plantez les graines enchantées près de la baliste abîmée, de la catapulte abîmée et de la machine volante abîmée.",
    [93759] = "Récupérez 2 tranches de venaison d’Hyjal sur des cerfs d’Hyjal non corrompus et 6 tubercules-flèches écarlates pour le ragoût de l’ermite.",
    [93773] = "Faites votre rapport à Ketharas, au mont Hyjal.",
    [93786] = "Terrassez 12 journaliers de Ruissepré et retournez voir Krom’rosh pour l’informer de votre succès.",
    [93787] = "Volez 6 sacoches de nourriture à la ferme de l’Alliance à Ruissepré et retournez voir Krom’rosh.",
    [93788] = "Récupérez 10 haches d’abattage sur les bûcherons du camp de bûcherons de Turner pour Kreza Sombreronce, à Rog’mar.",
    [93791] = "Parlez à Belann Vif-Bois à Valanaar.",
    [93797] = "Apportez un rameau imprégné de vent à Belann Vif-Bois, à Valanaar.",
    [93825] = "Récoltez 12 touffes de mousse voile-de-lune et retournez voir Suma Crin-de-mousse.",
    [93826] = "Triomphez de 8 totémiques mort-bois et de 8 soigne-gangrène mort-bois avant de retourner voir l’ancien Parlepin.",
    [93827] = "Récupérez 16 amulette enchantée de harpie et retournez voir Thobon Griffesève.",
    [93828] = "Récoltez 10 lots d’herbes séchées suspendues dans la tanière des Peau-d’écorce et rapportez-les à Fennar Crin-de-mousse.",
    [93830] = "Remplissez l’outre que vous a donné Fennar Crin-de-mousse à la mare devant la tanière des Furbolgs mort-bois.",
    [93831] = "Cueillez 30 baies des ours sur le mont Hyjal et retournez voir Osi Patte-de-brume.",
    [93833] = "Rapportez 5 corps de chouette à l’ancien Parlepin dans le terrier des Peau-d’écorce sur Hyjal.",
    [93834] = "Rapportez 10 morceaux de hannetons fouisseurs à Dala Clairegueule.",
    [93835] = "Prenez le portail vers les hauteurs des flèches Rohashi et rejoignez Elaadrin Trombecalme et Ayessa Chantelaube dans leur confrontation avec la grande prêtresse Lorthuna.",
    [93836] = "Parlez à Talaanis Chantelombre à Valanaar.",
    [93848] = "Retournez voir Ketharas et informez-le de ce qui s’est passé au sommet d’Éternité.",
    [93926] = "Trouvez le garde-paix Vaaniel à la tour de guet occidentale.",
    [93927] = "Récupérez la note trouvée à proximité de la dépouille du garde-paix et lisez-la pour décider d’un plan d’action.",
    [93948] = "Apportez la chevalière de la famille Chantelombre à Talaanis Chantelombre, à Valaanar.",
    [93949] = "Tuez des sauteciels à Valanaar jusqu’à avoir éliminé 8 sauteciels enchantés.",
    [93951] = "Collectez 8 plumes de duvet d’hippogriffe dans les hautes-terres de Shen’dar.",
    [93952] = "Éliminez 9 garde-tanière mort-bois et retournez voir Brerufa",
    [93958] = "Parlez à Valennia Poing-Tempête dans le sanctum intérieur du sanctuaire d’Akir.",
    [93963] = "Allez trouver Randal Emerson au donjon de Hurlevent afin de recevoir de nouvelles instructions. Suivez ses indications pour retrouver le roi Magni Barbe-de-Bronze, le Grand Bricoleur Mekkanivelle et Tyrande Murmevent, puis entretenez-vous avec chacun d’eux.",
    [93976] = "Livrez la lame à la connaissance de Kreza Sombreronce sur les quais à l’est de Rog’mar.",
    [94003] = "Reprenez le Rempart des Briseciel à Zaal Pare-tempête au sanctuaire d’Akir.",
    [94004] = "Obtenez les objets demandés par le client et apportez-les à l’endroit indiqué sur votre carte. Ce document doit être en votre possession pour que la transaction soit validée.",
    [94006] = "Parlez avec Urs’endris près de la cascade au nord-est de Valanaar.",
    [94007] = "Présentez-vous à Quel’ana Vent-Vif à Valanaar.",
    [94013] = "Utilisez le bâtonnet de domptage pour dompter une alpha vuldrène des plaines Aérelles. Entraînez-vous à combattre à ses côtés, puis rapportez le bâtonnet de domptage à Quel’ana Vent-Vif à Valanaar.",
    [94050] = "Parlez à Quel’dora Vent-Vif à Valanaar.",
