    [96998] = "Apportez l’étui de peintures de guerre à quelqu’un qui pourrait le reconnaître.",
    [96999] = "Apportez l’étui de peintures de guerre à quelqu’un au village de Sen’jin.",
    [97000] = "Fouillez les camps de l’Alliance détruits d’Hyjal à la recherche de traces du père d’Abigail Sawyer, Lawrence.",
    [97001] = "Apportez le registre de la famille Sawyer à Abigail Sawyer dans le quartier de la Guerre de Fossoyeuse.",
    [97003] = "Rapportez la tête de Chol’aruk à Gur’ak dans les Tarides.",
    [97005] = "Rapportez la tête de Chol’aruk à Bainham dans les Tarides.",
    [97006] = "Apportez le registre de la famille Sawyer au surveillant royal Bauhaus dans le quartier des Marchands de Fossoyeuse.",
    [97007] = "Rendez le registre de la famille Sawyer notarié à Abigail Sawyer dans le quartier de la Guerre.",
    [97009] = "Apportez 12 pointes de gangrechiens à Maerion Thaelemaches à Dae’gun.",
    [97010] = "Grimpez au sommet de la tour des mages et lancez un éclat de rune explosive pour indiquer à Maerion Thaelemaches de lancer son attaque contre les démons.",
    [97017] = "Examinez les béliers de monte pour choisir votre première monture.",
    [97018] = "Apprenez la compétence Apprenti cavalier auprès d’Ultham Corne-de-fer.",
    [97022] = "Parlez à Danitha Morr à la forteresse de Bandarion.",
    [97045] = "Examinez les chevaux pour choisir votre première monture.",
    [97046] = "Examinez les mécanotrotteurs de monte pour choisir votre première monture.",
    [97047] = "Dans la base de Kurzen, trouvez la clé de la cage de Wendel ainsi qu’un déguisement pour lui permettre de s’évader.",
    [97048] = "Allez voir la capitaine Aransas à Baie-du-Butin.",
    [97049] = "Récupérez 8 essences de gelée suintante à la terrasse du Façonneur.",
    [97074] = "Apprendre la compétence Apprenti cavalier auprès de Jartsam.",
    [97119] = "Apportez 6 mini-burgers de cerf savoureux à Ortak Lomgok, à Sylvancienne.",
    [97130] = "Récupérez une idole antique des Gurubashi dans la cité Submergée.",
    [97168] = "Si vous voulez aider Eldrun Brise-tempête de Forgefer, apportez-lui un diamant d’Azeroth et un diamant noir en parfait état.",
    [97169] = "Servez-vous du clairvoyant au centre du sous-sol du Grand ossuaire de la Scholomance. Cela attirera des esprits que vous devrez combattre. Les vaincre fera apparaître le chevalier de la mort Ravassombre. Tuez-le. Rapportez la tête de Ravassombre à Eldrun Brise-tempête dans la caverne Lugubre de Forgefer.",
    [97170] = "Apprendre la compétence Apprenti cavalier auprès de Randal Hunter.",
    [97171] = "Examinez les chevaux pour choisir votre première monture.",
    [97173] = "Récupérez un totem rituel noiregueule au repaire des Noiregueules.",
    [97174] = "Parlez à Danitha Morr à la forteresse de Bandarion, dans les clairières de Tirisfal.",
    [97175] = "Rendez-vous à Orgrimmar et procurez-vous l’encensoir d’exorcisme du grand-prêtre Zayus. Vous devrez faire un don de 150 pièces d’or pour l’obtenir.",
    [97176] = "Servez-vous de l’encensoir d’exorcisme pour révéler les esprits tourmentés de Val-Terreur et les libérer de leurs tourments. Lorsque vous aurez délivré 25 esprits, retournez auprès de Danitha Morr à la forteresse de Bandarion dans les clairières de Tirisfal.",
    [97177] = "Rapportez l’encensoir d’exorcisme à Danitha Morr à la forteresse de Bandarion, dans les clairières de Tirisfal.",
    [97178] = "Parlez à Ott, à Moulin-de-Tarren, dans les contreforts de Hautebrande.",
    [97179] = "Apportez 40 échantillons d’étoffe runique, 6 barres d’arcanite, 10 larmes d’Arthas, 5 fioles d’eau sacrée de Stratholme et 150 pièces d’or à Ott dans les contreforts de Hautebrande.",
    [97182] = "Procurez-vous une nourriture spéciale destinée à nourrir un esprit équin. Nathanos le Flétrisseur, dans les Maleterres de l’Est, pourra peut-être vous en fournir. Rendez-vous à Hache-Tripes, en Féralas, et terrassez Tendris Crochebois. Sa mort libérera l’ancien esprit équin. Donnez-lui ensuite cette nourriture spéciale afin de l’apaiser. Enfin, présentez-lui le caparaçon en arcanite et espérez qu’il accepte de lui accorder la bénédiction dont il a besoin.",
    [97188] = "Apprendre la compétence Apprenti cavalier auprès de Binjy Siffleplume.",
    [97194] = "Apprendre la compétence Apprenti cavalier auprès de Kildar.",
    [97196] = "Récupérez l’œil du Porte-froid dans les souilles de Tranchebauge.",
    [97197] = "Récupérez un fragment des terres de Feu dans les profondeurs de Rochenoire pour Alaana Marchetempête, en Mulgore.",
    [97198] = "Récupérez un totem rituel noiregueule au repaire des Noiregueules.",
    [97200] = "Apprendre la compétence Apprenti cavalier auprès de Xar’Ti.",
    [97203] = "Apprendre la compétence Apprenti cavalier auprès de Velma Warnam.",
    [97204] = "Apprendre la compétence Apprenti cavalier auprès de Kar Chante-l’Orage.",
    [97205] = "Apprenez la compétence Apprenti cavalier auprès de Genn Beautemps.",
    [97220] = "Apportez la cargaison de la Conciergerie à l’entrée de la réserve des Fromages de Trias, dans le quartier commerçant.",
    [97222] = "Montez la livraison destinée au corps de garde à l’étage de la boutique de Trias et déposez-la devant la porte.",
    [97223] = "Apportez les œufs de la matriarche griffesang à Xar’Ti, au village de Sen’jin.",
    [97225] = "Récupérez 8 idoles de Loas oubliées sur les îles de l’Écho. Apportez-les au maître Gadrin, au village de Sen’jin.",
    [97234] = "Apportez le matériel de lecture enveloppé à la bibliothèque de Hurlevent.",
    [97236] = "Apportez le crochet de Githyiss à quelqu’un d’Aldrassil qui s’intéresse tout particulièrement à l’étude des araignées.",
    [97237] = "Trouvez les matériaux de lecture situés dans la bibliothèque et apportez-les à Roy Lewells, au parc de Hurlevent.",
    [97242] = "Prélevez des spécimens d’herbe polisson et de roseau qui poussent près des eaux de la vallée de l’Honneur et retournez voir Kor’geld à la boutique Alchimie et potions de Yelmak.",
    [97243] = "Apportez la torche de la flamme dormante à Olariaan Vivebrûle au sanctuaire des Flammes, dans les plaines Aérelles.",
    [97244] = "Tuez le prêtre céleste Faladiel dans les plaines Aérelles, puis récupérez son cœur.",
    [97245] = "Trouvez le repaire de Kuramaa dans les hautes-terres de Shen’dar et vainquez l’esprit au combat. Une fois victorieuse, rapportez le masque de Kuramaa à Olariaan Vivebrûle dans les plaines Aérelles.",
    [97246] = "Allez à la Fosse à feu de Borstan et dites à ce dernier que Thatog vous demande d’apporter son déjeuner à Migi.",
    [97249] = "Apportez son repas à Migi derrière le fort Grommash.",
    [97250] = "Tuez des soldats de l’Alliance qui empiètent sur les Tarides, à la frontière du marécage d’Âprefange. Puis retournez voir le grunt Logmar, au camp Taurajo.",
    [97253] = "Récupérez 5 poignées de pièces complexes au camp des pirates, au sud de Cabestan, puis retournez voir Wrenix le Misérable, à Cabestan.",
    [97257] = "Attendez qu’Olariaan commence le rituel au brasero d’offrande, puis suivez ses instructions. Vous devez remettre la flamme éternelle à Valanaar avant la fin du temps imparti.",
    [97263] = "Apportez le paquet égaré à Eldrun.",
    [97264] = "Éliminez 12 ours crocs acérés dans les zones environnantes, puis retournez voir Sarna Corne-Brune.",
    [97265] = "Éliminez différents Satyres fielfuries à Sargeron, en Désolace, puis retournez auprès d’Aka’rai au village de Proie-de-l’Ombre.",
    [97275] = "Apportez la potion de Yelmak à Whuut.",
    [97277] = "Trouvez le camp de Grund et Gozwin dans les collines du nord-ouest. Récupérez le journal de mécano de Gozwin et tuez le léopard des neiges rôdeur.",
    [97279] = "Récupérez 6 armes d’entraînement abandonnées, puis retournez auprès de Kzan Trancheronce, dans l’Antre.",
    [97281] = "Apportez l’orbe de tempête émoussé à Rezlak, près du ravin Asséché.",
    [97282] = "Apportez 5 organes de lézard-tonnerre chargés à Rezlak, près du ravin Asséché.",
    [97284] = "Éliminez des Orcs de la Lame ardente à la forteresse de Hache-Tonnerre, en Désolace, puis retournez auprès de Vahlarriel Tueur-de-démons à la combe de Nijel.",
    [97287] = "Allez parler à l’image de l’archimage Modera, près de Dalaran.",
    [97288] = "Apportez la tête abominable au maître apothicaire Faranell à Fossoyeuse.",
    [97289] = "Apportez la tête du baron au corps d’Othmar, à Fossoyeuse.",
    [97290] = "Faites votre rapport au maître apothicaire Faranell, à Fossoyeuse.",
    [97291] = "Récupérez un calot toxique auprès de Grisette Fauve dans le quartier des Marchands, de la cloquette auprès de la maîtresse des herboristes et de l’essence d’agonie auprès du marchand de poison du quartier des Voleurs, pour le maître apothicaire Faranell à Fossoyeuse.",
    [97292] = "Injectez le sérum sifflant dans le dispositif au-dessus du corps d’Othmar, pour le maître apothicaire Faranell.",
    [97319] = "Retrouvez le cousin disparu quelque part sur le mont Hyjal.",
    [97326] = "Rapportez 8 rochers lisses à Thra derrière le fort Grommash.",
    [97327] = "Entrez dans le repaire des Noiregueules et récupérez 5 bourses noiregueules pour Ekkal, qui se trouve dans les ruines d’Eldarath en Azshara.",
    [97328] = "Récupérez 8 cargaisons volées dans les ruines de Zul’Kunda, dans la vallée de Strangleronce, et apportez vos trouvailles à quelqu’un, à Baie-du-Butin.",
    [97329] = "Obtenez la clé primitive auprès des Trolls des ruines de Zul’Kunda, dans la vallée de Strangleronce, et apportez-la à Zimmix Krachétincelle.",
    [97331] = "Conduisez Zimmix Krachétincelle hors des ruines de Zul’Kunda, puis informez le maître des quais Lozouïe de votre sauvetage.",
    [97332] = "Apportez le paquet doublement renouvelé au maître des quais Sifflebruit, au port de Poudremèche, sur les rives Claires.",
    [97378] = "Apportez l’aile de Mirrécaille à Melor Sabot-de-Pierre, aux Pitons-du-Tonnerre.",
    [97386] = "Le commandant Aggro’gosh du campement Grom’gol vous demande de tuer des Ogres au tertre des Ogres mosh’Ogg.",
    [97403] = "Tuez 15 ravageurs noroît et retournez voir Rilan Howard dans le nord du Berceau-de-l’Hiver.",
    [97404] = "Tuez les vieilles matriarches crocs acérés Kuroma et Kamuro, puis rapportez leurs têtes à Sarna Corne-Brune.",
    [97405] = "Knaz Bourdeflamme vous demande de tuer 3 magiciens mosh’Ogg, 3 combattants mosh’Ogg, 3 marteleurs mosh'Ogg et 3 chamans mosh’Ogg au tertre des Ogres mosh’Ogg.",
    [97411] = "Procurez-vous 15 échantillons de venin de Silithus et 20 pièces d’or, et apportez-les avec une paire de brassards de Sancteforge à Mokvar, à Orgrimmar.",
    [97420] = "Récupérez 4 barils de pétrole brut auprès des installations de la KapitalRisk au lac Nazfériti, puis retournez voir Gnaz Bourdeflamme dans la vallée de Strangleronce.",
    [97447] = "Procurez-vous 15 échantillons de sang du Berceau-de-l’hiver et 20 pièces d’or, et apportez-les avec une paire de manchettes des éléments à Deliana, à Forgefer.",
    [97453] = "Tuez 6 herbes carnivores au sud de Grom’gol, puis informez la mère de Gemmil.",
    [97485] = "Achetez un paquet d’herbes à Nida l’herboriste, un fagot de brindilles de cèdre à Nata la fournisseuse de composants d’enchantements, des fibres tendineuses à Mahu le fournisseur de matériel de travail du cuir, ainsi que du silex et de l’amadou de cérémonie à Naal le fournisseur de matériel de cuisine. Combinez ces composants, puis répandez l’encens depuis la cime des Chasseurs.",
    [97490] = "Localisez un Géant appelé Vexegrêle dans les collines du sud du Berceau-de-l’Hiver et récupérez la mousse givrée qui pousse sur son corps.",
    [97530] = "Le chef de la sécurité Bilgewhizzle du port Gentepression en Tanaris veut que vous retrouviez un bracelet particulièrement brillant perdu près de la base des Ogres cognedunes.",
    [97534] = "Quinn vous demande de collecter 7 débris du désert et de les lui rapporter à Gadgetzan.",
    [97536] = "Jhordy Lapforge vous demande de jeter la caisse de déchets radioactifs dans le désert de Tanaris à bonne distance de Gadgetzan et des autres ordures, puis de retourner le voir.",
    [97538] = "Tah Sabot-d’Hiver des Pitons-du-Tonnerre voudrait obtenir 30 cosses de bourbielle au lac Mirkfallon.",
    [97539] = "Rapportez 12 soies d’araignée chirurgicales au docteur Gregory Victor au Trépas-d’Orgrim, dans les hautes-terres Arathies.",
    [97540] = "Tooga s’est désaltéré, montrez-lui le chemin du retour vers sa femme, Torta.",
    [97558] = "Apportez à Shelene Rhobart 8 membranes d’ailes de chauve-souris de la pénombre, 6 peaux de sombredogue et 3 peaux de Murloc aileron noir.",
    [97583] = "Achetez de la gelée nutritive et apportez-la à votre amie la gelée nerveuse. Si elle paraît fatiguée, essayez de danser avec elle pour attirer son attention.",
    [97617] = "Rapportez 8 artéfacts non étudiés, un casque de mineur de la Ligue des explorateurs et un piolet en parfait état à Dorgaron, à la frontière entre le Loch Modan et les terres Ingrates.",
    [97663] = "Éliminez des ogres dans la vallée de la Poussière afin de récupérer les fournitures volées de Mus’hale. Utilisez-les ensuite pour réaliser des reproductions des gravures sur pierre des environs, puis retournez auprès de Mus’hale à Kargath.",
    [97821] = "Trouvez quelqu’un dans les terres Ingrates qui s’intéresserait à cette découverte.",
    [97884] = "Rendez-vous à Clairsoleil, sur les rives Claires, et récupérez le tome des techniques de forge de la famille Tremayne.",
    [97891] = "Apportez la potion instable au docteur Martin Felben, à l’Apothicarium, avant la fin du temps imparti.",
    [97894] = "Prenez des nouvelles de Gorbold Main-d’acier à Auberdine, à Sombrivage. Borgus a parlé d’un bateau, au quai le plus au sud du port de Hurlevent, qui peut vous y emmener.",
    [97899] = "Parlez à Whuut, à Orgrimmar, pour apprendre à fabriquer un objet de camping propre à votre métier une fois que vous vous serez fait la main.",
    [97900] = "Parlez à Dwukk, à Tranchecolline, pour apprendre à fabriquer un objet de camping propre à votre métier une fois que vous vous serez fait la main.",
